/* TỰ SINH bởi tools/build-zh-game.mjs từ data/curriculum (giáo trình HSK của app ATLAS), đừng sửa tay. */
var G = window.G || (window.G = {});
G.ROOMS = G.ROOMS || {};
G.ROOMS["zh-l001"] = {"id":"zh-l001","lang":"zh","level":1,"no":1,"teacher":"wang","title":"HSK1 · Bài 1 · 你好 Xin chào","intro":["你好！","Bài 1: Chào hỏi, hỏi thăm sức khoẻ, nói \"tôi là…\" và phủ định bằng 不. Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ hǎo!","gram":{"t":"Câu khẳng định với 是 (là)","b":"A + 是 + B","d":"是 shì nghĩa là \"là\", dùng để nối hai danh từ. Khác tiếng Việt, tiếng Trung KHÔNG bỏ được 是 trong câu này.","ex":[["我是学生。","Tôi là học sinh.","Wǒ shì xuésheng."],["她是老师。","Cô ấy là giáo viên.","Tā shì lǎoshī."]]},"grams":[{"t":"Câu khẳng định với 是 (là)","b":"A + 是 + B","d":"是 shì nghĩa là \"là\", dùng để nối hai danh từ. Khác tiếng Việt, tiếng Trung KHÔNG bỏ được 是 trong câu này.","ex":[["我是学生。","Tôi là học sinh.","Wǒ shì xuésheng."],["她是老师。","Cô ấy là giáo viên.","Tā shì lǎoshī."]]},{"t":"Câu hỏi với 吗","b":"Câu kể + 吗 ?","d":"Muốn hỏi, chỉ cần thêm 吗 vào cuối câu kể. Trật tự từ GIỮ NGUYÊN, không đảo như tiếng Anh.","ex":[["你好吗？","Bạn khoẻ không?","Nǐ hǎo ma?"],["你是老师吗？","Bạn là giáo viên phải không?","Nǐ shì lǎoshī ma?"]]},{"t":"Phủ định với 不 và quy tắc biến điệu","b":"不 + động từ / tính từ","d":"不 đặt TRƯỚC động từ hoặc tính từ. Quan trọng: 不 vốn là thanh 4 (bù), nhưng khi đứng trước một chữ thanh 4 khác thì đổi thành thanh 2 (bú). Vì vậy 不是 đọc là bú shì chứ không phải bù shì.","ex":[["我不是老师。","Tôi không phải giáo viên.","Wǒ bú shì lǎoshī."],["我不好。","Tôi không khoẻ.","Wǒ bù hǎo."]]},{"t":"Tính từ cần có 很 đứng trước","b":"Chủ ngữ + 很 + tính từ","d":"Câu \"我好\" nghe cụt và có ý so sánh. Người Trung Quốc luôn nói 我很好. Ở đây 很 chỉ là từ đệm cho câu tròn, đừng dịch thành \"rất\".","ex":[["我很好。","Tôi khoẻ.","Wǒ hěn hǎo."]]}],"items":[{"zh":"你","py":"nǐ","vi":"bạn, cậu, anh, chị (ngôi thứ hai)","hv":"nễ","note":"Bên trái là bộ 亻 (người) — chữ nói về người. Muốn lịch sự với người lớn tuổi thì dùng 您 nín.","ex":"你好！","exPy":"Nǐ hǎo!","exVi":"Xin chào!","w":"你好！"},{"zh":"好","py":"hǎo","vi":"tốt, khoẻ, ổn","hv":"hảo","note":"女 (phụ nữ) + 子 (đứa con) = tốt đẹp. Người xưa cho rằng có mẹ có con là điều tốt lành nhất.","ex":"老师好！","exPy":"Lǎoshī hǎo!","exVi":"Em chào thầy/cô ạ!","w":"老师 好！"},{"zh":"我","py":"wǒ","vi":"tôi, tớ, mình","hv":"ngã","note":"Tiếng Việt có từ \"bản ngã\" — chính là chữ 我 này.","ex":"我很好，谢谢。","exPy":"Wǒ hěn hǎo, xièxie.","exVi":"Tôi khoẻ, cảm ơn.","w":"我 很 好， 谢谢。"},{"zh":"是","py":"shì","vi":"là","hv":"thị","note":"日 (mặt trời) ở trên. Đây là động từ \"là\" — nối hai danh từ với nhau.","ex":"我是学生。","exPy":"Wǒ shì xuésheng.","exVi":"Tôi là học sinh.","w":"我 是 学生。"},{"zh":"吗","py":"ma","vi":"(trợ từ đặt cuối câu để hỏi)","hv":"ma","note":"口 (miệng) + 马 (ngựa, cho âm đọc). Thêm 吗 vào cuối câu kể là thành câu hỏi. Đọc nhẹ, không có thanh điệu.","ex":"你好吗？","exPy":"Nǐ hǎo ma?","exVi":"Bạn khoẻ không?","w":"你好 吗？"},{"zh":"不","py":"bù","vi":"không","hv":"bất","note":"Tiếng Việt có \"bất lịch sự\", \"bất công\" — đều là chữ 不 này.","ex":"我不是老师。","exPy":"Wǒ bú shì lǎoshī.","exVi":"Tôi không phải giáo viên.","w":"我 不 是 老师。"},{"zh":"很","py":"hěn","vi":"rất","hv":"ngận","note":"Trong tiếng Trung, 很 thường chỉ là từ đệm bắt buộc trước tính từ, KHÔNG mang nghĩa \"rất\" mạnh như tiếng Việt.","ex":"他很好。","exPy":"Tā hěn hǎo.","exVi":"Anh ấy khoẻ.","w":"他 很 好。"},{"zh":"谢谢","py":"xièxie","vi":"cảm ơn","hv":"tạ tạ","note":"Tiếng Việt có \"cảm tạ\" — chính là chữ 谢. Chữ thứ hai đọc nhẹ (khinh thanh).","ex":"谢谢老师！","exPy":"Xièxie lǎoshī!","exVi":"Cảm ơn thầy/cô!","w":"谢谢 老师！"},{"zh":"再见","py":"zàijiàn","vi":"tạm biệt","hv":"tái kiến","note":"再 (lại) + 见 (gặp) = \"gặp lại\". Giống hệt \"tái kiến\" trong tiếng Việt.","ex":"老师，再见！","exPy":"Lǎoshī, zàijiàn!","exVi":"Thưa thầy/cô, em về ạ!","w":"老师， 再见！"},{"zh":"老师","py":"lǎoshī","vi":"thầy giáo, cô giáo","hv":"lão sư","note":"老 (già, kính trọng) + 师 (thầy). Tiếng Việt gọi là \"lão sư\" trong từ Hán Việt.","ex":"你是老师吗？","exPy":"Nǐ shì lǎoshī ma?","exVi":"Bạn là giáo viên à?","w":"你 是 老师 吗？"}],"newChars":["你","好","我","是","吗","不","很","谢","再","见","老","师"],"outro":"很好！Xong bài 1."};
G.ROOMS["zh-l002"] = {"id":"zh-l002","lang":"zh","level":1,"no":2,"teacher":"wang","title":"HSK1 · Bài 2 · 你叫什么名字？ Bạn tên là gì?","intro":["你叫什么名字？","Bài 2: Hỏi và nói tên, giới thiệu người khác, dùng 呢 để hỏi lại. Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ jiào shénme míngzi?","gram":{"t":"Hỏi tên bằng 叫","b":"你 + 叫 + 什么名字？ → 我 + 叫 + tên","d":"Đây là mẫu câu hỏi tên chuẩn mực nhất. Trả lời chỉ cần thay 什么名字 bằng tên của mình, trật tự giữ nguyên.","ex":[["你叫什么名字？","Bạn tên là gì?","Nǐ jiào shénme míngzi?"],["我叫阿英。","Tôi tên là A Anh.","Wǒ jiào Ā Yīng."]]},"grams":[{"t":"Hỏi tên bằng 叫","b":"你 + 叫 + 什么名字？ → 我 + 叫 + tên","d":"Đây là mẫu câu hỏi tên chuẩn mực nhất. Trả lời chỉ cần thay 什么名字 bằng tên của mình, trật tự giữ nguyên.","ex":[["你叫什么名字？","Bạn tên là gì?","Nǐ jiào shénme míngzi?"],["我叫阿英。","Tôi tên là A Anh.","Wǒ jiào Ā Yīng."]]},{"t":"Câu hỏi có từ để hỏi thì KHÔNG dùng 吗","b":"什么 / 谁 / 哪儿 … (không có 吗)","d":"Đây là lỗi kinh điển của người mới. Đã có 什么 thì tuyệt đối không thêm 吗 vào cuối câu. Nói \"你叫什么名字吗?\" là SAI.","ex":[["你叫什么名字？","ĐÚNG","Nǐ jiào shénme míngzi?"],["这是什么？","Đây là cái gì?","Zhè shì shénme?"]]},{"t":"Hỏi lại bằng 呢","b":"A + 呢 ?","d":"Thay vì lặp lại cả câu hỏi dài, chỉ cần nêu đối tượng rồi thêm 呢. Giống \"còn bạn thì sao?\" trong tiếng Việt.","ex":[["我很好，你呢？","Tôi khoẻ, còn bạn?","Wǒ hěn hǎo, nǐ ne?"],["我是学生，他呢？","Tôi là học sinh, còn cậu ấy?","Wǒ shì xuésheng, tā ne?"]]}],"items":[{"zh":"他","py":"tā","vi":"anh ấy, ông ấy, cậu ấy","hv":"tha","note":"亻 (người) + 也. Dùng cho nam giới, hoặc khi chưa rõ giới tính.","ex":"他叫什么名字？","exPy":"Tā jiào shénme míngzi?","exVi":"Cậu ấy tên là gì?","w":"他 叫 什么 名字？"},{"zh":"她","py":"tā","vi":"cô ấy, chị ấy, bà ấy","hv":"tha","note":"女 (phụ nữ) + 也. Đọc HỆT như 他 — chỉ khác khi VIẾT. Đây là điểm dễ sai của người mới.","ex":"她是学生吗？","exPy":"Tā shì xuésheng ma?","exVi":"Cô ấy là học sinh à?","w":"她 是 学生 吗？"},{"zh":"叫","py":"jiào","vi":"gọi là, tên là","hv":"khiếu","note":"口 (miệng) + 丩. Việc gọi tên thì phải dùng miệng.","ex":"你叫什么名字？","exPy":"Nǐ jiào shénme míngzi?","exVi":"Bạn tên là gì?","w":"你 叫 什么 名字？"},{"zh":"什么","py":"shénme","vi":"cái gì, gì","hv":"thập ma","note":"Chữ thứ hai đọc nhẹ. Câu có 什么 thì KHÔNG được thêm 吗 nữa.","ex":"这是什么？","exPy":"Zhè shì shénme?","exVi":"Đây là cái gì?","w":"这 是 什么？"},{"zh":"名字","py":"míngzi","vi":"tên","hv":"danh tự","note":"名 (danh) + 字 (tự). Tiếng Việt có \"danh tính\", \"chữ ký\" — cùng gốc.","ex":"你叫什么名字？","exPy":"Nǐ jiào shénme míngzi?","exVi":"Bạn tên là gì?","w":"你 叫 什么 名字？"},{"zh":"呢","py":"ne","vi":"(trợ từ: còn… thì sao?)","hv":"ni","note":"Dùng để hỏi ngược lại mà không phải nhắc lại cả câu. Rất hay dùng trong hội thoại.","ex":"我叫小明，你呢？","exPy":"Wǒ jiào Xiǎomíng, nǐ ne?","exVi":"Tôi tên Tiểu Minh, còn bạn?","w":"我 叫 小 明， 你 呢？"},{"zh":"请","py":"qǐng","vi":"mời, xin vui lòng","hv":"thỉnh","note":"讠 (lời nói) + 青. Tiếng Việt có \"thỉnh cầu\", \"thỉnh giảng\".","ex":"请问，你是老师吗？","exPy":"Qǐngwèn, nǐ shì lǎoshī ma?","exVi":"Xin hỏi, bạn là giáo viên phải không?","w":"请问， 你 是 老师 吗？"},{"zh":"认识","py":"rènshi","vi":"quen biết, nhận ra","hv":"nhận thức","note":"Đúng là từ \"nhận thức\" trong tiếng Việt, nhưng nghĩa tiếng Trung là QUEN BIẾT một người.","ex":"我认识她。","exPy":"Wǒ rènshi tā.","exVi":"Tôi quen cô ấy.","w":"我 认识 她。"},{"zh":"高兴","py":"gāoxìng","vi":"vui, vui mừng","hv":"cao hứng","note":"Tiếng Việt \"cao hứng\" nghĩa hơi khác; tiếng Trung 高兴 đơn giản là VUI.","ex":"认识你很高兴。","exPy":"Rènshi nǐ hěn gāoxìng.","exVi":"Rất vui được quen bạn.","w":"认识 你 很 高兴。"},{"zh":"学生","py":"xuésheng","vi":"học sinh, sinh viên","hv":"học sinh","note":"Giống hệt \"học sinh\" tiếng Việt. 学 (học) + 生 (sinh).","ex":"她不是学生，她是老师。","exPy":"Tā bú shì xuésheng, tā shì lǎoshī.","exVi":"Cô ấy không phải học sinh, cô ấy là giáo viên.","w":"她 不 是 学生， 她 是 老师。"}],"newChars":["他","她","叫","什","么","名","字","呢","请","认","识","高","兴","学","生"],"outro":"很好！Xong bài 2."};
G.ROOMS["zh-l003"] = {"id":"zh-l003","lang":"zh","level":1,"no":3,"teacher":"wang","title":"HSK1 · Bài 3 · 数字 Con số","intro":["一、二、三、四、五。","Bài 3: Đếm từ 1 đến 99, hiểu quy tắc biến điệu của 一, và nhận ra 10 chữ số Hán Việt quen thuộc. Bấm 1 · Học để bắt đầu."],"introPy":"Yī, èr, sān, sì, wǔ.","gram":{"t":"Đếm từ 11 đến 99 — logic hơn tiếng Việt","b":"11 = 十一 · 20 = 二十 · 25 = 二十五 · 99 = 九十九","d":"Quy tắc cực đơn giản: số hàng chục ĐỨNG TRƯỚC 十, số hàng đơn vị ĐỨNG SAU. Không có ngoại lệ kiểu \"mười lăm / hai mươi lăm\" như tiếng Việt.","ex":[["十一","11","shíyī"],["三十","30","sānshí"],["四十七","47","sìshíqī"],["九十九","99","jiǔshíjiǔ"]]},"grams":[{"t":"Đếm từ 11 đến 99 — logic hơn tiếng Việt","b":"11 = 十一 · 20 = 二十 · 25 = 二十五 · 99 = 九十九","d":"Quy tắc cực đơn giản: số hàng chục ĐỨNG TRƯỚC 十, số hàng đơn vị ĐỨNG SAU. Không có ngoại lệ kiểu \"mười lăm / hai mươi lăm\" như tiếng Việt.","ex":[["十一","11","shíyī"],["三十","30","sānshí"],["四十七","47","sìshíqī"],["九十九","99","jiǔshíjiǔ"]]},{"t":"Biến điệu của 一 — quy tắc bắt buộc phải thuộc","b":"一 đứng một mình = yī · trước thanh 1,2,3 = yì · trước thanh 4 = yí","d":"Chữ 一 đổi thanh điệu tuỳ theo chữ đứng sau nó. Khi đếm số hoặc đứng cuối thì vẫn giữ yī. Đây là điểm người Việt hay bỏ qua nhưng người bản xứ nghe ra ngay.","ex":[["一、二、三","đếm số → giữ yī","yī, èr, sān"],["一天","một ngày (天 thanh 1 → yì)","yì tiān"],["一个","một cái (个 thanh 4 → yí)","yí ge"]]},{"t":"Số + lượng từ + danh từ","b":"Số + 个 + danh từ","d":"Tiếng Trung KHÔNG nói \"ba người\" trực tiếp, mà bắt buộc chèn lượng từ vào giữa, giống tiếng Việt nói \"ba NGƯỜI khách\", \"năm CÁI bàn\". Lượng từ vạn năng là 个 ge.","ex":[["三个人","ba người","sān ge rén"],["十个学生","mười học sinh","shí ge xuésheng"]]}],"items":[{"zh":"一","py":"yī","vi":"một","hv":"nhất","note":"Một nét ngang duy nhất. Viết TRÁI sang PHẢI. Tiếng Việt: \"đệ nhất\", \"thống nhất\".","ex":"一、二、三、四、五。","exPy":"Yī, èr, sān, sì, wǔ.","exVi":"Một, hai, ba, bốn, năm.","w":"一、 二、 三、 四、 五。"},{"zh":"二","py":"èr","vi":"hai","hv":"nhị","note":"Hai nét ngang, nét dưới DÀI hơn. Tiếng Việt: \"nhị phân\", \"độc nhất vô nhị\".","ex":"十一、十二、十三。","exPy":"Shíyī, shí'èr, shísān.","exVi":"Mười một, mười hai, mười ba.","w":"十 一、 十 二、 十 三。"},{"zh":"三","py":"sān","vi":"ba","hv":"tam","note":"Ba nét ngang, nét dưới cùng dài nhất. Tiếng Việt: \"tam giác\", \"tam quốc\".","ex":"二十、三十、四十。","exPy":"Èrshí, sānshí, sìshí.","exVi":"Hai mươi, ba mươi, bốn mươi.","w":"二 十、 三 十、 四 十。"},{"zh":"四","py":"sì","vi":"bốn","hv":"tứ","note":"Người Trung Quốc kiêng số 4 vì đọc gần giống 死 sǐ (chết). Tiếng Việt: \"tứ giác\", \"tứ phương\".","ex":"四个人","exPy":"sì ge rén","exVi":"bốn người","w":"四 个人"},{"zh":"五","py":"wǔ","vi":"năm","hv":"ngũ","note":"Tiếng Việt: \"ngũ cốc\", \"ngũ quan\", \"ngũ hành\".","ex":"五加五是十。","exPy":"Wǔ jiā wǔ shì shí.","exVi":"Năm cộng năm là mười.","w":"五 加 五 是 十。"},{"zh":"六","py":"liù","vi":"sáu","hv":"lục","note":"Số may mắn, vì 六六大顺 nghĩa là mọi việc thuận lợi. Tiếng Việt: \"lục địa\", \"lục bát\".","ex":"六、七、八、九、十。","exPy":"Liù, qī, bā, jiǔ, shí.","exVi":"Sáu, bảy, tám, chín, mười.","w":"六、 七、 八、 九、 十。"},{"zh":"七","py":"qī","vi":"bảy","hv":"thất","note":"Tiếng Việt: \"thất tình\" (bảy loại cảm xúc), \"thất bảo\".","ex":"七个","exPy":"qī ge","exVi":"bảy cái","w":"七 个"},{"zh":"八","py":"bā","vi":"tám","hv":"bát","note":"Số được yêu thích nhất vì 八 bā nghe giống 发 fā (phát tài). Tiếng Việt: \"bát giác\", \"bát quái\".","ex":"八个人","exPy":"bā ge rén","exVi":"tám người","w":"八 个人"},{"zh":"九","py":"jiǔ","vi":"chín","hv":"cửu","note":"Tiếng Việt: \"cửu long\" (chín rồng), \"cửu trùng\".","ex":"九十九个人。","exPy":"Jiǔshíjiǔ ge rén.","exVi":"Chín mươi chín người.","w":"九 十 九 个人。"},{"zh":"十","py":"shí","vi":"mười","hv":"thập","note":"Ngang trước, sổ sau. Tiếng Việt: \"thập niên\", \"thập toàn thập mỹ\".","ex":"我们班有二十个学生。","exPy":"Wǒmen bān yǒu èrshí ge xuésheng.","exVi":"Lớp chúng tôi có hai mươi học sinh.","w":"我们 班 有 二 十 个 学生。"}],"newChars":["一","二","三","四","五","六","七","八","九","十"],"outro":"很好！Xong bài 3."};
G.ROOMS["zh-l004"] = {"id":"zh-l004","lang":"zh","level":1,"no":4,"teacher":"wang","title":"HSK1 · Bài 4 · 我的家 Gia đình tôi","intro":["你家有几个人？","Bài 4: Nói về gia đình, dùng 有 / 没有 để nói có và không có, dùng 的 để chỉ sở hữu. Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ jiā yǒu jǐ ge rén?","gram":{"t":"有 và 没有 — cặp đặc biệt","b":"Khẳng định: A + 有 + B · Phủ định: A + 没有 + B","d":"Mọi động từ khác đều phủ định bằng 不, RIÊNG 有 phải dùng 没. Nói 不有 là sai hoàn toàn. Hãy học thuộc cặp 有 / 没有 như một khối.","ex":[["我有两个孩子。","Tôi có hai đứa con.","Wǒ yǒu liǎng ge háizi."],["我没有孩子。","Tôi không có con.","Wǒ méiyǒu háizi."]]},"grams":[{"t":"有 và 没有 — cặp đặc biệt","b":"Khẳng định: A + 有 + B · Phủ định: A + 没有 + B","d":"Mọi động từ khác đều phủ định bằng 不, RIÊNG 有 phải dùng 没. Nói 不有 là sai hoàn toàn. Hãy học thuộc cặp 有 / 没有 như một khối.","ex":[["我有两个孩子。","Tôi có hai đứa con.","Wǒ yǒu liǎng ge háizi."],["我没有孩子。","Tôi không có con.","Wǒ méiyǒu háizi."]]},{"t":"的 chỉ sở hữu — và khi nào được bỏ","b":"Người sở hữu + 的 + vật sở hữu","d":"我的书 = sách của tôi. Nhưng với NGƯỜI THÂN và NƠI CHỐN GẦN GŨI thì thường BỎ 的: 我妈妈 (mẹ tôi), 我家 (nhà tôi) — nghe tự nhiên hơn 我的妈妈.","ex":[["我的名字","tên của tôi","wǒ de míngzi"],["我妈妈","mẹ tôi (bỏ 的)","wǒ māma"],["老师的书","sách của thầy","lǎoshī de shū"]]},{"t":"Hỏi số lượng người trong nhà","b":"你家有几个人？","d":"几 dùng để hỏi số lượng nhỏ (dưới 10). Trả lời chỉ cần thay 几 bằng con số, giữ nguyên trật tự.","ex":[["你家有几个人？","Nhà bạn có mấy người?","Nǐ jiā yǒu jǐ ge rén?"],["我家有四个人。","Nhà tôi có bốn người.","Wǒ jiā yǒu sì ge rén."]]}],"items":[{"zh":"爸爸","py":"bàba","vi":"bố, ba","hv":"ba ba","note":"父 (phụ, người cha) ở trên + 巴 cho âm đọc. Chữ thứ hai đọc nhẹ.","ex":"爸爸、妈妈、我和弟弟。","exPy":"Bàba, māma, wǒ hé dìdi.","exVi":"Bố, mẹ, tôi và em trai.","w":"爸爸、 妈妈、 我 和 弟弟。"},{"zh":"妈妈","py":"māma","vi":"mẹ, má","hv":"ma ma","note":"女 (phụ nữ) + 马 (mã, cho âm đọc). Thấy bộ 女 là biết chữ nói về nữ giới.","ex":"我妈妈不是老师。","exPy":"Wǒ māma bú shì lǎoshī.","exVi":"Mẹ tôi không phải giáo viên.","w":"我 妈妈 不 是 老师。"},{"zh":"儿子","py":"érzi","vi":"con trai","hv":"nhi tử","note":"儿 (nhi, trẻ con) + 子 (tử, con). Tiếng Việt có \"nhi đồng\", \"phụ tử\".","ex":"他有一个儿子和一个女儿。","exPy":"Tā yǒu yí ge érzi hé yí ge nǚ'ér.","exVi":"Anh ấy có một con trai và một con gái.","w":"他 有 一 个 儿子 和 一 个 女儿。"},{"zh":"女儿","py":"nǚ'ér","vi":"con gái","hv":"nữ nhi","note":"Chính là \"nữ nhi\" trong tiếng Việt. Pinyin có dấu ngăn cách nǚ'ér để không đọc nhầm thành nǚr.","ex":"我没有女儿。","exPy":"Wǒ méiyǒu nǚ'ér.","exVi":"Tôi không có con gái.","w":"我 没有 女儿。"},{"zh":"家","py":"jiā","vi":"nhà, gia đình","hv":"gia","note":"宀 (mái nhà) trùm lên 豕 (con lợn). Nhà xưa nuôi lợn dưới sàn — có lợn mới là có nhà. Tiếng Việt: \"gia đình\", \"gia tộc\".","ex":"你家有几个人？","exPy":"Nǐ jiā yǒu jǐ ge rén?","exVi":"Nhà bạn có mấy người?","w":"你 家 有 几 个人？"},{"zh":"人","py":"rén","vi":"người","hv":"nhân","note":"Hình người đứng nhìn nghiêng, hai chân dang ra. Tiếng Việt: \"nhân dân\", \"cá nhân\".","ex":"我家有四个人。","exPy":"Wǒ jiā yǒu sì ge rén.","exVi":"Nhà tôi có bốn người.","w":"我 家 有 四 个人。"},{"zh":"的","py":"de","vi":"(trợ từ sở hữu: của)","hv":"đích","note":"Chữ XUẤT HIỆN NHIỀU NHẤT trong tiếng Trung. Đọc nhẹ, không thanh điệu.","ex":"这是我的名字。","exPy":"Zhè shì wǒ de míngzi.","exVi":"Đây là tên của tôi.","w":"这 是 我 的 名字。"},{"zh":"个","py":"gè","vi":"cái, người (lượng từ vạn năng)","hv":"cá","note":"Khi đứng sau số thì thường đọc nhẹ thành ge. Không biết dùng lượng từ nào thì cứ dùng 个.","ex":"我家有一个人是医生。","exPy":"Wǒ jiā yǒu yí ge rén shì yīshēng.","exVi":"Nhà tôi có một người là bác sĩ.","w":"我 家 有 一 个人 是 医生。"},{"zh":"有","py":"yǒu","vi":"có","hv":"hữu","note":"Tiếng Việt: \"sở hữu\", \"hữu ích\", \"quốc hữu\".","ex":"我没有儿子。","exPy":"Wǒ méiyǒu érzi.","exVi":"Tôi không có con trai.","w":"我 没有 儿子。"},{"zh":"没有","py":"méiyǒu","vi":"không có","hv":"một hữu","note":"CỰC KỲ QUAN TRỌNG: 有 là động từ DUY NHẤT không phủ định bằng 不. Phải nói 没有, tuyệt đối không nói 不有.","ex":"我没有钱。","exPy":"Wǒ méiyǒu qián.","exVi":"Tôi không có tiền.","w":"我 没有 钱。"}],"newChars":["爸","妈","儿","子","女","家","人","的","个","有","没"],"outro":"很好！Xong bài 4."};
G.ROOMS["zh-l005"] = {"id":"zh-l005","lang":"zh","level":1,"no":5,"teacher":"wang","title":"HSK1 · Bài 5 · 朋友和工作 Bạn bè và công việc","intro":["我们都是学生。","Bài 5: Giới thiệu bạn bè và nghề nghiệp, dùng 都 (đều), nói về quốc tịch và tiếng Trung. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒmen dōu shì xuésheng.","gram":{"t":"Vị trí của 都 — sau chủ ngữ, trước động từ","b":"Chủ ngữ + 都 + động từ / tính từ","d":"Đây là lỗi rất phổ biến. Người Việt hay đặt 都 lên đầu câu vì tiếng Việt nói \"Tất cả chúng tôi…\". Trong tiếng Trung 都 BẮT BUỘC đứng sau chủ ngữ.","ex":[["我们都是学生。","ĐÚNG — Chúng tôi đều là học sinh.","Wǒmen dōu shì xuésheng."],["他们都很好。","Họ đều khoẻ.","Tāmen dōu hěn hǎo."],["我们都不是老师。","Chúng tôi đều không phải giáo viên.","Wǒmen dōu bú shì lǎoshī."]]},"grams":[{"t":"Vị trí của 都 — sau chủ ngữ, trước động từ","b":"Chủ ngữ + 都 + động từ / tính từ","d":"Đây là lỗi rất phổ biến. Người Việt hay đặt 都 lên đầu câu vì tiếng Việt nói \"Tất cả chúng tôi…\". Trong tiếng Trung 都 BẮT BUỘC đứng sau chủ ngữ.","ex":[["我们都是学生。","ĐÚNG — Chúng tôi đều là học sinh.","Wǒmen dōu shì xuésheng."],["他们都很好。","Họ đều khoẻ.","Tāmen dōu hěn hǎo."],["我们都不是老师。","Chúng tôi đều không phải giáo viên.","Wǒmen dōu bú shì lǎoshī."]]},{"t":"Nói quốc tịch: Tên nước + 人","b":"Tên nước + 人","d":"Chỉ cần ghép chữ 人 (người) vào sau tên nước. Không cần thêm gì khác. Giống hệt cách nói \"người Việt Nam\", \"người Trung Quốc\".","ex":[["中国人","người Trung Quốc","Zhōngguó rén"],["越南人","người Việt Nam","Yuènán rén"],["我是越南人。","Tôi là người Việt Nam.","Wǒ shì Yuènán rén."]]},{"t":"Xưng hô: họ đứng TRƯỚC danh xưng","b":"Họ + 先生 / 小姐 / 老师","d":"Ngược hoàn toàn với tiếng Việt. Ta nói \"ông Vương\", tiếng Trung nói 王先生 (Vương + ông). Người Trung Quốc cũng viết họ trước tên.","ex":[["王先生","ông Vương","Wáng xiānsheng"],["李老师","thầy Lý / cô Lý","Lǐ lǎoshī"]]}],"items":[{"zh":"朋友","py":"péngyou","vi":"bạn, bạn bè","hv":"bằng hữu","note":"Chính là \"bằng hữu\" trong tiếng Việt. Hai chữ 月 ghép lại — vốn là hình hai chuỗi vỏ sò buộc chung.","ex":"他们都是我的朋友。","exPy":"Tāmen dōu shì wǒ de péngyou.","exVi":"Họ đều là bạn của tôi.","w":"他们 都 是 我 的 朋友。"},{"zh":"同学","py":"tóngxué","vi":"bạn cùng lớp, bạn học","hv":"đồng học","note":"同 (đồng, cùng) + 学 (học). Thầy cô Trung Quốc gọi học sinh là 同学 thay vì gọi tên.","ex":"我们是同学，也是朋友。","exPy":"Wǒmen shì tóngxué, yě shì péngyou.","exVi":"Chúng tôi là bạn cùng lớp, cũng là bạn bè.","w":"我们 是 同学， 也 是 朋友。"},{"zh":"先生","py":"xiānsheng","vi":"ông, ngài, anh (lịch sự); chồng","hv":"tiên sinh","note":"Đặt SAU họ: 王先生 = ông Vương. Ngược với tiếng Việt (\"ông Vương\").","ex":"王先生是医生吗？","exPy":"Wáng xiānsheng shì yīshēng ma?","exVi":"Ông Vương là bác sĩ à?","w":"王 先生 是 医生 吗？"},{"zh":"小姐","py":"xiǎojiě","vi":"cô, tiểu thư","hv":"tiểu tỷ","note":"Âm Hán Việt đúng là “tiểu tỷ” (姐 = tỷ); tiếng Việt quen gọi là “tiểu thư”. Cũng đặt sau họ: 李小姐 = cô Lý. Lưu ý ở Trung Quốc đại lục nay ít dùng vì có nghĩa xấu; nên dùng 女士 nǚshì.","ex":"她是李小姐。","exPy":"Tā shì Lǐ xiǎojiě.","exVi":"Cô ấy là cô Lý.","w":"她 是 李 小姐。"},{"zh":"医生","py":"yīshēng","vi":"bác sĩ","hv":"y sinh","note":"医 (y) + 生 (sinh). Tiếng Việt có \"y sĩ\", \"y tế\", \"y học\".","ex":"他不是医生，他是老师。","exPy":"Tā bú shì yīshēng, tā shì lǎoshī.","exVi":"Ông ấy không phải bác sĩ, ông ấy là giáo viên.","w":"他 不 是 医生， 他 是 老师。"},{"zh":"工作","py":"gōngzuò","vi":"công việc; làm việc","hv":"công tác","note":"Giống hệt \"công tác\" tiếng Việt. Vừa là danh từ (công việc) vừa là động từ (làm việc).","ex":"你的工作是什么？","exPy":"Nǐ de gōngzuò shì shénme?","exVi":"Công việc của bạn là gì?","w":"你 的 工作 是 什么？"},{"zh":"都","py":"dōu","vi":"đều, tất cả","hv":"đô","note":"Luôn đứng SAU chủ ngữ, TRƯỚC động từ. Không bao giờ đứng đầu câu.","ex":"我们都是学生。","exPy":"Wǒmen dōu shì xuésheng.","exVi":"Chúng tôi đều là học sinh.","w":"我们 都 是 学生。"},{"zh":"我们","py":"wǒmen","vi":"chúng tôi, chúng ta","hv":"ngã môn","note":"们 men là hậu tố số nhiều cho NGƯỜI: 你们 (các bạn), 他们 (họ). Không dùng cho đồ vật.","ex":"我们都学习汉语。","exPy":"Wǒmen dōu xuéxí Hànyǔ.","exVi":"Chúng tôi đều học tiếng Trung.","w":"我们 都 学习 汉语。"},{"zh":"中国","py":"Zhōngguó","vi":"Trung Quốc","hv":"Trung Quốc","note":"中 (trung, giữa) + 国 (quốc, nước) = \"nước ở giữa\". Đúng là \"Trung Quốc\" tiếng Việt.","ex":"我是越南人，他是中国人。","exPy":"Wǒ shì Yuènán rén, tā shì Zhōngguó rén.","exVi":"Tôi là người Việt Nam, anh ấy là người Trung Quốc.","w":"我 是 越 南 人， 他 是 中国 人。"},{"zh":"汉语","py":"Hànyǔ","vi":"tiếng Trung, tiếng Hán","hv":"Hán ngữ","note":"汉 (Hán) + 语 (ngữ). Tiếng Việt gọi là \"Hán ngữ\". Còn gọi là 中文 Zhōngwén.","ex":"我学习汉语。","exPy":"Wǒ xuéxí Hànyǔ.","exVi":"Tôi học tiếng Trung.","w":"我 学习 汉语。"}],"newChars":["朋","友","同","先","小","姐","医","工","作","都","们","中","国","汉","语"],"outro":"很好！Xong bài 5."};
G.ROOMS["zh-l006"] = {"id":"zh-l006","lang":"zh","level":1,"no":6,"teacher":"wang","title":"HSK1 · Bài 6 · 学习汉语 Học tiếng Trung","intro":["我学习汉语。","Bài 6: Nói về việc học, dùng 会 (biết làm), phân biệt 看 / 读 / 听 / 写 và cấu trúc động-tân. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒ xuéxí Hànyǔ.","gram":{"t":"会 — biết một kỹ năng đã học","b":"Chủ ngữ + 会 + động từ · Phủ định: 不会","d":"会 dùng cho kỹ năng phải HỌC mới có: nói ngoại ngữ, bơi, lái xe, nấu ăn. Nếu chỉ là \"có điều kiện làm\" thì dùng 能 (bài 8).","ex":[["我会说汉语。","Tôi biết nói tiếng Trung.","Wǒ huì shuō Hànyǔ."],["我不会写这个字。","Tôi không biết viết chữ này.","Wǒ bú huì xiě zhège zì."],["你会说汉语吗？","Bạn biết nói tiếng Trung không?","Nǐ huì shuō Hànyǔ ma?"]]},"grams":[{"t":"会 — biết một kỹ năng đã học","b":"Chủ ngữ + 会 + động từ · Phủ định: 不会","d":"会 dùng cho kỹ năng phải HỌC mới có: nói ngoại ngữ, bơi, lái xe, nấu ăn. Nếu chỉ là \"có điều kiện làm\" thì dùng 能 (bài 8).","ex":[["我会说汉语。","Tôi biết nói tiếng Trung.","Wǒ huì shuō Hànyǔ."],["我不会写这个字。","Tôi không biết viết chữ này.","Wǒ bú huì xiě zhège zì."],["你会说汉语吗？","Bạn biết nói tiếng Trung không?","Nǐ huì shuō Hànyǔ ma?"]]},{"t":"Trật tự cơ bản: Chủ ngữ - Động từ - Tân ngữ","b":"Ai + làm gì + cái gì","d":"Tiếng Trung có trật tự giống hệt tiếng Việt: 我(tôi) 看(xem) 书(sách). Đây là lợi thế lớn của người Việt khi học tiếng Trung so với người phương Tây.","ex":[["我看书。","Tôi đọc sách.","Wǒ kàn shū."],["他写字。","Anh ấy viết chữ.","Tā xiě zì."],["我们学习汉语。","Chúng tôi học tiếng Trung.","Wǒmen xuéxí Hànyǔ."]]},{"t":"Phân biệt 看 và 读","b":"看书 = đọc thầm · 读书 = đọc to / đi học","d":"看 là nhìn bằng MẮT (xem sách, xem tivi, xem phim). 读 có bộ 讠 nên là đọc RA TIẾNG. Muốn nói \"đọc sách\" theo nghĩa thông thường, người Trung Quốc nói 看书.","ex":[["我在看书。","Tôi đang đọc sách.","Wǒ zài kàn shū."],["请读一下。","Xin hãy đọc lên một chút.","Qǐng dú yíxià."]]}],"items":[{"zh":"学习","py":"xuéxí","vi":"học, học tập","hv":"học tập","note":"Giống hệt \"học tập\" tiếng Việt. Nói tắt chỉ dùng 学 cũng được: 我学汉语.","ex":"我学习汉语。","exPy":"Wǒ xuéxí Hànyǔ.","exVi":"Tôi học tiếng Trung.","w":"我 学习 汉语。"},{"zh":"学校","py":"xuéxiào","vi":"trường học","hv":"học hiệu","note":"学 (học) + 校 (hiệu). Tiếng Việt có \"hiệu trưởng\", \"trường học\".","ex":"我在学校学习。","exPy":"Wǒ zài xuéxiào xuéxí.","exVi":"Tôi học ở trường.","w":"我 在 学校 学习。"},{"zh":"书","py":"shū","vi":"sách","hv":"thư","note":"Tiếng Việt có \"thư viện\" (nơi chứa sách), \"thư pháp\" (nghệ thuật viết chữ).","ex":"他看书，我写字。","exPy":"Tā kàn shū, wǒ xiě zì.","exVi":"Anh ấy đọc sách, tôi viết chữ.","w":"他 看 书， 我 写 字。"},{"zh":"字","py":"zì","vi":"chữ, chữ viết","hv":"tự","note":"宀 (mái nhà) + 子 (con) — chữ nghĩa sinh sôi trong nhà. Tiếng Việt: \"văn tự\", \"chữ Hán tự\".","ex":"我不会写这个字。","exPy":"Wǒ bú huì xiě zhège zì.","exVi":"Tôi không biết viết chữ này.","w":"我 不 会 写 这个 字。"},{"zh":"写","py":"xiě","vi":"viết","hv":"tả","note":"Tiếng Việt có \"miêu tả\", \"mô tả\". Đây chính là động từ bạn dùng nhiều nhất trong app này.","ex":"老师，请写一下。","exPy":"Lǎoshī, qǐng xiě yíxià.","exVi":"Thưa thầy, xin viết cho em xem.","w":"老师， 请 写 一下。"},{"zh":"读","py":"dú","vi":"đọc (thành tiếng)","hv":"độc","note":"讠 (lời nói) + 卖. Có bộ ngôn nên là đọc RA TIẾNG, khác với 看书 (xem sách bằng mắt). Tiếng Việt: \"độc giả\".","ex":"请读这个字。","exPy":"Qǐng dú zhège zì.","exVi":"Xin hãy đọc chữ này.","w":"请 读 这个 字。"},{"zh":"说话","py":"shuōhuà","vi":"nói, nói chuyện","hv":"thuyết thoại","note":"说 (nói) + 话 (lời). Đây là một \"động từ ly hợp\" — có thể tách ra: 说汉语, 说中国话.","ex":"他说话很快。","exPy":"Tā shuōhuà hěn kuài.","exVi":"Anh ấy nói rất nhanh.","w":"他 说话 很 快。"},{"zh":"看","py":"kàn","vi":"xem, nhìn, đọc (bằng mắt)","hv":"khán","note":"手 (tay) che trên 目 (mắt) — hình người đưa tay che nắng để nhìn cho rõ. Tiếng Việt: \"khán giả\".","ex":"我看书。","exPy":"Wǒ kàn shū.","exVi":"Tôi đọc sách.","w":"我 看 书。"},{"zh":"听","py":"tīng","vi":"nghe","hv":"thính","note":"口 (miệng) + 斤. Giản thể mất bộ 耳 (tai) của chữ phồn thể 聽. Tiếng Việt: \"thính giác\", \"thính giả\".","ex":"请听老师说。","exPy":"Qǐng tīng lǎoshī shuō.","exVi":"Xin hãy nghe thầy nói.","w":"请 听 老师 说。"},{"zh":"会","py":"huì","vi":"biết (làm gì đó), có thể","hv":"hội","note":"Chỉ kỹ năng HỌC ĐƯỢC: biết bơi, biết nói tiếng Trung. Khác với 能 (đủ điều kiện để làm).","ex":"你会说汉语吗？","exPy":"Nǐ huì shuō Hànyǔ ma?","exVi":"Bạn biết nói tiếng Trung không?","w":"你 会 说 汉语 吗？"}],"newChars":["习","校","书","写","读","说","话","看","听","会"],"outro":"很好！Xong bài 6."};
G.ROOMS["zh-l007"] = {"id":"zh-l007","lang":"zh","level":1,"no":7,"teacher":"wang","title":"HSK1 · Bài 7 · 今天几号？ Hôm nay ngày mấy?","intro":["今天几号？","Bài 7: Nói ngày tháng, thứ trong tuần, xem giờ, và hiểu câu không có động từ \"là\". Bấm 1 · Học để bắt đầu."],"introPy":"Jīntiān jǐ hào?","gram":{"t":"Ngày tháng đi từ LỚN đến NHỎ","b":"Năm 年 → Tháng 月 → Ngày 号","d":"Ngược hoàn toàn với tiếng Anh, nhưng GIỐNG cách nói trang trọng của tiếng Việt. Năm đọc từng chữ số một: 2026 = 二零二六年 (nhị-linh-nhị-lục), KHÔNG đọc là \"hai nghìn không trăm hai sáu\".","ex":[["二零二六年九月二号","ngày 2 tháng 9 năm 2026","èr líng èr liù nián jiǔ yuè èr hào"],["今天几月几号？","Hôm nay ngày mấy tháng mấy?","Jīntiān jǐ yuè jǐ hào?"]]},"grams":[{"t":"Ngày tháng đi từ LỚN đến NHỎ","b":"Năm 年 → Tháng 月 → Ngày 号","d":"Ngược hoàn toàn với tiếng Anh, nhưng GIỐNG cách nói trang trọng của tiếng Việt. Năm đọc từng chữ số một: 2026 = 二零二六年 (nhị-linh-nhị-lục), KHÔNG đọc là \"hai nghìn không trăm hai sáu\".","ex":[["二零二六年九月二号","ngày 2 tháng 9 năm 2026","èr líng èr liù nián jiǔ yuè èr hào"],["今天几月几号？","Hôm nay ngày mấy tháng mấy?","Jīntiān jǐ yuè jǐ hào?"]]},{"t":"Câu chỉ thời gian KHÔNG dùng 是","b":"今天星期一。(không có 是)","d":"Đây là ngoại lệ quan trọng. Với ngày tháng, thứ, giờ và tuổi, người Trung Quốc BỎ động từ 是. Nói 今天是星期一 không sai nhưng nghe nặng nề; câu tự nhiên là 今天星期一.","ex":[["今天星期一。","Hôm nay thứ Hai.","Jīntiān xīngqīyī."],["现在八点。","Bây giờ tám giờ.","Xiànzài bā diǎn."],["明天九月三号。","Mai là ngày 3 tháng 9.","Míngtiān jiǔ yuè sān hào."]]},{"t":"Thứ trong tuần = 星期 + số","b":"星期一 … 星期六, riêng Chủ nhật là 星期天","d":"Hệ thống cực kỳ logic: chỉ cần ghép số vào sau 星期. Duy nhất Chủ nhật dùng 天 (hoặc 日) chứ không phải 七.","ex":[["星期一","thứ Hai","xīngqīyī"],["星期五","thứ Sáu","xīngqīwǔ"],["星期天","Chủ nhật","xīngqītiān"]]},{"t":"Xem giờ","b":"số + 点 + số + 分","d":"8:30 = 八点三十分, hoặc nói 八点半 (半 bàn = rưỡi). Chú ý 2 giờ là 两点 liǎng diǎn chứ KHÔNG phải 二点.","ex":[["现在几点？","Bây giờ mấy giờ?","Xiànzài jǐ diǎn?"],["现在八点。","Bây giờ 8 giờ.","Xiànzài bā diǎn."],["两点十分","2 giờ 10 phút","liǎng diǎn shí fēn"]]}],"items":[{"zh":"今天","py":"jīntiān","vi":"hôm nay","hv":"kim thiên","note":"今 (kim, nay) + 天 (thiên, ngày). Tiếng Việt có \"kim cổ\" (nay và xưa).","ex":"今天几号？","exPy":"Jīntiān jǐ hào?","exVi":"Hôm nay ngày mấy?","w":"今天 几 号？"},{"zh":"明天","py":"míngtiān","vi":"ngày mai","hv":"minh thiên","note":"明 = 日 (mặt trời) + 月 (mặt trăng) = sáng sủa. Tiếng Việt: \"minh bạch\", \"quang minh\".","ex":"明天星期四。","exPy":"Míngtiān xīngqīsì.","exVi":"Mai là thứ Năm.","w":"明天 星期 四。"},{"zh":"昨天","py":"zuótiān","vi":"hôm qua","hv":"tạc thiên","note":"Tiếng Việt có \"tạc dạ\" (đêm qua) trong văn cổ.","ex":"昨天是我的生日。","exPy":"Zuótiān shì wǒ de shēngrì.","exVi":"Hôm qua là sinh nhật tôi.","w":"昨天 是 我 的 生日。"},{"zh":"年","py":"nián","vi":"năm","hv":"niên","note":"Tiếng Việt: \"niên khoá\", \"thiếu niên\", \"chu niên\".","ex":"今年","exPy":"jīnnián","exVi":"năm nay","w":"今年"},{"zh":"月","py":"yuè","vi":"tháng; mặt trăng","hv":"nguyệt","note":"Tháng đặt tên bằng SỐ: 一月 = tháng Một, 十二月 = tháng Mười hai. Không có tên riêng như tiếng Anh.","ex":"今天九月二号。","exPy":"Jīntiān jiǔ yuè èr hào.","exVi":"Hôm nay ngày 2 tháng 9.","w":"今天 九 月 二 号。"},{"zh":"号","py":"hào","vi":"ngày (trong tháng); số","hv":"hiệu","note":"Dùng khi NÓI. Khi VIẾT trang trọng thì dùng 日 rì. Tiếng Việt: \"ký hiệu\", \"tín hiệu\".","ex":"今天几号？","exPy":"Jīntiān jǐ hào?","exVi":"Hôm nay ngày mấy?","w":"今天 几 号？"},{"zh":"星期","py":"xīngqī","vi":"tuần; thứ (trong tuần)","hv":"tinh kỳ","note":"星 (sao) + 期 (kỳ hạn). Thứ Hai = 星期一, thứ Bảy = 星期六, Chủ nhật = 星期天.","ex":"今天星期几？","exPy":"Jīntiān xīngqī jǐ?","exVi":"Hôm nay thứ mấy?","w":"今天 星期 几？"},{"zh":"现在","py":"xiànzài","vi":"bây giờ, hiện tại","hv":"hiện tại","note":"Giống hệt \"hiện tại\" tiếng Việt — một trong những từ dễ nhớ nhất cho người Việt.","ex":"现在几点？","exPy":"Xiànzài jǐ diǎn?","exVi":"Bây giờ mấy giờ?","w":"现在 几 点？"},{"zh":"几","py":"jǐ","vi":"mấy, bao nhiêu (số nhỏ)","hv":"kỷ","note":"Dùng khi đoán câu trả lời DƯỚI 10. Nếu số lớn hơn thì dùng 多少 (bài 10).","ex":"明天几点上课？","exPy":"Míngtiān jǐ diǎn shàngkè?","exVi":"Mai mấy giờ vào học?","w":"明天 几 点 上课？"},{"zh":"点","py":"diǎn","vi":"giờ; chấm, điểm","hv":"điểm","note":"Bốn chấm dưới là bộ 灬 (lửa). Tiếng Việt: \"điểm danh\", \"địa điểm\".","ex":"现在七点半。","exPy":"Xiànzài qī diǎn bàn.","exVi":"Bây giờ 7 giờ rưỡi.","w":"现在 七 点 半。"}],"newChars":["今","天","明","昨","年","月","号","星","期","现","在","几","点"],"outro":"很好！Xong bài 7."};
G.ROOMS["zh-l008"] = {"id":"zh-l008","lang":"zh","level":1,"no":8,"teacher":"wang","title":"HSK1 · Bài 8 · 一天的生活 Một ngày của tôi","intro":["上午我在学校学习。","Bài 8: Kể việc làm trong ngày, dùng 了 để nói việc đã xong, phân biệt 想 / 能 / 会 và cấu trúc 太…了. Bấm 1 · Học để bắt đầu."],"introPy":"Shàngwǔ wǒ zài xuéxiào xuéxí.","gram":{"t":"了 — việc đã xảy ra xong","b":"Động từ + 了","d":"了 KHÔNG phải thì quá khứ. Nó báo hiệu một việc đã HOÀN THÀNH. Câu phủ định dùng 没 và PHẢI BỎ 了: 我没吃 (tôi chưa ăn), không được nói 我没吃了.","ex":[["我吃了。","Tôi ăn rồi.","Wǒ chī le."],["他去了学校。","Anh ấy đi đến trường rồi.","Tā qù le xuéxiào."],["我没吃。","Tôi chưa ăn. (bỏ 了)","Wǒ méi chī."]]},"grams":[{"t":"了 — việc đã xảy ra xong","b":"Động từ + 了","d":"了 KHÔNG phải thì quá khứ. Nó báo hiệu một việc đã HOÀN THÀNH. Câu phủ định dùng 没 và PHẢI BỎ 了: 我没吃 (tôi chưa ăn), không được nói 我没吃了.","ex":[["我吃了。","Tôi ăn rồi.","Wǒ chī le."],["他去了学校。","Anh ấy đi đến trường rồi.","Tā qù le xuéxiào."],["我没吃。","Tôi chưa ăn. (bỏ 了)","Wǒ méi chī."]]},{"t":"太 … 了 — cấu trúc cảm thán","b":"太 + tính từ + 了","d":"Hai phần này gần như luôn đi cùng nhau. Đây là câu cảm thán thông dụng nhất trong hội thoại hằng ngày.","ex":[["太好了！","Tuyệt quá!","Tài hǎo le!"],["太贵了！","Đắt quá!","Tài guì le!"],["今天太热了。","Hôm nay nóng quá.","Jīntiān tài rè le."]]},{"t":"Phân biệt 会 / 能 / 想","b":"会 = biết làm · 能 = làm được (hoàn cảnh) · 想 = muốn làm","d":"Ba từ này người Việt rất hay nhầm. 我会游泳 (tôi biết bơi — đã học), 我今天不能游泳 (hôm nay tôi không bơi được — vì bận/ốm), 我想游泳 (tôi muốn đi bơi).","ex":[["我会说汉语。","Tôi biết nói tiếng Trung.","Wǒ huì shuō Hànyǔ."],["我现在不能说。","Bây giờ tôi không nói được.","Wǒ xiànzài bù néng shuō."],["我想学汉语。","Tôi muốn học tiếng Trung.","Wǒ xiǎng xué Hànyǔ."]]},{"t":"Thời gian đứng TRƯỚC động từ","b":"Chủ ngữ + thời gian + động từ","d":"Ngược với tiếng Việt. Ta nói \"Tôi ăn cơm lúc 12 giờ\", tiếng Trung nói \"Tôi 12 giờ ăn cơm\". Thời gian cũng có thể đứng đầu câu.","ex":[["我十二点吃饭。","Tôi ăn cơm lúc 12 giờ.","Wǒ shí'èr diǎn chīfàn."],["上午我在学校。","Buổi sáng tôi ở trường.","Shàngwǔ wǒ zài xuéxiào."]]}],"items":[{"zh":"上午","py":"shàngwǔ","vi":"buổi sáng","hv":"thượng ngọ","note":"上 (trên, trước) + 午 (ngọ, giữa trưa) = trước giờ ngọ. Người Việt cũng gọi 12h trưa là \"chính ngọ\".","ex":"上午我在学校学习。","exPy":"Shàngwǔ wǒ zài xuéxiào xuéxí.","exVi":"Buổi sáng tôi học ở trường.","w":"上午 我 在 学校 学习。"},{"zh":"中午","py":"zhōngwǔ","vi":"buổi trưa","hv":"trung ngọ","note":"中 (giữa) + 午 (ngọ). Khoảng 11h đến 13h.","ex":"中午我吃饭。","exPy":"Zhōngwǔ wǒ chīfàn.","exVi":"Buổi trưa tôi ăn cơm.","w":"中午 我 吃 饭。"},{"zh":"下午","py":"xiàwǔ","vi":"buổi chiều","hv":"hạ ngọ","note":"下 (dưới, sau) + 午 (ngọ) = sau giờ ngọ. Bộ ba 上午/中午/下午 rất dễ nhớ theo logic này.","ex":"下午我做什么？","exPy":"Xiàwǔ wǒ zuò shénme?","exVi":"Buổi chiều tôi làm gì?","w":"下午 我 做 什么？"},{"zh":"睡觉","py":"shuìjiào","vi":"ngủ","hv":"thuỵ giác","note":"睡 có bộ 目 (mắt) — mắt sụp xuống. Đây là động từ ly hợp, tách được: 睡了三个小时的觉.","ex":"我十点睡觉。","exPy":"Wǒ shí diǎn shuìjiào.","exVi":"Tôi đi ngủ lúc 10 giờ.","w":"我 十 点 睡觉。"},{"zh":"做","py":"zuò","vi":"làm, chế tạo","hv":"tố","note":"Đừng nhầm với 坐 zuò (ngồi) — cùng âm, khác chữ và khác nghĩa hoàn toàn.","ex":"你今天做什么了？","exPy":"Nǐ jīntiān zuò shénme le?","exVi":"Hôm nay bạn đã làm gì?","w":"你 今天 做 什么 了？"},{"zh":"分钟","py":"fēnzhōng","vi":"phút","hv":"phân chung","note":"分 (phân, chia) + 钟 (chuông, đồng hồ). 钟 có bộ 钅 (kim loại) vì chuông đúc bằng đồng.","ex":"请等十分钟。","exPy":"Qǐng děng shí fēnzhōng.","exVi":"Xin đợi mười phút.","w":"请 等 十分 钟。"},{"zh":"太","py":"tài","vi":"quá, quá mức","hv":"thái","note":"Hầu như luôn đi kèm 了 ở cuối: 太好了! Tiếng Việt có \"thái quá\".","ex":"太好了！","exPy":"Tài hǎo le!","exVi":"Tuyệt quá!","w":"太 好 了！"},{"zh":"了","py":"le","vi":"(trợ từ: việc đã hoàn thành / tình hình đã đổi)","hv":"liễu","note":"Đọc nhẹ là le. Khi mang nghĩa \"hiểu rõ\" thì đọc liǎo. Đây là chữ khó nhất của HSK1.","ex":"我吃了，谢谢。","exPy":"Wǒ chī le, xièxie.","exVi":"Tôi ăn rồi, cảm ơn.","w":"我 吃 了， 谢谢。"},{"zh":"想","py":"xiǎng","vi":"muốn; nghĩ; nhớ (ai đó)","hv":"tưởng","note":"心 (tim) nằm dưới — chữ về cảm xúc. Tiếng Việt: \"tư tưởng\", \"tưởng nhớ\".","ex":"我想睡觉。","exPy":"Wǒ xiǎng shuìjiào.","exVi":"Tôi muốn ngủ.","w":"我 想 睡觉。"},{"zh":"能","py":"néng","vi":"có thể (đủ điều kiện)","hv":"năng","note":"Tiếng Việt: \"khả năng\", \"năng lực\". Khác 会: 会 là kỹ năng đã học, 能 là hoàn cảnh cho phép.","ex":"我今天不能去。","exPy":"Wǒ jīntiān bù néng qù.","exVi":"Hôm nay tôi không đi được.","w":"我 今天 不 能 去。"}],"newChars":["上","午","下","睡","觉","做","分","钟","太","了","想","能"],"outro":"很好！Xong bài 8."};
G.ROOMS["zh-l009"] = {"id":"zh-l009","lang":"zh","level":1,"no":9,"teacher":"wang","title":"HSK1 · Bài 9 · 吃饭 Ăn uống","intro":["你想吃什么？","Bài 9: Gọi món, nói thích ăn gì, dùng lượng từ cho đồ ăn thức uống và nhận ra bộ 饣 (ăn), 艹 (rau cỏ). Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ xiǎng chī shénme?","gram":{"t":"Lượng từ cho đồ ăn thức uống","b":"一杯茶 · 一个苹果 · 一碗米饭 · 一瓶水","d":"Mỗi loại vật có lượng từ riêng. 杯 (cốc) cho đồ uống, 个 cho quả tròn, 碗 (bát) cho cơm, 瓶 (chai) cho nước đóng chai. Bí quyết: học lượng từ CÙNG LÚC với danh từ, đừng học riêng.","ex":[["一杯茶","một cốc trà","yì bēi chá"],["两个苹果","hai quả táo","liǎng ge píngguǒ"],["一碗米饭","một bát cơm","yì wǎn mǐfàn"]]},"grams":[{"t":"Lượng từ cho đồ ăn thức uống","b":"一杯茶 · 一个苹果 · 一碗米饭 · 一瓶水","d":"Mỗi loại vật có lượng từ riêng. 杯 (cốc) cho đồ uống, 个 cho quả tròn, 碗 (bát) cho cơm, 瓶 (chai) cho nước đóng chai. Bí quyết: học lượng từ CÙNG LÚC với danh từ, đừng học riêng.","ex":[["一杯茶","một cốc trà","yì bēi chá"],["两个苹果","hai quả táo","liǎng ge píngguǒ"],["一碗米饭","một bát cơm","yì wǎn mǐfàn"]]},{"t":"两 hay 二 — dùng cái nào?","b":"Đếm số dùng 二 · Đứng trước lượng từ dùng 两","d":"Rất quan trọng. Nói \"hai quả táo\" phải là 两个苹果, KHÔNG được nói 二个苹果. Nhưng khi đếm 1,2,3 hay đọc số nhà, số điện thoại thì vẫn dùng 二.","ex":[["两个人","hai người (ĐÚNG)","liǎng ge rén"],["两杯水","hai cốc nước","liǎng bēi shuǐ"],["十二号","ngày 12 (dùng 二)","shí'èr hào"]]},{"t":"好 + động từ = dễ chịu khi làm việc đó","b":"好吃 · 好喝 · 好看 · 好听","d":"Một quy tắc ghép chữ cực kỳ hữu ích: 好 + động từ giác quan = \"ngon / đẹp / hay\". 好吃 = ngon (ăn), 好喝 = ngon (uống), 好看 = đẹp, 好听 = hay (nghe).","ex":[["这个菜很好吃。","Món này rất ngon.","Zhège cài hěn hǎochī."],["这个茶很好喝。","Trà này ngon.","Zhège chá hěn hǎohē."]]}],"items":[{"zh":"吃","py":"chī","vi":"ăn","hv":"cật","note":"口 (miệng) + 乞. Có bộ khẩu vì ăn phải dùng miệng. Ăn cơm = 吃饭.","ex":"你想吃什么？","exPy":"Nǐ xiǎng chī shénme?","exVi":"Bạn muốn ăn gì?","w":"你 想 吃 什么？"},{"zh":"喝","py":"hē","vi":"uống","hv":"hát","note":"Cũng có bộ 口. Đừng nhầm 喝 hē (uống) với 渴 kě (khát) — chỉ khác bộ bên trái.","ex":"你喝什么？","exPy":"Nǐ hē shénme?","exVi":"Bạn uống gì?","w":"你 喝 什么？"},{"zh":"菜","py":"cài","vi":"rau; món ăn","hv":"thái","note":"Bộ 艹 (cỏ cây) trên đầu. Vừa nghĩa là rau, vừa nghĩa là món ăn nói chung: 中国菜 = món Trung Quốc.","ex":"我想吃米饭和菜。","exPy":"Wǒ xiǎng chī mǐfàn hé cài.","exVi":"Tôi muốn ăn cơm và rau.","w":"我 想 吃 米饭 和 菜。"},{"zh":"茶","py":"chá","vi":"trà, chè","hv":"trà","note":"Cũng có bộ 艹. Từ \"trà\" tiếng Việt mượn thẳng từ chữ này. Tiếng Anh \"tea\" cũng từ tiếng Hán.","ex":"请给我一杯茶。","exPy":"Qǐng gěi wǒ yì bēi chá.","exVi":"Cho tôi một cốc trà.","w":"请 给 我 一 杯 茶。"},{"zh":"水","py":"shuǐ","vi":"nước","hv":"thuỷ","note":"Bộ thủ quan trọng bậc nhất. Khi đứng bên trái chữ khác thì viết thành 氵. Tiếng Việt: \"thuỷ sản\", \"phong thuỷ\".","ex":"我喜欢吃水果。","exPy":"Wǒ xǐhuan chī shuǐguǒ.","exVi":"Tôi thích ăn hoa quả.","w":"我 喜欢 吃 水果。"},{"zh":"米饭","py":"mǐfàn","vi":"cơm","hv":"mễ phạn","note":"米 (gạo) + 饭 (cơm). 饭 có bộ 饣 (thức ăn). Tiếng Việt: \"gạo mễ\", \"cơm phạn\" trong từ cổ.","ex":"我想吃米饭。","exPy":"Wǒ xiǎng chī mǐfàn.","exVi":"Tôi muốn ăn cơm.","w":"我 想 吃 米饭。"},{"zh":"水果","py":"shuǐguǒ","vi":"hoa quả, trái cây","hv":"thuỷ quả","note":"水 (nước) + 果 (quả) = quả mọng nước. Tiếng Việt: \"kết quả\", \"hiệu quả\" cùng chữ 果.","ex":"我喜欢吃水果。","exPy":"Wǒ xǐhuan chī shuǐguǒ.","exVi":"Tôi thích ăn hoa quả.","w":"我 喜欢 吃 水果。"},{"zh":"苹果","py":"píngguǒ","vi":"quả táo","hv":"bình quả","note":"苹 có bộ 艹. Hãng Apple trong tiếng Trung cũng gọi là 苹果.","ex":"我买了两个苹果。","exPy":"Wǒ mǎi le liǎng ge píngguǒ.","exVi":"Tôi mua hai quả táo.","w":"我 买 了 两 个 苹果。"},{"zh":"饭馆","py":"fànguǎn","vi":"quán ăn, nhà hàng","hv":"phạn quán","note":"Cả hai chữ đều có bộ 饣 (thức ăn). Tiếng Việt có \"quán\" — chính là chữ 馆.","ex":"我们去饭馆吃饭吧。","exPy":"Wǒmen qù fànguǎn chīfàn ba.","exVi":"Chúng ta đi nhà hàng ăn cơm đi.","w":"我们 去 饭馆 吃 饭 吧。"},{"zh":"杯子","py":"bēizi","vi":"cái cốc, cái ly","hv":"bôi tử","note":"木 (gỗ) + 不 — cốc xưa làm bằng gỗ. 杯 cũng là lượng từ: 一杯水 = một cốc nước.","ex":"这个杯子很漂亮。","exPy":"Zhège bēizi hěn piàoliang.","exVi":"Cái cốc này rất đẹp.","w":"这个 杯子 很 漂亮。"}],"newChars":["吃","喝","菜","茶","水","米","饭","果","苹","馆","杯"],"outro":"很好！Xong bài 9."};
G.ROOMS["zh-l010"] = {"id":"zh-l010","lang":"zh","level":1,"no":10,"teacher":"wang","title":"HSK1 · Bài 10 · 买东西 Mua sắm","intro":["我去商店买东西。","Bài 10: Hỏi giá, mặc cả, dùng 多少 để hỏi số lượng lớn và phân biệt 多少 với 几. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒ qù shāngdiàn mǎi dōngxi.","gram":{"t":"Hỏi giá — mẫu câu bắt buộc thuộc lòng","b":"这个多少钱？","d":"Đây là câu bạn sẽ dùng nhiều nhất khi đi chợ ở Trung Quốc. Trả lời: số + 块钱.","ex":[["这个多少钱？","Cái này bao nhiêu tiền?","Zhège duōshao qián?"],["十五块。","Mười lăm đồng.","Shíwǔ kuài."],["太贵了！便宜一点儿吧。","Đắt quá! Rẻ một chút đi.","Tài guì le! Piányi yìdiǎnr ba."]]},"grams":[{"t":"Hỏi giá — mẫu câu bắt buộc thuộc lòng","b":"这个多少钱？","d":"Đây là câu bạn sẽ dùng nhiều nhất khi đi chợ ở Trung Quốc. Trả lời: số + 块钱.","ex":[["这个多少钱？","Cái này bao nhiêu tiền?","Zhège duōshao qián?"],["十五块。","Mười lăm đồng.","Shíwǔ kuài."],["太贵了！便宜一点儿吧。","Đắt quá! Rẻ một chút đi.","Tài guì le! Piányi yìdiǎnr ba."]]},{"t":"多少 hay 几 — chọn thế nào?","b":"几 = đoán dưới 10 (cần lượng từ) · 多少 = số bất kỳ (không cần lượng từ)","d":"几个人 (mấy người — ít) nhưng 多少人 (bao nhiêu người — có thể rất đông). Đặc biệt: hỏi tiền LUÔN dùng 多少 vì giá có thể lớn.","ex":[["你家有几个人？","Nhà bạn mấy người? (đoán ít)","Nǐ jiā yǒu jǐ ge rén?"],["你们学校有多少学生？","Trường bạn có bao nhiêu học sinh?","Nǐmen xuéxiào yǒu duōshao xuésheng?"],["多少钱？","Bao nhiêu tiền?","Duōshao qián?"]]},{"t":"一点儿 đặt ở đâu","b":"Động từ + 一点儿 + danh từ · Tính từ + 一点儿","d":"Sau ĐỘNG TỪ nghĩa là \"một ít\": 喝一点儿水. Sau TÍNH TỪ nghĩa là \"hơn một chút\": 便宜一点儿 (rẻ hơn chút). Đừng đặt đầu câu.","ex":[["我想喝一点儿水。","Tôi muốn uống một chút nước.","Wǒ xiǎng hē yìdiǎnr shuǐ."],["便宜一点儿。","Rẻ chút đi.","Piányi yìdiǎnr."]]}],"items":[{"zh":"买","py":"mǎi","vi":"mua","hv":"mãi","note":"Chữ phồn thể 買 có bộ 贝 (vỏ sò = tiền) ở dưới. Tiếng Việt: \"thương mại\", \"mãi lực\". Đừng nhầm với 卖 mài (bán) — chỉ khác một nét trên đầu!","ex":"我去商店买东西。","exPy":"Wǒ qù shāngdiàn mǎi dōngxi.","exVi":"Tôi đi cửa hàng mua đồ.","w":"我 去 商店 买 东西。"},{"zh":"钱","py":"qián","vi":"tiền","hv":"tiền","note":"Chính là chữ \"tiền\" của tiếng Việt. Bộ 钅 (kim loại) vì tiền xưa đúc bằng đồng.","ex":"这个多少钱？","exPy":"Zhège duōshao qián?","exVi":"Cái này bao nhiêu tiền?","w":"这个 多少 钱？"},{"zh":"块","py":"kuài","vi":"đồng (đơn vị tiền); cục, miếng","hv":"khối","note":"Đây là cách nói KHẨU NGỮ của đồng nhân dân tệ. Khi viết trang trọng dùng 元 yuán.","ex":"这个二十块钱。","exPy":"Zhège èrshí kuài qián.","exVi":"Cái này hai mươi đồng.","w":"这个 二 十 块 钱。"},{"zh":"多少","py":"duōshao","vi":"bao nhiêu","hv":"đa thiểu","note":"多 (nhiều) + 少 (ít) ghép lại thành \"bao nhiêu\". Chữ 少 ở đây đọc nhẹ là shao.","ex":"这些苹果多少钱？","exPy":"Zhèxiē píngguǒ duōshao qián?","exVi":"Mấy quả táo này bao nhiêu tiền?","w":"这些 苹果 多少 钱？"},{"zh":"商店","py":"shāngdiàn","vi":"cửa hàng","hv":"thương điếm","note":"商 (thương mại) + 店 (cửa tiệm). 店 có bộ 广 (mái hiên). Tiếng Việt: \"thương gia\", \"cửa hiệu\".","ex":"我去商店买东西。","exPy":"Wǒ qù shāngdiàn mǎi dōngxi.","exVi":"Tôi đi cửa hàng mua đồ.","w":"我 去 商店 买 东西。"},{"zh":"东西","py":"dōngxi","vi":"đồ vật, đồ đạc","hv":"đông tây","note":"Thú vị: 东 (đông) + 西 (tây) ghép lại lại có nghĩa là \"đồ vật\". Khi đọc là dōngxī (đủ thanh) thì mới nghĩa là phương đông-tây.","ex":"我买了很多东西。","exPy":"Wǒ mǎi le hěn duō dōngxi.","exVi":"Tôi mua rất nhiều đồ.","w":"我 买 了 很 多 东西。"},{"zh":"些","py":"xiē","vi":"một vài, một ít","hv":"ta","note":"Luôn đi với 一 hoặc 这/那: 一些 (một ít), 这些 (những cái này), 那些 (những cái kia).","ex":"我买了一些水果。","exPy":"Wǒ mǎi le yìxiē shuǐguǒ.","exVi":"Tôi mua một ít hoa quả.","w":"我 买 了 一些 水果。"},{"zh":"衣服","py":"yīfu","vi":"quần áo","hv":"y phục","note":"Chính là \"y phục\" tiếng Việt. 衣 là bộ thủ chỉ quần áo, bên trái chữ viết thành 衤.","ex":"我想买这件衣服。","exPy":"Wǒ xiǎng mǎi zhè jiàn yīfu.","exVi":"Tôi muốn mua bộ quần áo này.","w":"我 想 买 这 件 衣服。"},{"zh":"一点儿","py":"yìdiǎnr","vi":"một chút, một ít","hv":"nhất điểm nhi","note":"Âm 儿 er ở cuối là đặc trưng giọng Bắc Kinh. Đọc uốn lưỡi, không tách thành hai âm tiết.","ex":"便宜一点儿吧。","exPy":"Piányi yìdiǎnr ba.","exVi":"Rẻ một chút đi.","w":"便宜 一点儿 吧。"},{"zh":"少","py":"shǎo","vi":"ít","hv":"thiểu","note":"小 (nhỏ) thêm một nét phẩy. Tiếng Việt: \"thiểu số\", \"tối thiểu\".","ex":"我的钱很少。","exPy":"Wǒ de qián hěn shǎo.","exVi":"Tiền của tôi rất ít.","w":"我 的 钱 很 少。"}],"newChars":["买","钱","块","多","少","商","店","东","西","些","衣","服"],"outro":"很好！Xong bài 10."};
G.ROOMS["zh-l011"] = {"id":"zh-l011","lang":"zh","level":1,"no":11,"teacher":"wang","title":"HSK1 · Bài 11 · 在哪儿？ Ở đâu?","intro":["你在哪儿？","Bài 11: Hỏi và chỉ vị trí, dùng 在, phân biệt 这/那 và nắm quy tắc từ chỉ nơi chốn đứng sau danh từ. Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ zài nǎr?","gram":{"t":"在 làm động từ: A 在 nơi chốn","b":"Người/vật + 在 + nơi chốn","d":"Ở đây 在 là ĐỘNG TỪ CHÍNH, câu không cần động từ nào khác. 我在家 = tôi ở nhà (đủ câu). Phủ định: 不在.","ex":[["我在家。","Tôi ở nhà.","Wǒ zài jiā."],["老师不在学校。","Thầy không ở trường.","Lǎoshī bú zài xuéxiào."],["你在哪儿？","Bạn ở đâu?","Nǐ zài nǎr?"]]},"grams":[{"t":"在 làm động từ: A 在 nơi chốn","b":"Người/vật + 在 + nơi chốn","d":"Ở đây 在 là ĐỘNG TỪ CHÍNH, câu không cần động từ nào khác. 我在家 = tôi ở nhà (đủ câu). Phủ định: 不在.","ex":[["我在家。","Tôi ở nhà.","Wǒ zài jiā."],["老师不在学校。","Thầy không ở trường.","Lǎoshī bú zài xuéxiào."],["你在哪儿？","Bạn ở đâu?","Nǐ zài nǎr?"]]},{"t":"在 làm giới từ: đứng TRƯỚC động từ chính","b":"Chủ ngữ + 在 + nơi chốn + động từ","d":"Đây là điểm khác biệt lớn với tiếng Việt. Ta nói \"Tôi học Ở TRƯỜNG\" (nơi chốn ở cuối), tiếng Trung nói \"Tôi Ở TRƯỜNG học\" (nơi chốn ở giữa). Nói 我学习在学校 là SAI.","ex":[["我在学校学习。","Tôi học ở trường.","Wǒ zài xuéxiào xuéxí."],["他在饭馆吃饭。","Anh ấy ăn cơm ở nhà hàng.","Tā zài fànguǎn chīfàn."],["妈妈在医院工作。","Mẹ làm việc ở bệnh viện.","Māma zài yīyuàn gōngzuò."]]},{"t":"Từ chỉ vị trí đứng SAU danh từ","b":"Danh từ + 上 / 下 / 里 / 前面 / 后面","d":"Ngược hoàn toàn với tiếng Việt. Ta nói \"TRÊN bàn\", tiếng Trung nói \"bàn TRÊN\" (桌子上). Ta nói \"TRONG nhà\", tiếng Trung nói \"nhà TRONG\" (家里).","ex":[["桌子上","trên bàn","zhuōzi shàng"],["家里","trong nhà","jiā lǐ"],["学校前面","phía trước trường học","xuéxiào qiánmiàn"]]}],"items":[{"zh":"在","py":"zài","vi":"ở, tại; đang","hv":"tại","note":"Tiếng Việt: \"hiện tại\", \"tại chỗ\", \"tồn tại\". Vừa là động từ (ở đâu) vừa là giới từ (ở tại).","ex":"你在哪儿？","exPy":"Nǐ zài nǎr?","exVi":"Bạn ở đâu?","w":"你 在 哪儿？"},{"zh":"哪儿","py":"nǎr","vi":"ở đâu","hv":"na nhi","note":"Giọng Bắc Kinh nói 哪儿 nǎr, giọng miền Nam nói 哪里 nǎlǐ. Cả hai đều đúng.","ex":"医院在哪儿？","exPy":"Yīyuàn zài nǎr?","exVi":"Bệnh viện ở đâu?","w":"医院 在 哪儿？"},{"zh":"这","py":"zhè","vi":"này, đây","hv":"giá","note":"Có bộ 辶 (đi đường). Trước lượng từ thường đọc thành zhèi trong khẩu ngữ.","ex":"这是我的家。","exPy":"Zhè shì wǒ de jiā.","exVi":"Đây là nhà tôi.","w":"这 是 我 的 家。"},{"zh":"那","py":"nà","vi":"kia, đó","hv":"na","note":"Cặp 这 / 那 giống \"này / kia\" tiếng Việt. Cẩn thận: 那 nà (kia) và 哪 nǎ (nào) chỉ khác bộ 口 và thanh điệu.","ex":"那是你的书吗？","exPy":"Nà shì nǐ de shū ma?","exVi":"Kia là sách của bạn à?","w":"那 是 你 的 书 吗？"},{"zh":"里","py":"lǐ","vi":"trong, bên trong","hv":"lý","note":"Đứng SAU danh từ: 家里 (trong nhà), 学校里 (trong trường). Ngược với tiếng Việt.","ex":"书在包里。","exPy":"Shū zài bāo lǐ.","exVi":"Sách ở trong cặp.","w":"书 在 包 里。"},{"zh":"前面","py":"qiánmiàn","vi":"phía trước","hv":"tiền diện","note":"前 (tiền, trước) — tiếng Việt có \"tiền sử\", \"tiền lệ\". 面 (diện, mặt) — \"diện tích\", \"bề mặt\".","ex":"医院在学校前面。","exPy":"Yīyuàn zài xuéxiào qiánmiàn.","exVi":"Bệnh viện ở phía trước trường học.","w":"医院 在 学校 前面。"},{"zh":"后面","py":"hòumiàn","vi":"phía sau","hv":"hậu diện","note":"后 (hậu, sau) — tiếng Việt có \"hậu quả\", \"hậu phương\", \"sau này\".","ex":"商店在后面。","exPy":"Shāngdiàn zài hòumiàn.","exVi":"Cửa hàng ở phía sau.","w":"商店 在 后面。"},{"zh":"上","py":"shàng","vi":"trên; lên","hv":"thượng","note":"Một nét ngang làm mốc, phần nhô LÊN trên. Tiếng Việt: \"thượng đế\", \"cao thượng\".","ex":"书在桌子上。","exPy":"Shū zài zhuōzi shàng.","exVi":"Sách ở trên bàn.","w":"书 在 桌子 上。"},{"zh":"下","py":"xià","vi":"dưới; xuống","hv":"hạ","note":"Ngược lại của 上 — phần chìa XUỐNG dưới. Tiếng Việt: \"hạ giá\", \"thiên hạ\".","ex":"猫在桌子下。","exPy":"Māo zài zhuōzi xià.","exVi":"Con mèo ở dưới bàn.","w":"猫 在 桌子 下。"},{"zh":"医院","py":"yīyuàn","vi":"bệnh viện","hv":"y viện","note":"医 (y) + 院 (viện). Tiếng Việt cũng có \"y viện\", \"học viện\", \"viện nghiên cứu\".","ex":"老师不在，他在医院。","exPy":"Lǎoshī bú zài, tā zài yīyuàn.","exVi":"Thầy không ở đây, thầy ở bệnh viện.","w":"老师 不 在， 他 在 医院。"}],"newChars":["哪","这","那","里","前","面","后","院"],"outro":"很好！Xong bài 11."};
G.ROOMS["zh-l012"] = {"id":"zh-l012","lang":"zh","level":1,"no":12,"teacher":"wang","title":"HSK1 · Bài 12 · 去北京 Đi Bắc Kinh","intro":["你去哪儿？","Bài 12: Nói về đi lại, phương tiện giao thông, dùng 坐 và 和, và nắm trật tự \"phương tiện đứng trước động từ\". Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ qù nǎr?","gram":{"t":"Phương tiện đi lại: 坐 + xe + động từ","b":"坐 + phương tiện + 去/来 + nơi đến","d":"Phương tiện đứng TRƯỚC động từ chính, giống quy tắc của 在. Ta nói \"đi Bắc Kinh BẰNG MÁY BAY\", tiếng Trung nói \"NGỒI MÁY BAY đi Bắc Kinh\". Riêng xe đạp và xe máy dùng 骑 qí (cưỡi).","ex":[["我坐飞机去北京。","Tôi đi máy bay đến Bắc Kinh.","Wǒ zuò fēijī qù Běijīng."],["他坐出租车回家。","Anh ấy đi taxi về nhà.","Tā zuò chūzūchē huí jiā."],["我开车去。","Tôi lái xe đi.","Wǒ kāichē qù."]]},"grams":[{"t":"Phương tiện đi lại: 坐 + xe + động từ","b":"坐 + phương tiện + 去/来 + nơi đến","d":"Phương tiện đứng TRƯỚC động từ chính, giống quy tắc của 在. Ta nói \"đi Bắc Kinh BẰNG MÁY BAY\", tiếng Trung nói \"NGỒI MÁY BAY đi Bắc Kinh\". Riêng xe đạp và xe máy dùng 骑 qí (cưỡi).","ex":[["我坐飞机去北京。","Tôi đi máy bay đến Bắc Kinh.","Wǒ zuò fēijī qù Běijīng."],["他坐出租车回家。","Anh ấy đi taxi về nhà.","Tā zuò chūzūchē huí jiā."],["我开车去。","Tôi lái xe đi.","Wǒ kāichē qù."]]},{"t":"和 chỉ nối DANH TỪ, không nối câu","b":"danh từ + 和 + danh từ","d":"Lỗi rất phổ biến. Tiếng Việt dùng \"và\" nối được cả câu (\"Tôi ăn cơm và anh ấy uống trà\"). Tiếng Trung KHÔNG được: phải bỏ 和 hoặc dùng dấu phẩy.","ex":[["我和他","tôi và anh ấy (ĐÚNG)","wǒ hé tā"],["爸爸和妈妈都在家。","Bố và mẹ đều ở nhà.","Bàba hé māma dōu zài jiā."],["我吃饭，他喝茶。","Tôi ăn cơm, anh ấy uống trà. (dùng dấu phẩy, KHÔNG dùng 和)","Wǒ chīfàn, tā hē chá."]]},{"t":"Phân biệt 去 / 来 / 回","b":"去 = đi ra xa · 来 = đến gần · 回 = quay về chỗ cũ","d":"Chọn từ nào phụ thuộc vị trí NGƯỜI NÓI. Đang ở nhà thì nói 你来我家 (bạn đến nhà tôi). Đang ở ngoài thì nói 我回家 (tôi về nhà).","ex":[["我去你家。","Tôi đến nhà bạn.","Wǒ qù nǐ jiā."],["你来我家。","Bạn đến nhà tôi.","Nǐ lái wǒ jiā."],["我回家。","Tôi về nhà.","Wǒ huí jiā."]]}],"items":[{"zh":"去","py":"qù","vi":"đi (đến đâu đó)","hv":"khứ","note":"Tiếng Việt: \"quá khứ\" (đã đi qua). 去 luôn là đi RA XA khỏi người nói.","ex":"你去哪儿？","exPy":"Nǐ qù nǎr?","exVi":"Bạn đi đâu?","w":"你 去 哪儿？"},{"zh":"来","py":"lái","vi":"đến, tới","hv":"lai","note":"Tiếng Việt: \"tương lai\", \"lai lịch\". Ngược với 去 — 来 là đi LẠI GẦN người nói.","ex":"你来我家吧。","exPy":"Nǐ lái wǒ jiā ba.","exVi":"Bạn đến nhà tôi đi.","w":"你 来 我 家 吧。"},{"zh":"回","py":"huí","vi":"về, quay lại","hv":"hồi","note":"Hình hai vòng xoáy lồng nhau — quay vòng trở lại. Tiếng Việt: \"hồi hương\", \"hồi đáp\", \"hồi phục\".","ex":"他坐出租车回家。","exPy":"Tā zuò chūzūchē huí jiā.","exVi":"Anh ấy đi taxi về nhà.","w":"他 坐 出租车 回 家。"},{"zh":"坐","py":"zuò","vi":"ngồi; đi (bằng phương tiện)","hv":"toạ","note":"Hai chữ 人 (người) ngồi trên 土 (đất). Tiếng Việt: \"toạ độ\", \"toạ lạc\". Đừng nhầm với 做 zuò (làm).","ex":"我坐飞机去北京。","exPy":"Wǒ zuò fēijī qù Běijīng.","exVi":"Tôi đi máy bay đến Bắc Kinh.","w":"我 坐 飞机 去 北京。"},{"zh":"开","py":"kāi","vi":"mở; lái (xe); bật","hv":"khai","note":"Tiếng Việt: \"khai trương\", \"khai giảng\", \"khai mạc\". 开车 = lái xe, 开门 = mở cửa.","ex":"他会开车吗？","exPy":"Tā huì kāichē ma?","exVi":"Anh ấy biết lái xe không?","w":"他 会 开车 吗？"},{"zh":"出租车","py":"chūzūchē","vi":"xe taxi","hv":"xuất tô xa","note":"出租 (cho thuê) + 车 (xe) = xe cho thuê. Ở Trung Quốc còn gọi thân mật là 打车 (bắt xe).","ex":"我坐出租车去。","exPy":"Wǒ zuò chūzūchē qù.","exVi":"Tôi đi bằng taxi.","w":"我 坐 出租车 去。"},{"zh":"飞机","py":"fēijī","vi":"máy bay","hv":"phi cơ","note":"Chính là \"phi cơ\" tiếng Việt! 飞 (bay) + 机 (máy). Tiếng Việt còn có \"phi công\", \"phi trường\".","ex":"我坐飞机去北京。","exPy":"Wǒ zuò fēijī qù Běijīng.","exVi":"Tôi đi máy bay đến Bắc Kinh.","w":"我 坐 飞机 去 北京。"},{"zh":"北京","py":"Běijīng","vi":"Bắc Kinh","hv":"Bắc Kinh","note":"北 (bắc) + 京 (kinh đô) = \"kinh đô phía bắc\". Đúng là \"Bắc Kinh\" tiếng Việt. Tương tự 南京 = Nam Kinh.","ex":"北京是中国的首都。","exPy":"Běijīng shì Zhōngguó de shǒudū.","exVi":"Bắc Kinh là thủ đô Trung Quốc.","w":"北京 是 中国 的 首都。"},{"zh":"住","py":"zhù","vi":"ở, cư trú","hv":"trú","note":"亻 (người) + 主 (chủ). Tiếng Việt: \"cư trú\", \"đồn trú\". Khác 在: 住 là ở LÂU DÀI, 在 là ở ngay lúc này.","ex":"你住在哪儿？","exPy":"Nǐ zhù zài nǎr?","exVi":"Bạn sống ở đâu?","w":"你 住 在 哪儿？"},{"zh":"和","py":"hé","vi":"và, với","hv":"hoà","note":"禾 (cây lúa) + 口 (miệng) — có lúa ăn thì hoà thuận. Tiếng Việt: \"hoà bình\", \"hoà thuận\". CHỈ nối danh từ, không nối câu.","ex":"我和朋友一起去。","exPy":"Wǒ hé péngyou yìqǐ qù.","exVi":"Tôi đi cùng bạn.","w":"我 和 朋友 一起 去。"}],"newChars":["去","回","坐","租","车","飞","机","北","住"],"outro":"很好！Xong bài 12."};
G.ROOMS["zh-l013"] = {"id":"zh-l013","lang":"zh","level":1,"no":13,"teacher":"wang","title":"HSK1 · Bài 13 · 在家里 Trong nhà","intro":["喂，你好，请问王先生在吗？","Bài 13: Gọi tên đồ vật trong nhà, nói chuyện điện thoại, và khám phá \"gia đình chữ 电\". Bấm 1 · Học để bắt đầu."],"introPy":"Wéi, nǐ hǎo, qǐngwèn Wáng xiānsheng zài ma?","gram":{"t":"Gia đình chữ 电 — học một chữ được năm từ","b":"电 = điện → 电脑, 电视, 电影, 电话, 电子","d":"Đây chính là sức mạnh của việc học chữ Hán theo thành phần. Biết 电 (điện) rồi, bạn đoán được nghĩa của cả loạt từ mới mà không cần tra từ điển. Người Việt càng lợi thế vì đã quen \"điện ảnh\", \"điện thoại\", \"điện não\".","ex":[["电脑","điện + não = máy tính","diànnǎo"],["电视","điện + nhìn = tivi","diànshì"],["电影","điện + bóng hình = phim","diànyǐng"],["电话","điện + lời nói = điện thoại","diànhuà"]]},"grams":[{"t":"Gia đình chữ 电 — học một chữ được năm từ","b":"电 = điện → 电脑, 电视, 电影, 电话, 电子","d":"Đây chính là sức mạnh của việc học chữ Hán theo thành phần. Biết 电 (điện) rồi, bạn đoán được nghĩa của cả loạt từ mới mà không cần tra từ điển. Người Việt càng lợi thế vì đã quen \"điện ảnh\", \"điện thoại\", \"điện não\".","ex":[["电脑","điện + não = máy tính","diànnǎo"],["电视","điện + nhìn = tivi","diànshì"],["电影","điện + bóng hình = phim","diànyǐng"],["电话","điện + lời nói = điện thoại","diànhuà"]]},{"t":"Bổ ngữ kết quả: 看 và 看见","b":"Động từ hành động + động từ kết quả","d":"Tiếng Trung tách rõ HÀNH ĐỘNG và KẾT QUẢ. 我看了 = tôi đã nhìn (nhưng chưa chắc thấy gì). 我看见了 = tôi đã nhìn THẤY. Tương tự: 听 (nghe) và 听见 (nghe thấy).","ex":[["我看了，但是没看见。","Tôi đã nhìn, nhưng không thấy.","Wǒ kàn le, dànshì méi kànjiàn."],["你看见我的书了吗？","Bạn có thấy sách của tôi không?","Nǐ kànjiàn wǒ de shū le ma?"]]},{"t":"给 + người + động từ — làm gì đó CHO ai","b":"给 + người + 打电话 / 买 / 写","d":"给 gěi đứng trước người nhận, và cả cụm đặt TRƯỚC động từ chính. Ta nói \"gọi điện CHO mẹ\", tiếng Trung nói \"CHO mẹ gọi điện\".","ex":[["我给妈妈打电话。","Tôi gọi điện cho mẹ.","Wǒ gěi māma dǎ diànhuà."],["他给我买了一本书。","Anh ấy mua cho tôi một quyển sách.","Tā gěi wǒ mǎi le yì běn shū."]]}],"items":[{"zh":"桌子","py":"zhuōzi","vi":"cái bàn","hv":"trác tử","note":"Có bộ 木 (gỗ) ở dưới vì bàn làm bằng gỗ. Hậu tố 子 đọc nhẹ, rất hay gặp ở tên đồ vật.","ex":"书在桌子上，不在椅子上。","exPy":"Shū zài zhuōzi shàng, bú zài yǐzi shàng.","exVi":"Sách ở trên bàn, không phải trên ghế.","w":"书 在 桌子 上， 不 在 椅子 上。"},{"zh":"椅子","py":"yǐzi","vi":"cái ghế","hv":"ỷ tử","note":"Cũng có bộ 木 (gỗ) bên trái. Cặp 桌子 / 椅子 luôn học chung.","ex":"这个椅子很好。","exPy":"Zhège yǐzi hěn hǎo.","exVi":"Cái ghế này rất tốt.","w":"这个 椅子 很 好。"},{"zh":"电脑","py":"diànnǎo","vi":"máy tính","hv":"điện não","note":"电 (điện) + 脑 (não) = \"bộ não điện\". Cách đặt tên rất hình tượng của tiếng Trung.","ex":"我有一个电脑。","exPy":"Wǒ yǒu yí ge diànnǎo.","exVi":"Tôi có một cái máy tính.","w":"我 有 一 个 电脑。"},{"zh":"电视","py":"diànshì","vi":"tivi, truyền hình","hv":"điện thị","note":"电 (điện) + 视 (thị, nhìn) = \"nhìn bằng điện\". Tiếng Việt: \"thị giác\", \"truyền hình\".","ex":"晚上我看电视。","exPy":"Wǎnshang wǒ kàn diànshì.","exVi":"Buổi tối tôi xem tivi.","w":"晚上 我 看 电视。"},{"zh":"电影","py":"diànyǐng","vi":"phim, điện ảnh","hv":"điện ảnh","note":"Chính là \"điện ảnh\" tiếng Việt! 电 (điện) + 影 (ảnh, bóng hình).","ex":"我们去看电影吧。","exPy":"Wǒmen qù kàn diànyǐng ba.","exVi":"Chúng ta đi xem phim đi.","w":"我们 去 看 电影 吧。"},{"zh":"打电话","py":"dǎ diànhuà","vi":"gọi điện thoại","hv":"đả điện thoại","note":"打 (đánh) + 电话 (điện thoại). Người Trung Quốc \"đánh\" điện thoại, giống tiếng Việt \"đánh điện\" ngày xưa.","ex":"我给妈妈打电话。","exPy":"Wǒ gěi māma dǎ diànhuà.","exVi":"Tôi gọi điện cho mẹ.","w":"我 给 妈妈 打电话。"},{"zh":"喂","py":"wèi","vi":"a-lô (khi nghe điện thoại)","hv":"uy","note":"Khi nghe điện thoại thường đọc thành thanh 2: wéi (nghe mềm mại, lịch sự hơn). Đọc wèi nghe hơi cộc.","ex":"喂，你好，请问王先生在吗？","exPy":"Wéi, nǐ hǎo, qǐngwèn Wáng xiānsheng zài ma?","exVi":"A-lô, xin chào, cho hỏi ông Vương có ở đó không ạ?","w":"喂， 你好， 请问 王 先生 在 吗？"},{"zh":"看见","py":"kànjiàn","vi":"nhìn thấy","hv":"khán kiến","note":"看 (nhìn) + 见 (thấy). 看 là HÀNH ĐỘNG nhìn, 看见 là KẾT QUẢ đã thấy được.","ex":"我看见你的书了。","exPy":"Wǒ kànjiàn nǐ de shū le.","exVi":"Tôi thấy sách của bạn rồi.","w":"我 看见 你 的 书 了。"},{"zh":"大","py":"dà","vi":"to, lớn","hv":"đại","note":"Hình người dang rộng tay chân. Tiếng Việt: \"đại học\", \"vĩ đại\", \"đại lộ\".","ex":"我的房间不大也不小。","exPy":"Wǒ de fángjiān bú dà yě bù xiǎo.","exVi":"Phòng tôi không to cũng không nhỏ.","w":"我 的 房间 不 大 也 不 小。"},{"zh":"小","py":"xiǎo","vi":"nhỏ, bé","hv":"tiểu","note":"Tiếng Việt: \"tiểu học\", \"tiểu thuyết\", \"tiểu đội\". Cặp 大 / 小 luôn học chung.","ex":"这个杯子很小。","exPy":"Zhège bēizi hěn xiǎo.","exVi":"Cái cốc này rất nhỏ.","w":"这个 杯子 很 小。"}],"newChars":["桌","椅","电","脑","影","打","喂"],"outro":"很好！Xong bài 13."};
G.ROOMS["zh-l014"] = {"id":"zh-l014","lang":"zh","level":1,"no":14,"teacher":"wang","title":"HSK1 · Bài 14 · 我喜欢猫 Tôi thích mèo","intro":["你喜欢猫还是狗？","Bài 14: Nói về sở thích, khen chê, hỏi ý kiến bằng 怎么样 và hỏi cách làm bằng 怎么. Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ xǐhuan māo háishi gǒu?","gram":{"t":"喜欢 + danh từ HOẶC + động từ","b":"喜欢 + danh từ · 喜欢 + động từ + tân ngữ","d":"Khác nhiều động từ khác, sau 喜欢 có thể là cả một cụm hành động. 我喜欢猫 (thích mèo) và 我喜欢看书 (thích đọc sách) đều đúng.","ex":[["我喜欢中国菜。","Tôi thích món Trung Quốc.","Wǒ xǐhuan Zhōngguó cài."],["我喜欢看电影。","Tôi thích xem phim.","Wǒ xǐhuan kàn diànyǐng."],["我不喜欢喝茶。","Tôi không thích uống trà.","Wǒ bù xǐhuan hē chá."]]},"grams":[{"t":"喜欢 + danh từ HOẶC + động từ","b":"喜欢 + danh từ · 喜欢 + động từ + tân ngữ","d":"Khác nhiều động từ khác, sau 喜欢 có thể là cả một cụm hành động. 我喜欢猫 (thích mèo) và 我喜欢看书 (thích đọc sách) đều đúng.","ex":[["我喜欢中国菜。","Tôi thích món Trung Quốc.","Wǒ xǐhuan Zhōngguó cài."],["我喜欢看电影。","Tôi thích xem phim.","Wǒ xǐhuan kàn diànyǐng."],["我不喜欢喝茶。","Tôi không thích uống trà.","Wǒ bù xǐhuan hē chá."]]},{"t":"怎么 và 怎么样 — đừng nhầm","b":"怎么 + động từ (cách làm) · Danh từ + 怎么样 ? (ý kiến)","d":"怎么 luôn đứng TRƯỚC động từ và hỏi LÀM THẾ NÀO. 怎么样 đứng CUỐI câu và hỏi THẾ NÀO, RA SAO. Nói 这个电影怎么? là sai.","ex":[["这个字怎么写？","Chữ này viết thế nào? (cách làm)","Zhège zì zěnme xiě?"],["你的工作怎么样？","Công việc của bạn thế nào? (ý kiến)","Nǐ de gōngzuò zěnmeyàng?"],["我们去看电影，怎么样？","Chúng ta đi xem phim nhé?","Wǒmen qù kàn diànyǐng, zěnmeyàng?"]]},{"t":"很多 — nói \"nhiều\" phải có 很","b":"很多 + danh từ","d":"Một chữ 多 đứng trước danh từ nghe cụt. Phải nói 很多书 (rất nhiều sách), không nói 多书. Đây là lỗi rất hay gặp.","ex":[["我有很多书。","Tôi có rất nhiều sách.","Wǒ yǒu hěn duō shū."],["这里有很多人。","Ở đây có rất nhiều người.","Zhèlǐ yǒu hěn duō rén."]]},{"t":"… 的时候 = khi mà …","b":"Mệnh đề + 的时候 + mệnh đề chính","d":"Vế chỉ thời gian đứng TRƯỚC, khác tiếng Việt hay đặt ở sau. \"Hồi nhỏ tôi thích mèo\" = 我小的时候喜欢猫.","ex":[["我小的时候很喜欢猫。","Hồi nhỏ tôi rất thích mèo.","Wǒ xiǎo de shíhou hěn xǐhuan māo."],["吃饭的时候不要说话。","Lúc ăn cơm đừng nói chuyện.","Chīfàn de shíhou búyào shuōhuà."]]}],"items":[{"zh":"喜欢","py":"xǐhuan","vi":"thích","hv":"hỉ hoan","note":"Tiếng Việt có \"hoan hỉ\" (vui mừng) — cùng hai chữ này nhưng đảo thứ tự. Sau 喜欢 có thể là danh từ HOẶC cả một động từ.","ex":"你喜欢猫还是狗？","exPy":"Nǐ xǐhuan māo háishi gǒu?","exVi":"Bạn thích mèo hay chó?","w":"你 喜欢 猫 还是 狗？"},{"zh":"爱","py":"ài","vi":"yêu; rất thích","hv":"ái","note":"Tiếng Việt: \"ái tình\", \"tình ái\", \"ái mộ\". Mạnh hơn 喜欢 nhiều — đừng dùng bừa với người lạ.","ex":"我很爱我的家。","exPy":"Wǒ hěn ài wǒ de jiā.","exVi":"Tôi rất yêu gia đình mình.","w":"我 很 爱 我 的 家。"},{"zh":"漂亮","py":"piàoliang","vi":"đẹp, xinh","hv":"phiêu lượng","note":"Chữ thứ hai đọc nhẹ. Dùng khen người (nữ), đồ vật, phong cảnh. Khen nam giới thì dùng 帅 shuài (đẹp trai).","ex":"她很漂亮。","exPy":"Tā hěn piàoliang.","exVi":"Cô ấy rất xinh.","w":"她 很 漂亮。"},{"zh":"多","py":"duō","vi":"nhiều","hv":"đa","note":"Hai chữ 夕 (buổi tối) chồng lên nhau — nhiều đêm nối tiếp. Tiếng Việt: \"đa số\", \"đa dạng\".","ex":"我有很多中文书。","exPy":"Wǒ yǒu hěn duō Zhōngwén shū.","exVi":"Tôi có rất nhiều sách tiếng Trung.","w":"我 有 很 多 中文 书。"},{"zh":"猫","py":"māo","vi":"con mèo","hv":"miêu","note":"Bộ 犭 (thú bốn chân) + 苗. Tiếng Việt có \"miêu\" trong \"miêu nữ\". Từ \"mèo\" tiếng Việt cũng cùng gốc.","ex":"我喜欢猫，我家有两只猫。","exPy":"Wǒ xǐhuan māo, wǒ jiā yǒu liǎng zhī māo.","exVi":"Tôi thích mèo, nhà tôi có hai con mèo.","w":"我 喜欢 猫， 我 家 有 两 只 猫。"},{"zh":"狗","py":"gǒu","vi":"con chó","hv":"cẩu","note":"Cũng có bộ 犭. Tiếng Việt: \"cẩu\" trong \"cẩu thả\", \"hải cẩu\". Lượng từ cho động vật là 只 zhī.","ex":"这只狗很大。","exPy":"Zhè zhī gǒu hěn dà.","exVi":"Con chó này rất to.","w":"这 只 狗 很 大。"},{"zh":"本","py":"běn","vi":"quyển (lượng từ cho sách)","hv":"bản","note":"木 (cây) thêm một nét ngang ở gốc = gốc rễ. Tiếng Việt: \"cơ bản\", \"bản gốc\", \"nguyên bản\".","ex":"这本书怎么样？","exPy":"Zhè běn shū zěnmeyàng?","exVi":"Quyển sách này thế nào?","w":"这 本 书 怎么样？"},{"zh":"时候","py":"shíhou","vi":"lúc, khi, thời điểm","hv":"thì hậu","note":"Hay dùng trong cấu trúc …的时候 = \"khi mà…\". Tiếng Việt: \"thời gian\", \"thời điểm\".","ex":"我小的时候不喜欢学习。","exPy":"Wǒ xiǎo de shíhou bù xǐhuan xuéxí.","exVi":"Hồi nhỏ tôi không thích học.","w":"我 小 的 时候 不 喜欢 学习。"},{"zh":"怎么","py":"zěnme","vi":"làm thế nào, sao lại","hv":"chẩm ma","note":"Hỏi CÁCH THỨC: 怎么写? (viết thế nào?). Cũng hỏi lý do khi ngạc nhiên: 你怎么不来? (sao bạn không đến?).","ex":"这个字怎么写？","exPy":"Zhège zì zěnme xiě?","exVi":"Chữ này viết thế nào?","w":"这个 字 怎么 写？"},{"zh":"怎么样","py":"zěnmeyàng","vi":"thế nào, ra sao","hv":"chẩm ma dạng","note":"Hỏi Ý KIẾN hoặc TÌNH TRẠNG, khác 怎么 (hỏi cách làm). Cũng dùng để rủ rê: 我们去吃饭，怎么样?","ex":"我们去吃饭，怎么样？","exPy":"Wǒmen qù chīfàn, zěnmeyàng?","exVi":"Chúng ta đi ăn cơm nhé?","w":"我们 去 吃 饭， 怎么样？"}],"newChars":["喜","欢","漂","亮","猫","狗","本","时","候","怎","样"],"outro":"很好！Xong bài 14."};
G.ROOMS["zh-l015"] = {"id":"zh-l015","lang":"zh","level":1,"no":15,"teacher":"wang","title":"HSK1 · Bài 15 · 今天天气怎么样？ Thời tiết và phép lịch sự","intro":["今天天气怎么样？","Bài 15: Nói về thời tiết, hỏi tuổi, xin lỗi và đáp lễ — trọn bộ nghi thức giao tiếp cơ bản. Bấm 1 · Học để bắt đầu."],"introPy":"Jīntiān tiānqì zěnmeyàng?","gram":{"t":"Cặp đôi lịch sự — đáp đúng câu","b":"谢谢 → 不客气 · 对不起 → 没关系","d":"Đây là lỗi người mới hay mắc: đáp 没关系 cho lời cảm ơn. Nhớ theo cặp: cảm ơn thì đáp \"đừng khách sáo\", xin lỗi thì đáp \"không sao\".","ex":[["谢谢你！— 不客气。","Cảm ơn bạn! — Không có gì.","Xièxie nǐ! — Bú kèqi."],["对不起。— 没关系。","Xin lỗi. — Không sao đâu.","Duìbuqǐ. — Méi guānxi."]]},"grams":[{"t":"Cặp đôi lịch sự — đáp đúng câu","b":"谢谢 → 不客气 · 对不起 → 没关系","d":"Đây là lỗi người mới hay mắc: đáp 没关系 cho lời cảm ơn. Nhớ theo cặp: cảm ơn thì đáp \"đừng khách sáo\", xin lỗi thì đáp \"không sao\".","ex":[["谢谢你！— 不客气。","Cảm ơn bạn! — Không có gì.","Xièxie nǐ! — Bú kèqi."],["对不起。— 没关系。","Xin lỗi. — Không sao đâu.","Duìbuqǐ. — Méi guānxi."]]},{"t":"Hỏi tuổi — ba cách cho ba đối tượng","b":"Trẻ em: 你几岁？· Người ngang tuổi: 你多大？· Người lớn tuổi: 您多大年纪？","d":"Hỏi tuổi trong tiếng Trung phải chọn câu theo tuổi người nghe. Hỏi người lớn bằng 你几岁 là rất bất lịch sự vì câu đó chỉ dành cho trẻ con dưới 10 tuổi.","ex":[["你几岁？","Cháu mấy tuổi? (hỏi trẻ con)","Nǐ jǐ suì?"],["你多大？","Bạn bao nhiêu tuổi?","Nǐ duō dà?"],["我二十岁。","Tôi 20 tuổi.","Wǒ èrshí suì."]]},{"t":"Câu thời tiết không cần chủ ngữ","b":"下雨了。· 很冷。","d":"Tiếng Trung cho phép bỏ hẳn chủ ngữ khi nói về thời tiết, giống tiếng Việt nói \"Mưa rồi\", \"Lạnh quá\". Chữ 了 ở cuối báo hiệu TÌNH HÌNH ĐÃ THAY ĐỔI.","ex":[["下雨了。","Mưa rồi.","Xiàyǔ le."],["天气冷了。","Trời lạnh rồi.","Tiānqì lěng le."]]},{"t":"Ba chữ dễ nhầm: 那 / 哪 / 呢","b":"那 nà = kia · 哪 nǎ = nào · 呢 ne = trợ từ hỏi lại","d":"那 và 哪 chỉ khác nhau bộ 口 bên trái và thanh điệu. Mẹo nhớ: 哪 có MIỆNG 口 vì phải MỞ MIỆNG ra hỏi.","ex":[["那是什么？","Kia là cái gì?","Nà shì shénme?"],["你要哪个？","Bạn muốn cái nào?","Nǐ yào nǎge?"],["我很好，你呢？","Tôi khoẻ, còn bạn?","Wǒ hěn hǎo, nǐ ne?"]]}],"items":[{"zh":"天气","py":"tiānqì","vi":"thời tiết","hv":"thiên khí","note":"天 (trời) + 气 (khí). Tiếng Việt: \"khí hậu\", \"không khí\", \"thiên nhiên\".","ex":"今天天气怎么样？","exPy":"Jīntiān tiānqì zěnmeyàng?","exVi":"Hôm nay thời tiết thế nào?","w":"今天 天气 怎么样？"},{"zh":"冷","py":"lěng","vi":"lạnh","hv":"lãnh","note":"Bộ 冫 (hai chấm băng) bên trái — dấu hiệu của giá lạnh. Tiếng Việt: \"lãnh đạm\", \"lạnh lẽo\".","ex":"昨天很冷，今天不冷。","exPy":"Zuótiān hěn lěng, jīntiān bù lěng.","exVi":"Hôm qua rất lạnh, hôm nay không lạnh.","w":"昨天 很 冷， 今天 不 冷。"},{"zh":"热","py":"rè","vi":"nóng","hv":"nhiệt","note":"Bộ 灬 (bốn chấm lửa) ở dưới. Tiếng Việt: \"nhiệt độ\", \"nhiệt tình\", \"nhiệt đới\".","ex":"今天很热。","exPy":"Jīntiān hěn rè.","exVi":"Hôm nay rất nóng.","w":"今天 很 热。"},{"zh":"下雨","py":"xiàyǔ","vi":"mưa, trời mưa","hv":"hạ vũ","note":"下 (rơi xuống) + 雨 (mưa). Tiếng Trung coi mưa là một HÀNH ĐỘNG, nên nói 下雨了 (mưa rồi).","ex":"外面下雨了。","exPy":"Wàimiàn xiàyǔ le.","exVi":"Bên ngoài mưa rồi.","w":"外面 下雨 了。"},{"zh":"对不起","py":"duìbuqǐ","vi":"xin lỗi","hv":"đối bất khởi","note":"Nghĩa đen: \"không xứng đối mặt với bạn\". Dùng khi mình thực sự có lỗi.","ex":"对不起，我来晚了。","exPy":"Duìbuqǐ, wǒ lái wǎn le.","exVi":"Xin lỗi, tôi đến muộn.","w":"对不起， 我 来 晚 了。"},{"zh":"没关系","py":"méi guānxi","vi":"không sao đâu","hv":"một quan hệ","note":"Nghĩa đen: \"không có liên quan gì\". 关系 chính là \"quan hệ\" tiếng Việt. Đây là câu ĐÁP LẠI 对不起.","ex":"没关系。","exPy":"Méi guānxi.","exVi":"Không sao đâu.","w":"没关系。"},{"zh":"不客气","py":"bú kèqi","vi":"không có gì, đừng khách sáo","hv":"bất khách khí","note":"Nghĩa đen: \"đừng khách khí\". Đây là câu ĐÁP LẠI 谢谢. Đừng dùng nhầm với 没关系.","ex":"谢谢你！— 不客气。","exPy":"Xièxie nǐ! — Bú kèqi.","exVi":"Cảm ơn bạn! — Không có gì.","w":"谢谢 你！— 不客气。"},{"zh":"谁","py":"shéi","vi":"ai","hv":"thuỳ","note":"Có bộ 讠 (lời nói). Đọc là shéi trong khẩu ngữ, shuí trong văn viết. Cả hai đều đúng.","ex":"他是谁？","exPy":"Tā shì shéi?","exVi":"Anh ấy là ai?","w":"他 是 谁？"},{"zh":"岁","py":"suì","vi":"tuổi","hv":"tuế","note":"山 (núi) + 夕 (chiều tối). Tiếng Việt có \"tuế nguyệt\" (năm tháng) trong văn cổ.","ex":"我二十岁。","exPy":"Wǒ èrshí suì.","exVi":"Tôi hai mươi tuổi.","w":"我 二 十 岁。"},{"zh":"哪","py":"nǎ","vi":"nào (cái nào)","hv":"na","note":"So sánh kỹ ba chữ: 那 nà (kia) — 哪 nǎ (nào) — 呢 ne (trợ từ). Rất dễ nhầm khi mới học.","ex":"你是哪国人？","exPy":"Nǐ shì nǎ guó rén?","exVi":"Bạn là người nước nào?","w":"你 是 哪 国 人？"}],"newChars":["冷","雨","关","系","客","谁","岁"],"outro":"很好！Xong bài 15."};
G.ROOMS["zh-l016"] = {"id":"zh-l016","lang":"zh","level":1,"no":16,"teacher":"wang","title":"HSK1 · Bài 16 · 他们和这些 Họ, cái này, những cái kia","intro":["你们好！","Bài 16: Nói số nhiều bằng 们, và chỉ người, vật bằng 这个 / 那个 / 哪个, 这些 / 那些 / 哪些. Bấm 1 · Học để bắt đầu."],"introPy":"Nǐmen hǎo!","gram":{"t":"们 — số nhiều cho người","b":"đại từ / danh từ chỉ người + 们","d":"Tiếng Trung không đổi hình thức danh từ theo số nhiều. Chỉ người mới thêm 们, và không thêm khi đã có số đếm hay từ chỉ số lượng.","ex":[["老师们都很忙。","Các thầy cô đều rất bận.","Lǎoshīmen dōu hěn máng."],["我有三个朋友。","Tôi có ba người bạn.","Wǒ yǒu sān ge péngyou."]]},"grams":[{"t":"们 — số nhiều cho người","b":"đại từ / danh từ chỉ người + 们","d":"Tiếng Trung không đổi hình thức danh từ theo số nhiều. Chỉ người mới thêm 们, và không thêm khi đã có số đếm hay từ chỉ số lượng.","ex":[["老师们都很忙。","Các thầy cô đều rất bận.","Lǎoshīmen dōu hěn máng."],["我有三个朋友。","Tôi có ba người bạn.","Wǒ yǒu sān ge péngyou."]]},{"t":"这 / 那 / 哪 + 个 hoặc 些","b":"这个 cái này · 那个 cái kia · 哪个 cái nào · 这些 / 那些 / 哪些 nhiều cái","d":"Một cái thì dùng 个 (hoặc lượng từ riêng), nhiều cái thì dùng 些. Câu hỏi với 哪 không cần thêm 吗.","ex":[["你要这个还是那个？","Bạn lấy cái này hay cái kia?","Nǐ yào zhège háishi nàge?"],["哪些是你的？","Những cái nào là của bạn?","Nǎxiē shì nǐ de?"]]}],"items":[{"zh":"们","py":"men","vi":"(hậu tố số nhiều cho người)","hv":"môn","note":"Gắn sau đại từ hoặc danh từ chỉ người để thành số nhiều: 我们, 老师们. Không dùng 们 khi đã có số đếm: nói 三个学生, không nói 三个学生们.","ex":"你们好！","exPy":"Nǐmen hǎo!","exVi":"Chào các bạn!","w":"你们 好！"},{"zh":"你们","py":"nǐmen","vi":"các bạn, các anh chị","hv":"nễ môn","note":"你 + 们. Dùng khi nói với từ hai người trở lên.","ex":"你们是学生吗？","exPy":"Nǐmen shì xuésheng ma?","exVi":"Các bạn là học sinh à?","w":"你们 是 学生 吗？"},{"zh":"他们","py":"tāmen","vi":"họ, các anh ấy","hv":"tha môn","note":"Nhóm có cả nam lẫn nữ cũng dùng 他们.","ex":"他们是哪国人？","exPy":"Tāmen shì nǎ guó rén?","exVi":"Họ là người nước nào?","w":"他们 是 哪 国 人？"},{"zh":"她们","py":"tāmen","vi":"họ (toàn nữ), các cô ấy","hv":"tha môn","note":"Đọc giống hệt 他们, chỉ khác khi viết: cả nhóm đều là nữ mới dùng 她们.","ex":"她们都是老师。","exPy":"Tāmen dōu shì lǎoshī.","exVi":"Các cô ấy đều là giáo viên.","w":"她们 都 是 老师。"},{"zh":"它们","py":"tāmen","vi":"chúng nó (con vật, đồ vật)","hv":"tha môn","note":"它 dùng cho con vật, đồ vật. Ba chữ 他们, 她们, 它们 đọc như nhau.","ex":"我家有两只猫，它们很可爱。","exPy":"Wǒ jiā yǒu liǎng zhī māo, tāmen hěn kě'ài.","exVi":"Nhà tôi có hai con mèo, chúng rất đáng yêu.","w":"我 家 有 两 只 猫， 它们 很 可爱。"},{"zh":"这个","py":"zhège","vi":"cái này, người này","hv":"giá cá","note":"这 (này) + 个 (lượng từ chung). Trong khẩu ngữ hay đọc zhèige.","ex":"这个是我的，那个是你的。","exPy":"Zhège shì wǒ de, nàge shì nǐ de.","exVi":"Cái này của tôi, cái kia của bạn.","w":"这个 是 我 的， 那个 是 你 的。"},{"zh":"那个","py":"nàge","vi":"cái kia, người kia","hv":"na cá","note":"那 (kia) + 个. Khẩu ngữ hay đọc nèige. Người Trung Quốc còn nói 那个… khi đang nghĩ, giống \"ờ…\" của người Việt.","ex":"那个人是谁？","exPy":"Nàge rén shì shéi?","exVi":"Người kia là ai?","w":"那个 人 是 谁？"},{"zh":"哪个","py":"nǎge","vi":"cái nào, người nào","hv":"na cá","note":"Chú ý thanh điệu: 哪 thanh 3 (nǎ) là \"nào\", 那 thanh 4 (nà) là \"kia\". Chữ 哪 có thêm bộ 口.","ex":"你喜欢哪个？","exPy":"Nǐ xǐhuan nǎge?","exVi":"Bạn thích cái nào?","w":"你 喜欢 哪个？"},{"zh":"这些","py":"zhèxiē","vi":"những cái này","hv":"giá ta","note":"些 là \"một vài, những\". Sau 这些 không cần lượng từ: 这些书.","ex":"这些都是新的。","exPy":"Zhèxiē dōu shì xīn de.","exVi":"Những cái này đều mới.","w":"这些 都 是 新 的。"},{"zh":"那些","py":"nàxiē","vi":"những cái kia","hv":"na ta","note":"Đối xứng với 这些.","ex":"那些苹果很好吃。","exPy":"Nàxiē píngguǒ hěn hǎochī.","exVi":"Những quả táo kia rất ngon.","w":"那些 苹果 很 好吃。"},{"zh":"哪些","py":"nǎxiē","vi":"những cái nào","hv":"na ta","note":"Hỏi khi câu trả lời có thể là nhiều thứ.","ex":"你喜欢哪些菜？","exPy":"Nǐ xǐhuan nǎxiē cài?","exVi":"Bạn thích những món nào?","w":"你 喜欢 哪些 菜？"}],"newChars":["它"],"outro":"很好！Xong bài 16."};
G.ROOMS["zh-l017"] = {"id":"zh-l017","lang":"zh","level":1,"no":17,"teacher":"wang","title":"HSK1 · Bài 17 · 这里和那里 Ở đây, ở kia","intro":["这里是哪里？","Bài 17: Chỉ nơi chốn bằng 这里 / 那里 / 哪里, 这边 / 那边, và nói trước, sau, bên ngoài. Bấm 1 · Học để bắt đầu."],"introPy":"Zhèlǐ shì nǎlǐ?","gram":{"t":"在 + nơi chốn","b":"Người / vật + 在 + 这里 / 那里 / 哪里","d":"Hỏi \"ở đâu\" thì chỉ cần đặt 哪里 vào đúng chỗ của câu trả lời, không cần đảo trật tự như tiếng Anh.","ex":[["你在哪里？","Bạn đang ở đâu?","Nǐ zài nǎlǐ?"],["我在这里。","Tôi ở đây.","Wǒ zài zhèlǐ."]]},"grams":[{"t":"在 + nơi chốn","b":"Người / vật + 在 + 这里 / 那里 / 哪里","d":"Hỏi \"ở đâu\" thì chỉ cần đặt 哪里 vào đúng chỗ của câu trả lời, không cần đảo trật tự như tiếng Anh.","ex":[["你在哪里？","Bạn đang ở đâu?","Nǐ zài nǎlǐ?"],["我在这里。","Tôi ở đây.","Wǒ zài zhèlǐ."]]},{"t":"Danh từ + 前 / 后 / 边","b":"学校前 · 吃饭后 · 门边","d":"Từ chỉ phương hướng đứng SAU danh từ, ngược với tiếng Việt: tiếng Việt nói \"trước trường\", tiếng Trung nói \"trường trước\" (学校前).","ex":[["银行在医院后边。","Ngân hàng ở phía sau bệnh viện.","Yínháng zài yīyuàn hòubian."],["下课后我去图书馆。","Tan học tôi đi thư viện.","Xiàkè hòu wǒ qù túshūguǎn."]]}],"items":[{"zh":"这里","py":"zhèlǐ","vi":"ở đây, chỗ này","hv":"giá lý","note":"里 ở đây là \"chỗ, nơi\". Miền Bắc Trung Quốc hay nói 这儿, nghĩa như nhau.","ex":"这里是哪里？","exPy":"Zhèlǐ shì nǎlǐ?","exVi":"Đây là đâu?","w":"这里 是 哪里？"},{"zh":"那里","py":"nàlǐ","vi":"ở đó, ở kia","hv":"na lý","note":"Tương đương 那儿.","ex":"那里有很多人。","exPy":"Nàlǐ yǒu hěn duō rén.","exVi":"Ở đó có rất nhiều người.","w":"那里 有 很 多 人。"},{"zh":"哪里","py":"nǎlǐ","vi":"ở đâu","hv":"na lý","note":"Hai thanh 3 đi liền nên đọc thành nálǐ. Khi được khen, người Trung Quốc hay đáp 哪里哪里 nghĩa là \"đâu có, đâu có\".","ex":"你家在哪里？","exPy":"Nǐ jiā zài nǎlǐ?","exVi":"Nhà bạn ở đâu?","w":"你 家 在 哪里？"},{"zh":"这边","py":"zhèbiān","vi":"bên này, phía này","hv":"giá biên","note":"边 là \"bên, phía\". Hay dùng khi chỉ đường: 请这边走 (mời đi lối này).","ex":"请这边走。","exPy":"Qǐng zhèbiān zǒu.","exVi":"Mời đi lối này.","w":"请 这边 走。"},{"zh":"那边","py":"nàbiān","vi":"bên kia, phía kia","hv":"na biên","note":"Đối xứng với 这边.","ex":"我在那边等你。","exPy":"Wǒ zài nàbiān děng nǐ.","exVi":"Tôi đợi bạn ở bên kia.","w":"我 在 那边 等 你。"},{"zh":"外边","py":"wàibian","vi":"bên ngoài","hv":"ngoại biên","note":"外 = \"ngoại\" trong \"ngoại quốc\". Chữ 边 ở đây đọc nhẹ.","ex":"外边很冷，你多穿一点儿。","exPy":"Wàibian hěn lěng, nǐ duō chuān yìdiǎnr.","exVi":"Bên ngoài lạnh lắm, bạn mặc thêm vào.","w":"外边 很 冷， 你 多 穿 一点儿。"},{"zh":"前","py":"qián","vi":"phía trước; trước (thời gian)","hv":"tiền","note":"\"Tiền\" trong \"tiền sảnh\", \"trước tiên\". Dùng cả cho chỗ lẫn thời gian: 三天前 (ba ngày trước).","ex":"我家前边有一个公园。","exPy":"Wǒ jiā qiánbian yǒu yí ge gōngyuán.","exVi":"Trước nhà tôi có một công viên.","w":"我 家 前 边 有 一 个 公园。"},{"zh":"后","py":"hòu","vi":"phía sau; sau (thời gian)","hv":"hậu","note":"\"Hậu\" trong \"hậu quả\", \"hậu phương\". 以后 là \"sau này\".","ex":"吃饭后我们去看电影。","exPy":"Chīfàn hòu wǒmen qù kàn diànyǐng.","exVi":"Ăn cơm xong chúng ta đi xem phim.","w":"吃 饭 后 我们 去 看 电影。"},{"zh":"边","py":"biān","vi":"bên, phía, cạnh","hv":"biên","note":"\"Biên\" trong \"biên giới\". Ghép với phương hướng: 左边, 右边, 旁边.","ex":"我坐在他旁边。","exPy":"Wǒ zuò zài tā pángbiān.","exVi":"Tôi ngồi cạnh anh ấy.","w":"我 坐 在 他 旁边。"},{"zh":"有的","py":"yǒude","vi":"có cái, có người, một số","hv":"hữu đích","note":"Dùng để chia một nhóm: 有的…有的… (có người thì…, có người thì…).","ex":"有的同学来了，有的还没来。","exPy":"Yǒude tóngxué lái le, yǒude hái méi lái.","exVi":"Có bạn đến rồi, có bạn chưa đến.","w":"有的 同学 来 了， 有的 还 没 来。"}],"newChars":["边","外"],"outro":"很好！Xong bài 17."};
G.ROOMS["zh-l018"] = {"id":"zh-l018","lang":"zh","level":1,"no":18,"teacher":"wang","title":"HSK1 · Bài 18 · 今天和明年 Ngày, năm, sớm, muộn","intro":["你今年多大？","Bài 18: Nói về ngày tháng năm, buổi trong ngày, và nói sớm muộn, một nửa, một chút. Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ jīnnián duō dà?","gram":{"t":"Thời gian đứng trước động từ","b":"Chủ ngữ + thời gian + động từ · Thời gian + chủ ngữ + động từ","d":"Mốc thời gian (今年, 明天, 白天…) luôn đứng TRƯỚC động từ, không đặt cuối câu như tiếng Việt hay nói \"tôi đi Trung Quốc năm sau\".","ex":[["我明年去中国。","Năm sau tôi đi Trung Quốc.","Wǒ míngnián qù Zhōngguó."],["星期天我们去公园吧。","Chủ nhật mình đi công viên nhé.","Xīngqītiān wǒmen qù gōngyuán ba."]]},"grams":[{"t":"Thời gian đứng trước động từ","b":"Chủ ngữ + thời gian + động từ · Thời gian + chủ ngữ + động từ","d":"Mốc thời gian (今年, 明天, 白天…) luôn đứng TRƯỚC động từ, không đặt cuối câu như tiếng Việt hay nói \"tôi đi Trung Quốc năm sau\".","ex":[["我明年去中国。","Năm sau tôi đi Trung Quốc.","Wǒ míngnián qù Zhōngguó."],["星期天我们去公园吧。","Chủ nhật mình đi công viên nhé.","Xīngqītiān wǒmen qù gōngyuán ba."]]},{"t":"Động từ + 一下","b":"看一下 · 等一下 · 试一下","d":"Làm việc gì đó trong thời gian ngắn hoặc nói cho nhẹ nhàng. Hai thanh 4 đi liền nên 一 đọc thanh 2: yíxià.","ex":[["你看一下这个。","Bạn xem qua cái này nhé.","Nǐ kàn yíxià zhège."],["我们休息一下吧。","Chúng ta nghỉ một lát đi.","Wǒmen xiūxi yíxià ba."]]}],"items":[{"zh":"天","py":"tiān","vi":"ngày; trời","hv":"thiên","note":"Vừa là \"trời\" vừa là \"ngày\": 今天, 三天. Cũng làm lượng từ: 一天 (một ngày).","ex":"我每天早上六点起床，很早。","exPy":"Wǒ měi tiān zǎoshang liù diǎn qǐchuáng, hěn zǎo.","exVi":"Sáng nào tôi cũng dậy lúc sáu giờ, rất sớm.","w":"我 每 天 早上 六 点 起床， 很 早。"},{"zh":"白天","py":"báitiān","vi":"ban ngày","hv":"bạch thiên","note":"白 (trắng, sáng) + 天 (ngày) = lúc trời sáng.","ex":"白天我工作，晚上我学习。","exPy":"Báitiān wǒ gōngzuò, wǎnshang wǒ xuéxí.","exVi":"Ban ngày tôi làm việc, buổi tối tôi học.","w":"白天 我 工作， 晚上 我 学习。"},{"zh":"今年","py":"jīnnián","vi":"năm nay","hv":"kim niên","note":"今 = \"kim\" trong \"kim cổ\", \"hiện kim\": bây giờ. 今天 hôm nay, 今年 năm nay.","ex":"你今年多大？","exPy":"Nǐ jīnnián duō dà?","exVi":"Năm nay bạn bao nhiêu tuổi?","w":"你 今年 多 大？"},{"zh":"明年","py":"míngnián","vi":"năm sau","hv":"minh niên","note":"Giống 明天 (ngày mai): 明 ở đây nghĩa là \"kế tiếp\".","ex":"明年我想去中国。","exPy":"Míngnián wǒ xiǎng qù Zhōngguó.","exVi":"Năm sau tôi muốn đi Trung Quốc.","w":"明年 我 想 去 中国。"},{"zh":"星期天","py":"xīngqītiān","vi":"Chủ nhật","hv":"tinh kỳ thiên","note":"Thứ Hai đến thứ Bảy là 星期一 đến 星期六. Chủ nhật không phải \"星期七\" mà là 星期天.","ex":"星期天你有时间吗？","exPy":"Xīngqītiān nǐ yǒu shíjiān ma?","exVi":"Chủ nhật bạn có thời gian không?","w":"星期天 你 有时 间 吗？"},{"zh":"星期日","py":"xīngqīrì","vi":"Chủ nhật","hv":"tinh kỳ nhật","note":"Cùng nghĩa với 星期天 nhưng trang trọng hơn, hay gặp trên lịch và văn bản.","ex":"星期日商店也开门。","exPy":"Xīngqīrì shāngdiàn yě kāimén.","exVi":"Chủ nhật cửa hàng cũng mở cửa.","w":"星期日 商店 也 开 门。"},{"zh":"早","py":"zǎo","vi":"sớm; chào buổi sáng","hv":"tảo","note":"Chữ 日 (mặt trời) trên 十: mặt trời vừa lên. Gặp nhau buổi sáng có thể chỉ nói 早！","ex":"你早！今天你来得很早。","exPy":"Nǐ zǎo! Jīntiān nǐ lái de hěn zǎo.","exVi":"Chào buổi sáng! Hôm nay bạn đến sớm thế.","w":"你 早！ 今天 你 来 得 很 早。"},{"zh":"晚","py":"wǎn","vi":"muộn; buổi tối","hv":"vãn","note":"\"Vãn\" trong \"vãn hồi\", \"vãn bối\". Đối lập với 早.","ex":"太晚了，我们回家吧。","exPy":"Tài wǎn le, wǒmen huí jiā ba.","exVi":"Muộn quá rồi, mình về nhà thôi.","w":"太 晚 了， 我们 回 家 吧。"},{"zh":"一半","py":"yíbàn","vi":"một nửa","hv":"nhất bán","note":"半 = \"bán\" trong \"bán cầu\", \"bán kết\".","ex":"这本书我看了一半。","exPy":"Zhè běn shū wǒ kàn le yíbàn.","exVi":"Cuốn sách này tôi đọc được một nửa.","w":"这 本 书 我 看 了 一半。"},{"zh":"一下","py":"yíxià","vi":"một chút, một lát","hv":"nhất hạ","note":"Đặt sau động từ để câu mềm và lịch sự hơn: 等一下 (đợi chút), 看一下 (xem qua).","ex":"请等一下。","exPy":"Qǐng děng yíxià.","exVi":"Xin đợi một chút.","w":"请 等 一下。"}],"newChars":["白","日","早","晚","半"],"outro":"很好！Xong bài 18."};
G.ROOMS["zh-l019"] = {"id":"zh-l019","lang":"zh","level":1,"no":19,"teacher":"wang","title":"HSK1 · Bài 19 · 吃饭了吗？ Ba bữa cơm","intro":["你会做饭吗？","Bài 19: Nói về bữa sáng, trưa, tối, nấu ăn, và các nơi bán đồ ăn, bán sách. Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ huì zuò fàn ma?","gram":{"t":"Ăn bữa nào thì dùng 吃","b":"吃 + 早饭 / 午饭 / 晚饭","d":"Không cần \"ăn bữa\", chỉ cần 吃早饭. Hỏi \"ăn chưa\" thì thêm 了吗.","ex":[["你吃早饭了吗？","Bạn ăn sáng chưa?","Nǐ chī zǎofàn le ma?"],["我还没吃午饭。","Tôi vẫn chưa ăn trưa.","Wǒ hái méi chī wǔfàn."]]},"grams":[{"t":"Ăn bữa nào thì dùng 吃","b":"吃 + 早饭 / 午饭 / 晚饭","d":"Không cần \"ăn bữa\", chỉ cần 吃早饭. Hỏi \"ăn chưa\" thì thêm 了吗.","ex":[["你吃早饭了吗？","Bạn ăn sáng chưa?","Nǐ chī zǎofàn le ma?"],["我还没吃午饭。","Tôi vẫn chưa ăn trưa.","Wǒ hái méi chī wǔfàn."]]},{"t":"Lượng từ 家 cho cửa hàng, công ty","b":"一家 + 店 / 饭店 / 书店 / 公司","d":"Nơi kinh doanh đếm bằng 家, giống tiếng Việt nói \"một nhà hàng\".","ex":[["这里有两家书店。","Ở đây có hai hiệu sách.","Zhèlǐ yǒu liǎng jiā shūdiàn."],["那家饭店很贵。","Nhà hàng kia rất đắt.","Nà jiā fàndiàn hěn guì."]]}],"items":[{"zh":"饭","py":"fàn","vi":"cơm; bữa ăn","hv":"phạn","note":"\"Phạn\" trong \"phạn điếm\". Người Trung Quốc chào nhau bằng 吃饭了吗？ (ăn cơm chưa?), giống người Việt.","ex":"你会做饭吗？","exPy":"Nǐ huì zuò fàn ma?","exVi":"Bạn biết nấu ăn không?","w":"你 会 做饭 吗？"},{"zh":"早饭","py":"zǎofàn","vi":"bữa sáng","hv":"tảo phạn","note":"早 (sớm) + 饭 (bữa ăn).","ex":"早饭我喝牛奶，吃面包。","exPy":"Zǎofàn wǒ hē niúnǎi, chī miànbāo.","exVi":"Bữa sáng tôi uống sữa, ăn bánh mì.","w":"早饭 我 喝 牛奶， 吃 面包。"},{"zh":"午饭","py":"wǔfàn","vi":"bữa trưa","hv":"ngọ phạn","note":"午 = \"ngọ\" trong \"giờ Ngọ\", \"chính ngọ\": giữa trưa.","ex":"我们一起吃午饭吧。","exPy":"Wǒmen yìqǐ chī wǔfàn ba.","exVi":"Chúng mình cùng ăn trưa nhé.","w":"我们 一起 吃 午饭 吧。"},{"zh":"晚饭","py":"wǎnfàn","vi":"bữa tối","hv":"vãn phạn","note":"晚 (tối) + 饭.","ex":"晚饭吃什么？","exPy":"Wǎnfàn chī shénme?","exVi":"Bữa tối ăn gì?","w":"晚饭 吃 什么？"},{"zh":"做饭","py":"zuò fàn","vi":"nấu cơm, nấu ăn","hv":"tố phạn","note":"做 = làm. Tiếng Trung \"làm cơm\" chứ không \"nấu cơm\".","ex":"妈妈在做饭。","exPy":"Māma zài zuò fàn.","exVi":"Mẹ đang nấu cơm.","w":"妈妈 在 做饭。"},{"zh":"面条儿","py":"miàntiáor","vi":"mì sợi","hv":"diện điều nhi","note":"面 (bột mì) + 条 (sợi dài). Âm 儿 cuối là giọng Bắc Kinh, viết 面条 cũng được.","ex":"这家店的面条儿很便宜。","exPy":"Zhè jiā diàn de miàntiáor hěn piányi.","exVi":"Mì ở quán này rất rẻ.","w":"这 家 店 的 面条儿 很 便宜。"},{"zh":"饭店","py":"fàndiàn","vi":"nhà hàng; khách sạn","hv":"phạn điếm","note":"Vừa là nhà hàng, vừa có thể là khách sạn lớn (北京饭店 là khách sạn).","ex":"我们晚上去饭店吃饭吧。","exPy":"Wǒmen wǎnshang qù fàndiàn chīfàn ba.","exVi":"Tối nay chúng ta ra nhà hàng ăn nhé.","w":"我们 晚上 去 饭店 吃 饭 吧。"},{"zh":"店","py":"diàn","vi":"cửa hàng, quán","hv":"điếm","note":"\"Điếm\" trong \"tửu điếm\", \"khách điếm\". Đếm bằng 家: 一家店.","ex":"我在书店买了一些书。","exPy":"Wǒ zài shūdiàn mǎi le yìxiē shū.","exVi":"Tôi đã mua vài cuốn sách ở hiệu sách.","w":"我 在 书店 买 了 一些 书。"},{"zh":"书店","py":"shūdiàn","vi":"hiệu sách","hv":"thư điếm","note":"书 (sách) + 店 (cửa hàng). Cứ thế ghép: 花店, 鞋店…","ex":"学校旁边有一个书店。","exPy":"Xuéxiào pángbiān yǒu yí ge shūdiàn.","exVi":"Cạnh trường có một hiệu sách.","w":"学校 旁边 有 一 个 书店。"},{"zh":"一些","py":"yìxiē","vi":"một ít, một vài","hv":"nhất ta","note":"Dùng cho số lượng không xác định, không nhiều: 买一些水果.","ex":"我去买一些水果。","exPy":"Wǒ qù mǎi yìxiē shuǐguǒ.","exVi":"Tôi đi mua ít hoa quả.","w":"我 去 买 一些 水果。"}],"newChars":["条"],"outro":"很好！Xong bài 19."};
G.ROOMS["zh-l020"] = {"id":"zh-l020","lang":"zh","level":1,"no":20,"teacher":"wang","title":"HSK1 · Bài 20 · 上学和上课 Đi học","intro":["我每天七点半上学。","Bài 20: Nói về đi học, vào lớp, tan học, và các cấp trường từ tiểu học tới đại học. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒ měi tiān qī diǎn bàn shàngxué.","gram":{"t":"上 / 下 + danh từ: bắt đầu và kết thúc","b":"上学 · 上课 · 上班 / 下课 · 下班","d":"上 nghĩa là đi tới hoặc bắt đầu, 下 là rời đi hoặc kết thúc. Nhớ một cặp là nhớ được cả nhóm.","ex":[["你几点下课？","Mấy giờ bạn tan học?","Nǐ jǐ diǎn xiàkè?"],["我八点上课，十二点下课。","Tôi vào học lúc tám giờ, tan lúc mười hai giờ.","Wǒ bā diǎn shàngkè, shí'èr diǎn xiàkè."]]},"grams":[{"t":"上 / 下 + danh từ: bắt đầu và kết thúc","b":"上学 · 上课 · 上班 / 下课 · 下班","d":"上 nghĩa là đi tới hoặc bắt đầu, 下 là rời đi hoặc kết thúc. Nhớ một cặp là nhớ được cả nhóm.","ex":[["你几点下课？","Mấy giờ bạn tan học?","Nǐ jǐ diǎn xiàkè?"],["我八点上课，十二点下课。","Tôi vào học lúc tám giờ, tan lúc mười hai giờ.","Wǒ bā diǎn shàngkè, shí'èr diǎn xiàkè."]]},{"t":"上 + cấp học","b":"上小学 · 上中学 · 上大学","d":"Nói \"đang học cấp nào\" thì dùng 上 + tên cấp học, giống \"lên đại học\" của tiếng Việt.","ex":[["她明年上大学。","Năm sau cô ấy lên đại học.","Tā míngnián shàng dàxué."],["你孩子上小学了吗？","Con bạn đi học tiểu học chưa?","Nǐ háizi shàng xiǎoxué le ma?"]]}],"items":[{"zh":"学","py":"xué","vi":"học","hv":"học","note":"\"Học\" trong \"học sinh\". Đi một mình nghĩa như 学习 nhưng gọn hơn: 学汉语, 学开车.","ex":"我每天七点半上学。","exPy":"Wǒ měi tiān qī diǎn bàn shàngxué.","exVi":"Ngày nào tôi cũng đi học lúc bảy rưỡi.","w":"我 每 天 七 点 半 上学。"},{"zh":"上学","py":"shàngxué","vi":"đi học","hv":"thượng học","note":"上 ở đây là \"đi tới\": 上学 (đến trường), 上班 (đi làm).","ex":"我弟弟每天走路上学。","exPy":"Wǒ dìdi měi tiān zǒulù shàngxué.","exVi":"Em trai tôi ngày nào cũng đi bộ đến trường.","w":"我 弟弟 每 天 走路 上学。"},{"zh":"上课","py":"shàngkè","vi":"vào lớp, lên lớp","hv":"thượng khoá","note":"课 = \"khoá\" trong \"khoá học\". Thầy dạy hay trò học đều dùng 上课.","ex":"我们八点上课。","exPy":"Wǒmen bā diǎn shàngkè.","exVi":"Tám giờ chúng tôi vào học.","w":"我们 八 点 上课。"},{"zh":"下课","py":"xiàkè","vi":"tan học, hết giờ","hv":"hạ khoá","note":"上 là bắt đầu, 下 là kết thúc: 上课 / 下课, 上班 / 下班.","ex":"下课了，我们去吃饭吧。","exPy":"Xiàkè le, wǒmen qù chīfàn ba.","exVi":"Tan học rồi, mình đi ăn thôi.","w":"下课 了， 我们 去 吃 饭 吧。"},{"zh":"小学","py":"xiǎoxué","vi":"trường tiểu học","hv":"tiểu học","note":"Chính là \"tiểu học\" tiếng Việt.","ex":"我妹妹在上小学。","exPy":"Wǒ mèimei zài shàng xiǎoxué.","exVi":"Em gái tôi đang học tiểu học.","w":"我 妹妹 在 上 小学。"},{"zh":"小学生","py":"xiǎoxuéshēng","vi":"học sinh tiểu học","hv":"tiểu học sinh","note":"小学 + 生 (người học).","ex":"那些小学生很可爱。","exPy":"Nàxiē xiǎoxuéshēng hěn kě'ài.","exVi":"Mấy em học sinh tiểu học kia rất đáng yêu.","w":"那些 小学生 很 可爱。"},{"zh":"中学","py":"zhōngxué","vi":"trường trung học","hv":"trung học","note":"Gồm cả cấp hai (初中) và cấp ba (高中).","ex":"中学生每天都很忙。","exPy":"Zhōngxuéshēng měi tiān dōu hěn máng.","exVi":"Học sinh trung học ngày nào cũng rất bận.","w":"中学生 每 天 都 很 忙。"},{"zh":"中学生","py":"zhōngxuéshēng","vi":"học sinh trung học","hv":"trung học sinh","note":"中学 + 生.","ex":"我是中学生。","exPy":"Wǒ shì zhōngxuéshēng.","exVi":"Tôi là học sinh trung học.","w":"我 是 中学生。"},{"zh":"大学","py":"dàxué","vi":"trường đại học","hv":"đại học","note":"Chính là \"đại học\". Đếm trường bằng 所: 一所大学.","ex":"他是北京大学的大学生。","exPy":"Tā shì Běijīng Dàxué de dàxuéshēng.","exVi":"Anh ấy là sinh viên Đại học Bắc Kinh.","w":"他 是 北京 大学 的 大学生。"},{"zh":"大学生","py":"dàxuéshēng","vi":"sinh viên đại học","hv":"đại học sinh","note":"Tiếng Việt nói \"sinh viên\", tiếng Trung nói 大学生.","ex":"我哥哥是大学生。","exPy":"Wǒ gēge shì dàxuéshēng.","exVi":"Anh trai tôi là sinh viên.","w":"我 哥哥 是 大学生。"}],"newChars":["课"],"outro":"很好！Xong bài 20."};
G.ROOMS["zh-l021"] = {"id":"zh-l021","lang":"zh","level":1,"no":21,"teacher":"wang","title":"HSK1 · Bài 21 · 请问，您是哪国人？ Làm quen","intro":["你好，请问你是哪国人？","Bài 21: Chào hỏi lịch sự với 你好, 请问, giới thiệu người thân, bạn bè, quốc gia, và đếm thứ tự bằng 第. Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ hǎo, qǐngwèn nǐ shì nǎ guó rén?","gram":{"t":"第 + số = số thứ tự","b":"第一 · 第二 · 第三 · 第一次","d":"Giống \"đệ nhất\", \"đệ nhị\" của tiếng Việt. Muốn đếm thêm danh từ thì thêm lượng từ: 第一个人, 第二天.","ex":[["他是第一个来的。","Anh ấy là người đến đầu tiên.","Tā shì dì yī ge lái de."],["第二天我们去了长城。","Ngày hôm sau chúng tôi đi Vạn Lý Trường Thành.","Dì èr tiān wǒmen qù le Chángchéng."]]},"grams":[{"t":"第 + số = số thứ tự","b":"第一 · 第二 · 第三 · 第一次","d":"Giống \"đệ nhất\", \"đệ nhị\" của tiếng Việt. Muốn đếm thêm danh từ thì thêm lượng từ: 第一个人, 第二天.","ex":[["他是第一个来的。","Anh ấy là người đến đầu tiên.","Tā shì dì yī ge lái de."],["第二天我们去了长城。","Ngày hôm sau chúng tôi đi Vạn Lý Trường Thành.","Dì èr tiān wǒmen qù le Chángchéng."]]},{"t":"请问 mở đầu câu hỏi lịch sự","b":"请问 + câu hỏi","d":"Với người lạ, người lớn tuổi, nhân viên phục vụ, nên mở đầu bằng 请问. Câu sau vẫn giữ nguyên là câu hỏi bình thường.","ex":[["请问，现在几点？","Cho hỏi, bây giờ mấy giờ?","Qǐngwèn, xiànzài jǐ diǎn?"],["请问，您贵姓？","Xin hỏi, ông họ gì ạ?","Qǐngwèn, nín guì xìng?"]]}],"items":[{"zh":"你好","py":"nǐ hǎo","vi":"xin chào","hv":"nễ hảo","note":"Hai thanh 3 đi liền nên 你 đọc thanh 2: ní hǎo. Lịch sự hơn thì nói 您好.","ex":"你好，请问你是哪国人？","exPy":"Nǐ hǎo, qǐngwèn nǐ shì nǎ guó rén?","exVi":"Xin chào, cho hỏi bạn là người nước nào?","w":"你好， 请问 你 是 哪 国 人？"},{"zh":"请问","py":"qǐngwèn","vi":"xin hỏi, cho hỏi","hv":"thỉnh vấn","note":"请 (xin) + 问 (hỏi). Mở đầu câu hỏi người lạ, giống \"cho tôi hỏi\".","ex":"请问，洗手间在哪里？","exPy":"Qǐngwèn, xǐshǒujiān zài nǎlǐ?","exVi":"Cho hỏi, nhà vệ sinh ở đâu?","w":"请问， 洗手间 在 哪里？"},{"zh":"国","py":"guó","vi":"nước, quốc gia","hv":"quốc","note":"\"Quốc\" trong \"quốc gia\". Bên trong là chữ 玉 (ngọc) được bao bởi bức tường.","ex":"我是越南人，我在中国读书。","exPy":"Wǒ shì Yuènán rén, wǒ zài Zhōngguó dúshū.","exVi":"Tôi là người Việt Nam, tôi đang đi học ở Trung Quốc.","w":"我 是 越 南 人， 我 在 中国 读书。"},{"zh":"家人","py":"jiārén","vi":"người nhà, gia đình","hv":"gia nhân","note":"Khác \"gia nhân\" (người hầu) của tiếng Việt: 家人 là người thân trong nhà.","ex":"我的家人都很好。","exPy":"Wǒ de jiārén dōu hěn hǎo.","exVi":"Người nhà tôi đều khoẻ.","w":"我 的 家人 都 很 好。"},{"zh":"小朋友","py":"xiǎopéngyǒu","vi":"bạn nhỏ, em bé","hv":"tiểu bằng hữu","note":"Người lớn gọi trẻ em là 小朋友, thân thiện như \"bạn nhỏ\" trong tiếng Việt.","ex":"小朋友，你几岁了？","exPy":"Xiǎopéngyǒu, nǐ jǐ suì le?","exVi":"Bạn nhỏ ơi, cháu mấy tuổi rồi?","w":"小朋友， 你 几 岁 了？"},{"zh":"男朋友","py":"nánpéngyou","vi":"bạn trai, người yêu (nam)","hv":"nam bằng hữu","note":"男 (nam) + 朋友. Chỉ người yêu, không phải \"bạn là con trai\".","ex":"她有男朋友了。","exPy":"Tā yǒu nánpéngyou le.","exVi":"Cô ấy có bạn trai rồi.","w":"她 有 男朋友 了。"},{"zh":"女朋友","py":"nǚpéngyou","vi":"bạn gái, người yêu (nữ)","hv":"nữ bằng hữu","note":"Đối xứng với 男朋友.","ex":"你有女朋友吗？","exPy":"Nǐ yǒu nǚpéngyou ma?","exVi":"Bạn có bạn gái chưa?","w":"你 有 女朋友 吗？"},{"zh":"女士","py":"nǚshì","vi":"quý bà, cô (cách gọi lịch sự)","hv":"nữ sĩ","note":"Đặt sau họ: 王女士 (bà Vương). Trên thông báo: 女士们，先生们 (thưa quý bà, quý ông).","ex":"李女士，您好！","exPy":"Lǐ nǚshì, nín hǎo!","exVi":"Chào bà Lý!","w":"李 女士， 您 好！"},{"zh":"读书","py":"dúshū","vi":"đọc sách; đi học","hv":"độc thư","note":"\"Độc thư\" là đọc sách, nhưng khẩu ngữ còn có nghĩa là đang đi học: 他在大学读书.","ex":"我喜欢读书。","exPy":"Wǒ xǐhuan dúshū.","exVi":"Tôi thích đọc sách.","w":"我 喜欢 读书。"},{"zh":"汉字","py":"Hànzì","vi":"chữ Hán","hv":"Hán tự","note":"Chính là \"Hán tự\". Người Việt biết âm Hán Việt nên học chữ Hán nhanh hơn người phương Tây.","ex":"这是我第一次学汉字。","exPy":"Zhè shì wǒ dì yī cì xué Hànzì.","exVi":"Đây là lần đầu tôi học chữ Hán.","w":"这 是 我 第一 次 学 汉字。"},{"zh":"第","py":"dì","vi":"thứ (số thứ tự)","hv":"đệ","note":"\"Đệ nhất\" là 第一. Đặt 第 trước số đếm để thành số thứ tự.","ex":"这是我第一次来北京。","exPy":"Zhè shì wǒ dì yī cì lái Běijīng.","exVi":"Đây là lần đầu tôi đến Bắc Kinh.","w":"这 是 我 第一 次 来 北京。"}],"newChars":["问","男","士","第"],"outro":"很好！Xong bài 21."};
G.ROOMS["zh-l022"] = {"id":"zh-l022","lang":"zh","level":1,"no":22,"teacher":"wang","title":"HSK1 · Bài 22 · 坐火车 Xe, điện thoại, ca hát","intro":["我下班以后坐火车回家。","Bài 22: Nói về đi xe, lái xe, tan làm, gọi điện, nghe thấy, gặp nhau, và hát. Bấm 1 · Học để bắt đầu."],"introPy":"Wǒ xiàbān yǐhòu zuò huǒchē huí jiā.","gram":{"t":"看 / 听 + 见: có kết quả","b":"看 → 看见 · 听 → 听见","d":"看, 听 chỉ là hành động. Thêm 见 thì nghĩa là đã thấy, đã nghe được. Phủ định dùng 没: 没听见 (không nghe thấy).","ex":[["我看了，可是没看见他。","Tôi đã nhìn, nhưng không thấy anh ấy.","Wǒ kàn le, kěshì méi kànjiàn tā."],["对不起，我没听见。","Xin lỗi, tôi không nghe thấy.","Duìbuqǐ, wǒ méi tīngjiàn."]]},"grams":[{"t":"看 / 听 + 见: có kết quả","b":"看 → 看见 · 听 → 听见","d":"看, 听 chỉ là hành động. Thêm 见 thì nghĩa là đã thấy, đã nghe được. Phủ định dùng 没: 没听见 (không nghe thấy).","ex":[["我看了，可是没看见他。","Tôi đã nhìn, nhưng không thấy anh ấy.","Wǒ kàn le, kěshì méi kànjiàn tā."],["对不起，我没听见。","Xin lỗi, tôi không nghe thấy.","Duìbuqǐ, wǒ méi tīngjiàn."]]},{"t":"给 + người + 打电话","b":"Chủ ngữ + 给 + người + 打电话","d":"Tiếng Trung đặt người nhận lên trước động từ bằng 给, không nói 打电话给 trong câu đơn giản.","ex":[["晚上我给你打电话。","Tối tôi gọi điện cho bạn.","Wǎnshang wǒ gěi nǐ dǎ diànhuà."],["你给他打电话了吗？","Bạn gọi cho anh ấy chưa?","Nǐ gěi tā dǎ diànhuà le ma?"]]}],"items":[{"zh":"车","py":"chē","vi":"xe","hv":"xa","note":"Chữ tượng hình: nhìn từ trên xuống thấy bánh xe và trục. \"Xa\" trong \"xa lộ\" là chữ này.","ex":"我下班以后坐火车回家。","exPy":"Wǒ xiàbān yǐhòu zuò huǒchē huí jiā.","exVi":"Tan làm tôi đi tàu hoả về nhà.","w":"我 下班 以后 坐 火车 回 家。"},{"zh":"火车","py":"huǒchē","vi":"tàu hoả","hv":"hoả xa","note":"Chính là \"hoả xa\": xe chạy bằng lửa, vì tàu xưa chạy bằng hơi nước đốt than.","ex":"我们坐火车去上海。","exPy":"Wǒmen zuò huǒchē qù Shànghǎi.","exVi":"Chúng tôi đi tàu hoả đến Thượng Hải.","w":"我们 坐 火车 去 上 海。"},{"zh":"开车","py":"kāichē","vi":"lái xe","hv":"khai xa","note":"开 = mở, vận hành. Lái ô tô dùng 开车, đi xe đạp thì dùng 骑.","ex":"你会开车吗？","exPy":"Nǐ huì kāichē ma?","exVi":"Bạn biết lái xe không?","w":"你 会 开车 吗？"},{"zh":"下班","py":"xiàbān","vi":"tan làm","hv":"hạ ban","note":"班 = ca làm. 上班 đi làm, 下班 tan làm.","ex":"你几点下班？","exPy":"Nǐ jǐ diǎn xiàbān?","exVi":"Mấy giờ bạn tan làm?","w":"你 几 点 下班？"},{"zh":"电话","py":"diànhuà","vi":"điện thoại; cuộc gọi","hv":"điện thoại","note":"Chính là \"điện thoại\". Gọi điện là 打电话.","ex":"我给妈妈打电话。","exPy":"Wǒ gěi māma dǎ diànhuà.","exVi":"Tôi gọi điện cho mẹ.","w":"我 给 妈妈 打电话。"},{"zh":"见","py":"jiàn","vi":"gặp; thấy","hv":"kiến","note":"\"Kiến\" trong \"kiến thức\", \"hội kiến\". Đã gặp trong 再见.","ex":"我听见有人叫我。","exPy":"Wǒ tīngjiàn yǒu rén jiào wǒ.","exVi":"Tôi nghe thấy có người gọi tôi.","w":"我 听见 有 人 叫 我。"},{"zh":"听见","py":"tīngjiàn","vi":"nghe thấy","hv":"thính kiến","note":"听 là nghe (hành động), 听见 là nghe THẤY (có kết quả). Giống 看 và 看见.","ex":"你听见了吗？","exPy":"Nǐ tīngjiàn le ma?","exVi":"Bạn có nghe thấy không?","w":"你 听见 了 吗？"},{"zh":"唱","py":"chàng","vi":"hát","hv":"xướng","note":"\"Xướng\" trong \"đề xướng\", \"xướng ca\". Có bộ 口 (miệng).","ex":"我很喜欢唱中国歌。","exPy":"Wǒ hěn xǐhuan chàng Zhōngguó gē.","exVi":"Tôi rất thích hát bài hát tiếng Trung.","w":"我 很 喜欢 唱 中国 歌。"},{"zh":"歌","py":"gē","vi":"bài hát","hv":"ca","note":"\"Ca\" trong \"ca sĩ\", \"ca khúc\". Hát là 唱歌.","ex":"我们一起唱歌吧。","exPy":"Wǒmen yìqǐ chànggē ba.","exVi":"Chúng mình cùng hát nhé.","w":"我们 一起 唱歌 吧。"},{"zh":"好听","py":"hǎotīng","vi":"hay, dễ nghe","hv":"hảo thính","note":"好 + 听: nghe thấy hay. Dùng cho bài hát, giọng nói, cái tên.","ex":"这首歌很好听。","exPy":"Zhè shǒu gē hěn hǎotīng.","exVi":"Bài hát này rất hay.","w":"这 首 歌 很 好听。"}],"newChars":["火","班","唱","歌"],"outro":"很好！Xong bài 22."};
G.ROOMS["zh-l023"] = {"id":"zh-l023","lang":"zh","level":1,"no":23,"teacher":"wang","title":"HSK1 · Bài 23 · 有点儿不舒服 Vui chơi, ốm, mưa","intro":["你怎么了？有点儿不舒服吗？","Bài 23: Khen hay, đẹp, vui; nói có việc hay không có việc; nói hơi ốm, đi khám, ngủ, và trời mưa. Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ zěnme le? Yǒudiǎnr bù shūfu ma?","gram":{"t":"有点儿 + tính từ","b":"有点儿 + 贵 / 累 / 冷","d":"Nói \"hơi…\" về điều không như ý. Nói điều tốt thì dùng 比较 hoặc 很, không dùng 有点儿: nói 有点儿贵 nhưng không nói 有点儿便宜.","ex":[["这件衣服有点儿贵。","Bộ quần áo này hơi đắt.","Zhè jiàn yīfu yǒudiǎnr guì."],["我有点儿累，想休息一下。","Tôi hơi mệt, muốn nghỉ một lát.","Wǒ yǒudiǎnr lèi, xiǎng xiūxi yíxià."]]},"grams":[{"t":"有点儿 + tính từ","b":"有点儿 + 贵 / 累 / 冷","d":"Nói \"hơi…\" về điều không như ý. Nói điều tốt thì dùng 比较 hoặc 很, không dùng 有点儿: nói 有点儿贵 nhưng không nói 有点儿便宜.","ex":[["这件衣服有点儿贵。","Bộ quần áo này hơi đắt.","Zhè jiàn yīfu yǒudiǎnr guì."],["我有点儿累，想休息一下。","Tôi hơi mệt, muốn nghỉ một lát.","Wǒ yǒudiǎnr lèi, xiǎng xiūxi yíxià."]]},{"t":"不要 + động từ: khuyên đừng làm","b":"不要 + động từ (+ 了)","d":"Dùng để nhắc nhở, cấm đoán. Trong biển báo, thông báo rất hay gặp.","ex":[["不要哭了。","Đừng khóc nữa.","Búyào kū le."],["下雨了，不要出去。","Trời mưa rồi, đừng ra ngoài.","Xià yǔ le, búyào chūqu."]]}],"items":[{"zh":"好看","py":"hǎokàn","vi":"đẹp, hay (để xem)","hv":"hảo khán","note":"好 + 看: xem thấy hay. Dùng cho người, quần áo, phim ảnh.","ex":"你的衣服很好看。","exPy":"Nǐ de yīfu hěn hǎokàn.","exVi":"Quần áo của bạn đẹp lắm.","w":"你 的 衣服 很 好看。"},{"zh":"好玩儿","py":"hǎowánr","vi":"vui, thú vị (để chơi)","hv":"hảo ngoạn nhi","note":"好 + 玩 (chơi). Nói về nơi chốn, trò chơi, hoạt động.","ex":"北京很好玩儿。","exPy":"Běijīng hěn hǎowánr.","exVi":"Bắc Kinh chơi vui lắm.","w":"北京 很 好玩儿。"},{"zh":"电影院","py":"diànyǐngyuàn","vi":"rạp chiếu phim","hv":"điện ảnh viện","note":"电影 (điện ảnh) + 院 (viện): như 医院 (y viện, bệnh viện).","ex":"我们去电影院看电影吧。","exPy":"Wǒmen qù diànyǐngyuàn kàn diànyǐng ba.","exVi":"Mình ra rạp xem phim đi.","w":"我们 去 电影院 看 电影 吧。"},{"zh":"事","py":"shì","vi":"việc, chuyện","hv":"sự","note":"\"Sự\" trong \"sự việc\", \"sự kiện\". Hỏi \"có chuyện gì không\" là 有事吗？","ex":"你找我有事吗？","exPy":"Nǐ zhǎo wǒ yǒu shì ma?","exVi":"Bạn tìm tôi có việc gì không?","w":"你 找 我 有 事 吗？"},{"zh":"没事","py":"méishì","vi":"không sao; rảnh","hv":"một sự","note":"Hai nghĩa: \"không sao đâu\" (khi ai xin lỗi) và \"không có việc gì, đang rảnh\".","ex":"没事，没事，别担心。","exPy":"Méishì, méishì, bié dānxīn.","exVi":"Không sao, không sao, đừng lo.","w":"没事， 没事， 别 担心。"},{"zh":"有点儿","py":"yǒudiǎnr","vi":"hơi, có chút","hv":"hữu điểm nhi","note":"Đứng trước tính từ, thường cho điều không vừa ý: 有点儿贵 (hơi đắt), 有点儿累 (hơi mệt).","ex":"你怎么了？有点儿不舒服吗？","exPy":"Nǐ zěnme le? Yǒudiǎnr bù shūfu ma?","exVi":"Bạn sao thế? Hơi khó chịu à?","w":"你 怎么 了？ 有点儿 不 舒服 吗？"},{"zh":"有些","py":"yǒuxiē","vi":"một số; hơi","hv":"hữu ta","note":"Như 有的: 有些人 (một số người). Đứng trước tính từ thì giống 有点儿.","ex":"有些同学还没来。","exPy":"Yǒuxiē tóngxué hái méi lái.","exVi":"Một số bạn vẫn chưa đến.","w":"有些 同学 还 没 来。"},{"zh":"病","py":"bìng","vi":"bệnh; bị ốm","hv":"bệnh","note":"\"Bệnh\" tiếng Việt chính là chữ này. Bộ 疒 (bệnh) ở bên ngoài.","ex":"我病了，要去看病。","exPy":"Wǒ bìng le, yào qù kànbìng.","exVi":"Tôi bị ốm, phải đi khám.","w":"我 病 了， 要 去 看病。"},{"zh":"看病","py":"kànbìng","vi":"đi khám bệnh; khám bệnh","hv":"khán bệnh","note":"Bệnh nhân đi khám hay bác sĩ khám đều dùng 看病.","ex":"我下午去医院看病。","exPy":"Wǒ xiàwǔ qù yīyuàn kànbìng.","exVi":"Chiều nay tôi đi bệnh viện khám.","w":"我 下午 去 医院 看病。"},{"zh":"睡","py":"shuì","vi":"ngủ","hv":"thuỵ","note":"\"Thuỵ\" trong \"thuỵ miên\". Có bộ 目 (mắt). Đi một mình hay gặp trong 睡吧, 睡了.","ex":"我昨天睡得很晚。","exPy":"Wǒ zuótiān shuì de hěn wǎn.","exVi":"Hôm qua tôi ngủ rất muộn.","w":"我 昨天 睡 得 很 晚。"},{"zh":"雨","py":"yǔ","vi":"mưa","hv":"vũ","note":"Chữ tượng hình: những giọt mưa rơi dưới bầu trời. \"Vũ\" trong \"phong vũ\".","ex":"下雨了，我们在家看电影吧。","exPy":"Xià yǔ le, wǒmen zài jiā kàn diànyǐng ba.","exVi":"Trời mưa rồi, mình ở nhà xem phim nhé.","w":"下雨 了， 我们 在 家 看 电影 吧。"},{"zh":"不要","py":"búyào","vi":"đừng; không cần","hv":"bất yếu","note":"Đứng trước động từ để khuyên ngăn: 不要说话 (đừng nói chuyện). Mạnh hơn 别 một chút.","ex":"不要在这里吃东西。","exPy":"Búyào zài zhèlǐ chī dōngxi.","exVi":"Đừng ăn uống ở đây.","w":"不要 在 这里 吃 东西。"}],"newChars":["玩","事","病","要"],"outro":"很好！Xong bài 23."};
G.ROOMS["zh-l024"] = {"id":"zh-l024","lang":"zh","level":1,"no":24,"teacher":"wang","title":"HSK1 · Bài 24 · 我的家人 Người thân trong nhà","intro":["你家有几个孩子？","Bài 24: Gọi tên đầy đủ anh chị em, vợ chồng, và dùng 大家 để xưng hô với cả nhóm. Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ jiā yǒu jǐ ge háizi?","gram":{"t":"Anh chị em gọi theo TUỔI, không theo giới tính trước","b":"哥哥 anh · 姐姐 chị · 弟弟 em trai · 妹妹 em gái","d":"Giống hệt tiếng Việt và khác hẳn tiếng Anh (brother/sister không phân biệt lớn nhỏ). Người Việt học phần này rất nhanh vì tư duy giống nhau.","ex":[["我有一个哥哥和一个妹妹。","Tôi có một anh trai và một em gái.","Wǒ yǒu yí ge gēge hé yí ge mèimei."],["你有弟弟吗？","Bạn có em trai không?","Nǐ yǒu dìdi ma?"]]},"grams":[{"t":"Anh chị em gọi theo TUỔI, không theo giới tính trước","b":"哥哥 anh · 姐姐 chị · 弟弟 em trai · 妹妹 em gái","d":"Giống hệt tiếng Việt và khác hẳn tiếng Anh (brother/sister không phân biệt lớn nhỏ). Người Việt học phần này rất nhanh vì tư duy giống nhau.","ex":[["我有一个哥哥和一个妹妹。","Tôi có một anh trai và một em gái.","Wǒ yǒu yí ge gēge hé yí ge mèimei."],["你有弟弟吗？","Bạn có em trai không?","Nǐ yǒu dìdi ma?"]]},{"t":"男 / 女 + danh từ","b":"男 + nghề · 女 + nghề","d":"Ghép thẳng vào trước danh từ để chỉ giới tính: 男老师 (thầy giáo), 女医生 (nữ bác sĩ). Muốn nói \"người đó là nam\" thì dùng 是男的.","ex":[["她是女医生。","Cô ấy là nữ bác sĩ.","Tā shì nǚ yīshēng."],["那个男孩子是我弟弟。","Cậu bé kia là em trai tôi.","Nàge nán háizi shì wǒ dìdi."]]},{"t":"大家 — chào cả nhóm","b":"大家好！· 大家 + 都 + động từ","d":"大家 là chủ ngữ số nhiều, nên rất hay đi kèm 都. Mở đầu một bài nói hay tin nhắn nhóm, người Trung Quốc luôn dùng 大家好.","ex":[["大家好，我叫小明。","Chào mọi người, tôi tên Tiểu Minh.","Dàjiā hǎo, wǒ jiào Xiǎomíng."],["大家都是学生。","Mọi người đều là học sinh.","Dàjiā dōu shì xuésheng."]]}],"items":[{"zh":"哥哥","py":"gēge","vi":"anh trai","hv":"ca ca","note":"Tiếng Việt có \"đại ca\" (anh cả) — chính là chữ 哥 này. Chữ thứ hai đọc nhẹ.","ex":"我有一个哥哥和一个妹妹。","exPy":"Wǒ yǒu yí ge gēge hé yí ge mèimei.","exVi":"Tôi có một anh trai và một em gái.","w":"我 有 一 个 哥哥 和 一 个 妹妹。"},{"zh":"姐姐","py":"jiějie","vi":"chị gái","hv":"tỷ tỷ","note":"Bộ 女 bên trái. Tiếng Việt có \"tỷ muội\" (chị em gái) trong văn cổ.","ex":"我姐姐在北京工作。","exPy":"Wǒ jiějie zài Běijīng gōngzuò.","exVi":"Chị tôi làm việc ở Bắc Kinh.","w":"我 姐姐 在 北京 工作。"},{"zh":"弟弟","py":"dìdi","vi":"em trai","hv":"đệ đệ","note":"Tiếng Việt có \"đệ tử\", \"huynh đệ\" — cùng chữ 弟.","ex":"弟弟今年十岁。","exPy":"Dìdi jīnnián shí suì.","exVi":"Em trai tôi năm nay mười tuổi.","w":"弟弟 今年 十 岁。"},{"zh":"妹妹","py":"mèimei","vi":"em gái","hv":"muội muội","note":"Tiếng Việt có \"tỷ muội\". Bộ 女 + 未.","ex":"我妹妹很漂亮。","exPy":"Wǒ mèimei hěn piàoliang.","exVi":"Em gái tôi rất xinh.","w":"我 妹妹 很 漂亮。"},{"zh":"孩子","py":"háizi","vi":"đứa trẻ, con cái","hv":"hài tử","note":"孩 có bộ 子 (con). Dùng cho con mình lẫn trẻ con nói chung.","ex":"你家有几个孩子？","exPy":"Nǐ jiā yǒu jǐ ge háizi?","exVi":"Nhà bạn có mấy đứa con?","w":"你 家 有 几 个 孩子？"},{"zh":"丈夫","py":"zhàngfu","vi":"người chồng","hv":"trượng phu","note":"Chính là \"trượng phu\" tiếng Việt. Cách nói thân mật hơn là 老公 lǎogōng.","ex":"她丈夫是中国人。","exPy":"Tā zhàngfu shì Zhōngguó rén.","exVi":"Chồng cô ấy là người Trung Quốc.","w":"她 丈夫 是 中国 人。"},{"zh":"妻子","py":"qīzi","vi":"người vợ","hv":"thê tử","note":"妻 = \"thê\" trong \"phu thê\". Cách nói thân mật là 老婆 lǎopo.","ex":"我妻子不会说汉语。","exPy":"Wǒ qīzi bú huì shuō Hànyǔ.","exVi":"Vợ tôi không biết nói tiếng Trung.","w":"我 妻子 不 会 说 汉语。"},{"zh":"男","py":"nán","vi":"nam, đàn ông","hv":"nam","note":"田 (ruộng) trên 力 (sức) — người đàn ông ra đồng dùng sức. Tiếng Việt: \"nam giới\".","ex":"我们家有男有女。","exPy":"Wǒmen jiā yǒu nán yǒu nǚ.","exVi":"Nhà tôi có cả nam cả nữ.","w":"我们 家 有 男 有 女。"},{"zh":"女","py":"nǚ","vi":"nữ, phụ nữ","hv":"nữ","note":"Cũng là bộ thủ số 32 bạn đã học. Tiếng Việt: \"nữ giới\", \"thiếu nữ\".","ex":"她是女老师。","exPy":"Tā shì nǚ lǎoshī.","exVi":"Cô ấy là cô giáo.","w":"她 是 女 老师。"},{"zh":"大家","py":"dàjiā","vi":"mọi người, cả nhà","hv":"đại gia","note":"大 (lớn) + 家 (nhà) = cả nhà, mọi người. KHÁC hẳn nghĩa \"đại gia\" (người giàu) của tiếng Việt hiện đại.","ex":"大家好！","exPy":"Dàjiā hǎo!","exVi":"Chào mọi người!","w":"大家 好！"}],"newChars":["哥","弟","妹","孩","丈","妻","男"],"outro":"很好！Xong bài 24."};
G.ROOMS["zh-l026"] = {"id":"zh-l026","lang":"zh","level":1,"no":26,"teacher":"wang","title":"HSK1 · Bài 26 · 时间和习惯 Thời gian và thói quen","intro":["你每天几点起床？","Bài 26: Kể lịch sinh hoạt hằng ngày, dùng 从…到…, 每…都… và phân biệt 小时 với 点. Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ měi tiān jǐ diǎn qǐchuáng?","gram":{"t":"从 … 到 … — từ đâu đến đâu","b":"从 + mốc đầu + 到 + mốc cuối","d":"Dùng được cho cả thời gian lẫn nơi chốn, giống hệt \"từ… đến…\" tiếng Việt. Cả cụm đứng TRƯỚC động từ.","ex":[["我从八点到十点学习。","Tôi học từ 8 giờ đến 10 giờ.","Wǒ cóng bā diǎn dào shí diǎn xuéxí."],["从我家到学校很近。","Từ nhà tôi đến trường rất gần.","Cóng wǒ jiā dào xuéxiào hěn jìn."]]},"grams":[{"t":"从 … 到 … — từ đâu đến đâu","b":"从 + mốc đầu + 到 + mốc cuối","d":"Dùng được cho cả thời gian lẫn nơi chốn, giống hệt \"từ… đến…\" tiếng Việt. Cả cụm đứng TRƯỚC động từ.","ex":[["我从八点到十点学习。","Tôi học từ 8 giờ đến 10 giờ.","Wǒ cóng bā diǎn dào shí diǎn xuéxí."],["从我家到学校很近。","Từ nhà tôi đến trường rất gần.","Cóng wǒ jiā dào xuéxiào hěn jìn."]]},{"t":"每 … 都 … — cứ mỗi… đều…","b":"每 + (lượng từ) + danh từ + 都 + động từ","d":"每 gần như luôn đi kèm 都 ở vế sau. Riêng 每天, 每年, 每月 không cần lượng từ; còn 每个人, 每本书 thì phải có.","ex":[["我每天都写汉字。","Ngày nào tôi cũng viết chữ Hán.","Wǒ měi tiān dōu xiě Hànzì."],["每个人都有名字。","Ai cũng có tên.","Měi ge rén dōu yǒu míngzi."]]},{"t":"小时 hay 点 — độ dài hay thời điểm?","b":"两点 = 2 giờ (thời điểm) · 两个小时 = 2 tiếng (độ dài)","d":"Lỗi kinh điển của người mới. 我学了两点 là sai hoàn toàn. Nhớ: 小时 luôn cần lượng từ 个 đứng trước, còn 点 thì không.","ex":[["现在两点。","Bây giờ 2 giờ.","Xiànzài liǎng diǎn."],["我睡了八个小时。","Tôi ngủ tám tiếng.","Wǒ shuì le bā ge xiǎoshí."]]},{"t":"就 — nhấn mạnh việc xảy ra sớm","b":"mốc thời gian + 就 + động từ + 了","d":"So sánh: 我七点起床 (tôi dậy lúc 7 giờ — trung tính) và 我七点就起床了 (mới 7 giờ tôi ĐÃ dậy rồi — ý là sớm). Ngược lại với 才 cái (mãi mới).","ex":[["他五点就来了。","Mới 5 giờ anh ấy đã đến rồi.","Tā wǔ diǎn jiù lái le."],["我吃完就走。","Tôi ăn xong là đi ngay.","Wǒ chī wán jiù zǒu."]]}],"items":[{"zh":"时间","py":"shíjiān","vi":"thời gian","hv":"thời gian","note":"Chính là \"thời gian\" tiếng Việt, không cần học thuộc gì thêm.","ex":"我没有时间休息。","exPy":"Wǒ méiyǒu shíjiān xiūxi.","exVi":"Tôi không có thời gian nghỉ.","w":"我 没有 时间 休息。"},{"zh":"小时","py":"xiǎoshí","vi":"tiếng đồng hồ, giờ (khoảng dài)","hv":"tiểu thời","note":"QUAN TRỌNG: 小时 là ĐỘ DÀI (hai tiếng), còn 点 là THỜI ĐIỂM (hai giờ). Đừng lẫn.","ex":"晚上我看一个小时电视。","exPy":"Wǎnshang wǒ kàn yí ge xiǎoshí diànshì.","exVi":"Buổi tối tôi xem tivi một tiếng.","w":"晚上 我 看 一 个 小时 电视。"},{"zh":"早上","py":"zǎoshang","vi":"buổi sáng sớm","hv":"tảo thượng","note":"早 có bộ 日 (mặt trời) ở trên. Sớm hơn 上午 — khoảng 5 đến 9 giờ.","ex":"我每天早上六点起床。","exPy":"Wǒ měi tiān zǎoshang liù diǎn qǐchuáng.","exVi":"Sáng nào tôi cũng dậy lúc 6 giờ.","w":"我 每 天 早上 六 点 起床。"},{"zh":"晚上","py":"wǎnshang","vi":"buổi tối","hv":"vãn thượng","note":"晚 cũng có bộ 日. Tiếng Việt: \"vãn\" trong \"chiều vãn\", \"vãn cảnh\".","ex":"晚上我看电视。","exPy":"Wǎnshang wǒ kàn diànshì.","exVi":"Buổi tối tôi xem tivi.","w":"晚上 我 看 电视。"},{"zh":"起床","py":"qǐchuáng","vi":"ngủ dậy, rời giường","hv":"khởi sàng","note":"起 (dậy) + 床 (giường, bộ 广 mái nhà). Tiếng Việt: \"khởi hành\", \"khởi động\".","ex":"你每天几点起床？","exPy":"Nǐ měi tiān jǐ diǎn qǐchuáng?","exVi":"Ngày nào bạn cũng dậy lúc mấy giờ?","w":"你 每 天 几 点 起床？"},{"zh":"每","py":"měi","vi":"mỗi, mọi","hv":"mỗi","note":"Âm Hán Việt đúng là \"mỗi\" — chính là từ \"mỗi\" tiếng Việt đang dùng hằng ngày.","ex":"我每个星期去两次。","exPy":"Wǒ měi ge xīngqī qù liǎng cì.","exVi":"Mỗi tuần tôi đi hai lần.","w":"我 每 个 星期 去 两 次。"},{"zh":"次","py":"cì","vi":"lần, lượt","hv":"thứ","note":"Đếm số lần làm việc gì: 一次 (một lần), 第一次 (lần đầu tiên). Tiếng Việt: \"thứ tự\", \"lần thứ\".","ex":"这是我第一次来北京。","exPy":"Zhè shì wǒ dì-yī cì lái Běijīng.","exVi":"Đây là lần đầu tôi đến Bắc Kinh.","w":"这 是 我 第一 次 来 北京。"},{"zh":"从","py":"cóng","vi":"từ (mốc bắt đầu)","hv":"tòng","note":"Hai chữ 人 nối nhau — người theo sau người. Tiếng Việt: \"tòng quân\", \"phục tòng\".","ex":"我从八点到十二点上课。","exPy":"Wǒ cóng bā diǎn dào shí'èr diǎn shàngkè.","exVi":"Tôi học từ 8 giờ đến 12 giờ.","w":"我 从 八 点 到 十 二 点 上课。"},{"zh":"到","py":"dào","vi":"đến, tới","hv":"đáo","note":"Có bộ 刂 bên phải. Tiếng Việt: \"chu đáo\", \"đáo hạn\".","ex":"他六点就到了。","exPy":"Tā liù diǎn jiù dào le.","exVi":"Mới 6 giờ anh ấy đã tới rồi.","w":"他 六 点 就 到 了。"},{"zh":"就","py":"jiù","vi":"liền, ngay, thì","hv":"tựu","note":"Chữ rất khó dịch. Nghĩa cốt lõi: việc xảy ra SỚM hoặc NHANH hơn mong đợi.","ex":"我七点就起床了。","exPy":"Wǒ qī diǎn jiù qǐchuáng le.","exVi":"Mới 7 giờ tôi đã dậy rồi.","w":"我 七 点 就 起床 了。"}],"newChars":["间","早","晚","床","每","从","就"],"outro":"很好！Xong bài 26."};
G.ROOMS["zh-l029"] = {"id":"zh-l029","lang":"zh","level":1,"no":29,"teacher":"wang","title":"HSK1 · Bài 29 · 颜色和衣服 Màu sắc và quần áo","intro":["你喜欢什么颜色？","Bài 29: Gọi tên màu sắc, nói về quần áo và đồ dùng, dùng đúng lượng từ 件. Bấm 1 · Học để bắt đầu."],"introPy":"Nǐ xǐhuan shénme yánsè?","gram":{"t":"Màu sắc: thêm 色 hay không?","b":"红色的衣服 · 衣服是红色的 · 红衣服","d":"色 sè nghĩa là \"màu\". Đứng trước danh từ thì cả hai cách đều được (红衣服 hoặc 红色的衣服). Nhưng làm vị ngữ thì phải đủ: 这件衣服是红色的.","ex":[["我要那件白色的。","Tôi lấy cái màu trắng kia.","Wǒ yào nà jiàn báisè de."],["他的手机是黑色的。","Điện thoại anh ấy màu đen.","Tā de shǒujī shì hēisè de."]]},"grams":[{"t":"Màu sắc: thêm 色 hay không?","b":"红色的衣服 · 衣服是红色的 · 红衣服","d":"色 sè nghĩa là \"màu\". Đứng trước danh từ thì cả hai cách đều được (红衣服 hoặc 红色的衣服). Nhưng làm vị ngữ thì phải đủ: 这件衣服是红色的.","ex":[["我要那件白色的。","Tôi lấy cái màu trắng kia.","Wǒ yào nà jiàn báisè de."],["他的手机是黑色的。","Điện thoại anh ấy màu đen.","Tā de shǒujī shì hēisè de."]]},{"t":"Lượng từ phải hợp với đồ vật","b":"一件衣服 · 一块手表 · 一个手机 · 一双鞋","d":"Đây là phần người Việt thấy quen vì tiếng Việt cũng có \"một CHIẾC áo\", \"một ĐÔI giày\". Mẹo: học lượng từ CÙNG LÚC với danh từ, đừng học tách rời.","ex":[["两件衣服","hai bộ quần áo","liǎng jiàn yīfu"],["一块手表","một chiếc đồng hồ","yí kuài shǒubiǎo"],["三件事情","ba việc","sān jiàn shìqing"]]},{"t":"穿 và 戴 — mặc hay đeo?","b":"穿 cho áo quần giày · 戴 dài cho mũ kính đồng hồ","d":"Tiếng Việt cũng phân biệt \"mặc áo\" với \"đeo đồng hồ\", nên quy tắc này rất dễ nhớ: thứ gì luồn người vào thì 穿, thứ gì gài lên người thì 戴.","ex":[["她穿着白色的衣服。","Cô ấy đang mặc đồ trắng.","Tā chuān zhe báisè de yīfu."],["他戴着一块手表。","Anh ấy đeo một chiếc đồng hồ.","Tā dài zhe yí kuài shǒubiǎo."]]}],"items":[{"zh":"颜色","py":"yánsè","vi":"màu sắc","hv":"nhan sắc","note":"Thú vị: tiếng Việt \"nhan sắc\" nói về vẻ đẹp người, còn tiếng Trung 颜色 chỉ đơn giản là MÀU.","ex":"你喜欢什么颜色？","exPy":"Nǐ xǐhuan shénme yánsè?","exVi":"Bạn thích màu gì?","w":"你 喜欢 什么 颜色？"},{"zh":"白","py":"bái","vi":"trắng","hv":"bạch","note":"Tiếng Việt: \"bạch mã\", \"bạch tuộc\", \"trắng bạch\". Màu trắng ở Trung Quốc gắn với tang lễ.","ex":"我喜欢白色和红色。","exPy":"Wǒ xǐhuan báisè hé hóngsè.","exVi":"Tôi thích màu trắng và màu đỏ.","w":"我 喜欢 白色 和 红色。"},{"zh":"黑","py":"hēi","vi":"đen","hv":"hắc","note":"Có bộ 灬 (lửa) ở dưới — bồ hóng bám đen. Tiếng Việt: \"hắc ám\", \"hắc ín\".","ex":"这件衣服是黑色的。","exPy":"Zhè jiàn yīfu shì hēisè de.","exVi":"Bộ đồ này màu đen.","w":"这 件 衣服 是 黑色 的。"},{"zh":"红","py":"hóng","vi":"đỏ","hv":"hồng","note":"Bộ 纟 (sợi tơ) — màu nhuộm vải. Tiếng Việt: \"hồng\". Đỏ là màu may mắn nhất ở Trung Quốc.","ex":"她今天穿了红色的衣服。","exPy":"Tā jīntiān chuān le hóngsè de yīfu.","exVi":"Hôm nay cô ấy mặc đồ đỏ.","w":"她 今天 穿 了 红色 的 衣服。"},{"zh":"新","py":"xīn","vi":"mới","hv":"tân","note":"Tiếng Việt: \"tân binh\", \"canh tân\", \"tân niên\" (năm mới). Trái nghĩa là 旧 jiù (cũ).","ex":"我买了一件新衣服。","exPy":"Wǒ mǎi le yí jiàn xīn yīfu.","exVi":"Tôi mua một bộ đồ mới.","w":"我 买 了 一 件 新 衣服。"},{"zh":"件","py":"jiàn","vi":"cái, chiếc (lượng từ cho áo, việc)","hv":"kiện","note":"亻 (người) + 牛 (trâu). Tiếng Việt: \"điều kiện\", \"sự kiện\". Dùng cho quần ÁO và công VIỆC.","ex":"一件衣服","exPy":"yí jiàn yīfu","exVi":"một bộ quần áo","w":"一 件 衣服"},{"zh":"穿","py":"chuān","vi":"mặc, đi (giày)","hv":"xuyên","note":"Tiếng Việt: \"xuyên qua\" — mặc áo là luồn người xuyên qua áo. Dùng cho áo, quần, giày.","ex":"她穿了一件红衣服。","exPy":"Tā chuān le yí jiàn hóng yīfu.","exVi":"Cô ấy mặc một bộ đồ đỏ.","w":"她 穿 了 一 件 红 衣服。"},{"zh":"洗","py":"xǐ","vi":"giặt, rửa","hv":"tẩy","note":"Bộ 氵 (nước). Tiếng Việt: \"tẩy rửa\", \"tẩy trắng\". 洗手 = rửa tay, 洗衣服 = giặt đồ.","ex":"我要洗衣服。","exPy":"Wǒ yào xǐ yīfu.","exVi":"Tôi phải giặt quần áo.","w":"我 要 洗 衣服。"},{"zh":"手表","py":"shǒubiǎo","vi":"đồng hồ đeo tay","hv":"thủ biểu","note":"手 (tay) + 表 (mặt đồng hồ, bảng biểu). Nghĩa đen: cái bảng đeo trên tay.","ex":"这块手表多少钱？","exPy":"Zhè kuài shǒubiǎo duōshao qián?","exVi":"Chiếc đồng hồ này bao nhiêu tiền?","w":"这 块 手表 多少 钱？"},{"zh":"手机","py":"shǒujī","vi":"điện thoại di động","hv":"thủ cơ","note":"手 (tay) + 机 (máy) = \"máy cầm tay\". Cách đặt tên rất gọn của tiếng Trung.","ex":"我的手机不见了。","exPy":"Wǒ de shǒujī bú jiàn le.","exVi":"Điện thoại của tôi mất rồi.","w":"我 的 手机 不见 了。"}],"newChars":["颜","色","白","黑","红","穿","洗","手"],"outro":"很好！Xong bài 29."};
G.ROOMS["zh-l030"] = {"id":"zh-l030","lang":"zh","level":1,"no":30,"teacher":"wang","title":"HSK1 · Bài 30 · 买卖和数字 Mua bán và số lớn","intro":["这里卖什么？","Bài 30: Đếm tới hàng nghìn, mặc cả, và dùng 最 để nói \"nhất\". Bấm 1 · Học để bắt đầu."],"introPy":"Zhèlǐ mài shénme?","gram":{"t":"Đọc số từ 100 đến 9999","b":"百 trăm → 千 nghìn · đọc theo từng bậc","d":"235 = 二百三十五. 1800 = 一千八百. Quy tắc giống tiếng Việt, chỉ khác là bậc trăm/nghìn phải nói rõ chứ không lược đi.","ex":[["一百二十","120","yìbǎi èrshí"],["三百五十六","356","sānbǎi wǔshíliù"],["两千零八","2008","liǎngqiān líng bā"]]},"grams":[{"t":"Đọc số từ 100 đến 9999","b":"百 trăm → 千 nghìn · đọc theo từng bậc","d":"235 = 二百三十五. 1800 = 一千八百. Quy tắc giống tiếng Việt, chỉ khác là bậc trăm/nghìn phải nói rõ chứ không lược đi.","ex":[["一百二十","120","yìbǎi èrshí"],["三百五十六","356","sānbǎi wǔshíliù"],["两千零八","2008","liǎngqiān líng bā"]]},{"t":"零 — khi nào phải nói \"linh\"","b":"Có bậc bị TRỐNG ở giữa thì phải chèn 零","d":"Giống hệt tiếng Việt nói \"một trăm linh năm\". 105 = 一百零五. Nhưng 150 = 一百五十 thì không cần vì không có bậc trống ở giữa.","ex":[["一百零五","105 (có bậc chục trống)","yìbǎi líng wǔ"],["一百五十","150 (không cần 零)","yìbǎi wǔshí"],["两千零一","2001","liǎngqiān líng yī"]]},{"t":"最 — so sánh nhất","b":"最 + tính từ","d":"Đặt ngay trước tính từ, không cần gì thêm. Khi có 最 thì KHÔNG dùng 很 nữa: nói 最很好 là sai.","ex":[["这个最便宜。","Cái này rẻ nhất.","Zhège zuì piányi."],["我最喜欢红色。","Tôi thích màu đỏ nhất.","Wǒ zuì xǐhuan hóngsè."]]},{"t":"Bộ câu mặc cả ở chợ Trung Quốc","b":"多少钱？→ 太贵了 → 便宜一点儿吧 → 好，我买了","d":"Ở chợ và cửa hàng nhỏ, mặc cả là chuyện bình thường. Bốn câu này đủ để bạn đi chợ.","ex":[["这个多少钱一公斤？","Cái này bao nhiêu tiền một cân?","Zhège duōshao qián yì gōngjīn?"],["太贵了，便宜一点儿吧。","Đắt quá, rẻ chút đi.","Tài guì le, piányi yìdiǎnr ba."],["好，我买两公斤。","Được, tôi mua hai cân.","Hǎo, wǒ mǎi liǎng gōngjīn."]]}],"items":[{"zh":"卖","py":"mài","vi":"bán","hv":"mại","note":"CẨN THẬN: 买 mǎi (mua, thanh 3) và 卖 mài (bán, thanh 4) chỉ khác một nét trên đầu và một thanh điệu. Chữ 卖 có thêm nét ngang ở trên — hàng bày ra để bán.","ex":"这里卖什么？","exPy":"Zhèlǐ mài shénme?","exVi":"Ở đây bán gì?","w":"这里 卖 什么？"},{"zh":"便宜","py":"piányi","vi":"rẻ","hv":"tiện nghi","note":"Đừng nhầm với \"tiện nghi\" tiếng Việt (đầy đủ tiện ích) — tiếng Trung 便宜 nghĩa là RẺ. Chữ 便 ở đây đọc pián chứ không phải biàn.","ex":"太贵了，便宜一点儿吧。","exPy":"Tài guì le, piányi yìdiǎnr ba.","exVi":"Đắt quá, rẻ chút đi.","w":"太 贵 了， 便宜 一点儿 吧。"},{"zh":"贵","py":"guì","vi":"đắt; quý","hv":"quý","note":"Bộ 贝 (vỏ sò = tiền) ở dưới. Tiếng Việt: \"quý giá\", \"cao quý\". 贵姓 = quý danh (hỏi họ lịch sự).","ex":"这本书不贵，很便宜。","exPy":"Zhè běn shū bú guì, hěn piányi.","exVi":"Quyển sách này không đắt, rất rẻ.","w":"这 本 书 不 贵， 很 便宜。"},{"zh":"票","py":"piào","vi":"vé","hv":"phiếu","note":"Chính là \"phiếu\" tiếng Việt. 飞机票 vé máy bay, 电影票 vé xem phim.","ex":"我买了两张电影票。","exPy":"Wǒ mǎi le liǎng zhāng diànyǐng piào.","exVi":"Tôi mua hai vé xem phim.","w":"我 买 了 两 张 电影 票。"},{"zh":"千","py":"qiān","vi":"nghìn","hv":"thiên","note":"Tiếng Việt: \"thiên niên kỷ\", \"thiên lý\". Chú ý 千 (nghìn) khác 干 (khô) chỉ ở nét phẩy trên đầu.","ex":"飞机票一千八百块。","exPy":"Fēijī piào yìqiān bābǎi kuài.","exVi":"Vé máy bay một nghìn tám trăm đồng.","w":"飞机 票 一 千 八 百 块。"},{"zh":"百","py":"bǎi","vi":"trăm","hv":"bách","note":"Tiếng Việt: \"bách khoa\" (trăm ngành), \"bách hoá\" (trăm mặt hàng).","ex":"两百个人","exPy":"liǎngbǎi ge rén","exVi":"hai trăm người","w":"两 百 个人"},{"zh":"零","py":"líng","vi":"số không","hv":"linh","note":"Có bộ 雨 (mưa) ở trên. Tiếng Việt: \"linh\" trong \"một trăm linh năm\" — dùng y hệt nhau!","ex":"我们学校有两千零五个学生。","exPy":"Wǒmen xuéxiào yǒu liǎngqiān líng wǔ ge xuésheng.","exVi":"Trường tôi có 2005 học sinh.","w":"我们 学校 有 两 千 零 五 个 学生。"},{"zh":"公斤","py":"gōngjīn","vi":"ki-lô-gam","hv":"công cân","note":"公 (chuẩn quốc tế) + 斤 (cân, đơn vị cổ). Một 斤 ở Trung Quốc là nửa ki-lô.","ex":"苹果多少钱一公斤？","exPy":"Píngguǒ duōshao qián yì gōngjīn?","exVi":"Táo bao nhiêu tiền một cân?","w":"苹果 多少 钱 一 公斤？"},{"zh":"两","py":"liǎng","vi":"hai (trước lượng từ)","hv":"lưỡng","note":"Tiếng Việt: \"lưỡng lự\", \"lưỡng cực\". Nhắc lại quy tắc bài 9: đứng trước lượng từ thì dùng 两, đếm số thì dùng 二.","ex":"两个人","exPy":"liǎng ge rén","exVi":"hai người","w":"两 个人"},{"zh":"最","py":"zuì","vi":"nhất, tối","hv":"tối","note":"Tiếng Việt: \"tối đa\", \"tối thiểu\", \"tối cao\" — đều mang nghĩa \"nhất\" này.","ex":"这个最便宜。","exPy":"Zhège zuì piányi.","exVi":"Cái này rẻ nhất.","w":"这个 最 便宜。"}],"newChars":["卖","宜","贵","票","零","斤","两"],"outro":"很好！Xong bài 30."};
G.ROOMS["zh-l031"] = {"id":"zh-l031","lang":"zh","level":1,"no":31,"teacher":"wang","title":"HSK1 · Bài 31 · 点菜 Gọi món","intro":["你们要点什么？","Bài 31: Gọi món ở quán, dùng 要 để yêu cầu, và học bổ ngữ kết quả 完 (làm xong). Bấm 1 · Học để bắt đầu."],"introPy":"Nǐmen yào diǎn shénme?","gram":{"t":"要 và 想 — muốn ở hai mức độ","b":"想 = muốn (mong ước) · 要 = cần, nhất định lấy","d":"Khi gọi món phải dùng 要 vì đó là yêu cầu cụ thể: 我要一碗米饭. Nói 我想一碗米饭 nghe rất kỳ. Ngược lại, ước mơ xa thì dùng 想: 我想去中国.","ex":[["我要一杯咖啡。","Cho tôi một cốc cà phê. (gọi món)","Wǒ yào yì bēi kāfēi."],["我想去中国。","Tôi muốn đi Trung Quốc. (mong ước)","Wǒ xiǎng qù Zhōngguó."],["我不要，谢谢。","Tôi không lấy, cảm ơn.","Wǒ bú yào, xièxie."]]},"grams":[{"t":"要 và 想 — muốn ở hai mức độ","b":"想 = muốn (mong ước) · 要 = cần, nhất định lấy","d":"Khi gọi món phải dùng 要 vì đó là yêu cầu cụ thể: 我要一碗米饭. Nói 我想一碗米饭 nghe rất kỳ. Ngược lại, ước mơ xa thì dùng 想: 我想去中国.","ex":[["我要一杯咖啡。","Cho tôi một cốc cà phê. (gọi món)","Wǒ yào yì bēi kāfēi."],["我想去中国。","Tôi muốn đi Trung Quốc. (mong ước)","Wǒ xiǎng qù Zhōngguó."],["我不要，谢谢。","Tôi không lấy, cảm ơn.","Wǒ bú yào, xièxie."]]},{"t":"完 — bổ ngữ chỉ việc đã LÀM XONG","b":"Động từ + 完 (+ 了)","d":"Ghép ngay sau động từ để nói việc đã hoàn tất: 吃完 ăn xong, 看完 xem xong, 写完 viết xong. Phủ định dùng 没: 我没吃完 (tôi ăn chưa xong).","ex":[["我吃完饭了。","Tôi ăn cơm xong rồi.","Wǒ chī wán fàn le."],["这本书我看完了。","Quyển sách này tôi đọc xong rồi.","Zhè běn shū wǒ kàn wán le."],["我还没写完。","Tôi vẫn chưa viết xong.","Wǒ hái méi xiě wán."]]},{"t":"还 — vẫn còn, và thêm nữa","b":"还 + động từ (vẫn) · 还要 + số lượng (thêm)","d":"Hai nghĩa hay dùng: \"vẫn còn\" (我还在吃) và \"thêm nữa\" (我还要一个). Kết hợp 还没 nghĩa là \"vẫn chưa\".","ex":[["我还在吃饭。","Tôi vẫn đang ăn cơm.","Wǒ hái zài chīfàn."],["我还要一杯茶。","Cho tôi thêm một cốc trà.","Wǒ hái yào yì bēi chá."],["他还没来。","Anh ấy vẫn chưa đến.","Tā hái méi lái."]]}],"items":[{"zh":"鸡蛋","py":"jīdàn","vi":"quả trứng gà","hv":"kê đản","note":"鸡 (gà, có bộ 鸟 chim) + 蛋 (trứng). Tiếng Việt: \"kê\" trong \"kê cân\" (gà), \"đản\" trong \"đản bạch\".","ex":"我要一碗米饭和一个鸡蛋。","exPy":"Wǒ yào yì wǎn mǐfàn hé yí ge jīdàn.","exVi":"Cho tôi một bát cơm và một quả trứng.","w":"我 要 一 碗 米饭 和 一 个 鸡蛋。"},{"zh":"牛奶","py":"niúnǎi","vi":"sữa bò","hv":"ngưu nãi","note":"牛 (bò) + 奶 (sữa, bộ 女). Nghĩa đen là \"sữa bò\", rất dễ đoán.","ex":"我每天早上喝牛奶。","exPy":"Wǒ měi tiān zǎoshang hē niúnǎi.","exVi":"Sáng nào tôi cũng uống sữa.","w":"我 每 天 早上 喝 牛奶。"},{"zh":"咖啡","py":"kāfēi","vi":"cà phê","hv":"ca phê","note":"Từ mượn phiên âm, giống hệt \"cà phê\" tiếng Việt. Cả hai chữ đều có bộ 口 vì chỉ mượn âm.","ex":"我想喝一杯咖啡。","exPy":"Wǒ xiǎng hē yì bēi kāfēi.","exVi":"Tôi muốn uống một cốc cà phê.","w":"我 想 喝 一 杯 咖啡。"},{"zh":"羊肉","py":"yángròu","vi":"thịt dê, thịt cừu","hv":"dương nhục","note":"羊 (dê, bộ thủ đã học) + 肉 (thịt). Ghép tên con vật + 肉 là ra tên thịt: 牛肉, 鸡肉, 鱼肉.","ex":"我不吃羊肉。","exPy":"Wǒ bù chī yángròu.","exVi":"Tôi không ăn thịt dê.","w":"我 不 吃 羊肉。"},{"zh":"西瓜","py":"xīguā","vi":"dưa hấu","hv":"tây qua","note":"西 (phía tây) + 瓜 (quả bí, dưa) — loại dưa từ phương tây truyền vào.","ex":"夏天的西瓜很甜。","exPy":"Xiàtiān de xīguā hěn tián.","exVi":"Dưa hấu mùa hè rất ngọt.","w":"夏天 的 西瓜 很 甜。"},{"zh":"鱼","py":"yú","vi":"con cá","hv":"ngư","note":"Bộ thủ đã học ở phần bộ thủ. Tiếng Việt: \"ngư dân\", \"ngư nghiệp\".","ex":"这个鱼太好吃了！","exPy":"Zhège yú tài hǎochī le!","exVi":"Con cá này ngon quá!","w":"这个 鱼 太 好吃 了！"},{"zh":"好吃","py":"hǎochī","vi":"ngon (đồ ăn)","hv":"hảo cật","note":"Nhắc lại quy tắc bài 9: 好 + động từ giác quan. 好吃 ngon, 好喝 ngon (uống), 好看 đẹp, 好听 hay.","ex":"太好吃了！","exPy":"Tài hǎochī le!","exVi":"Ngon quá!","w":"太 好吃 了！"},{"zh":"要","py":"yào","vi":"muốn, cần; sẽ","hv":"yếu","note":"Tiếng Việt: \"yêu cầu\", \"cần yếu\". Mạnh hơn 想 — 想 là \"muốn\", 要 là \"cần / nhất định lấy\".","ex":"你们要点什么？","exPy":"Nǐmen yào diǎn shénme?","exVi":"Các bạn gọi món gì?","w":"你们 要点 什么？"},{"zh":"完","py":"wán","vi":"xong, hết","hv":"hoàn","note":"Bộ 宀 (mái nhà). Tiếng Việt: \"hoàn thành\", \"hoàn tất\". Chủ yếu dùng làm bổ ngữ sau động từ.","ex":"我吃完了，你呢？","exPy":"Wǒ chī wán le, nǐ ne?","exVi":"Tôi ăn xong rồi, còn bạn?","w":"我 吃 完 了， 你 呢？"},{"zh":"还","py":"hái","vi":"còn, vẫn; thêm nữa","hv":"hoàn","note":"Có bộ 辶 (đi đường). Đọc hái nghĩa là \"còn, vẫn\"; đọc huán nghĩa là \"trả lại\" (还书 trả sách).","ex":"我还没吃完。","exPy":"Wǒ hái méi chī wán.","exVi":"Tôi vẫn chưa ăn xong.","w":"我 还 没 吃 完。"}],"newChars":["鸡","蛋","牛","奶","咖","啡","羊","肉","瓜","鱼","完","还"],"outro":"很好！Xong bài 31."};
G.ROOMS["zh-l038"] = {"id":"zh-l038","lang":"zh","level":1,"no":38,"teacher":"wang","title":"HSK1 · Bài 38 · 今天的天气 Thời tiết và tin tức","intro":["今天天气怎么样？","Bài 38: Nói thời tiết đầy đủ, phân biệt 知道 với 认识, 说 với 告诉 — và khép lại HSK 2. Bấm 1 · Học để bắt đầu."],"introPy":"Jīntiān tiānqì zěnmeyàng?","gram":{"t":"知道 và 认识 — biết việc hay quen người?","b":"知道 + thông tin · 认识 + người","d":"Lỗi rất phổ biến. 我认识他 = tôi quen anh ấy (đã gặp mặt). 我知道他 = tôi biết anh ấy (nghe tên, chưa chắc quen). Nói 我知道这个字 nghĩa là biết chữ đó, còn 我认识这个字 nghĩa là nhận ra mặt chữ — cả hai đều dùng được với chữ viết.","ex":[["我认识他，他是我的同学。","Tôi quen anh ấy, anh ấy là bạn cùng lớp.","Wǒ rènshi tā, tā shì wǒ de tóngxué."],["我知道他的名字。","Tôi biết tên anh ấy.","Wǒ zhīdào tā de míngzi."],["我不知道。","Tôi không biết.","Wǒ bù zhīdào."]]},"grams":[{"t":"知道 và 认识 — biết việc hay quen người?","b":"知道 + thông tin · 认识 + người","d":"Lỗi rất phổ biến. 我认识他 = tôi quen anh ấy (đã gặp mặt). 我知道他 = tôi biết anh ấy (nghe tên, chưa chắc quen). Nói 我知道这个字 nghĩa là biết chữ đó, còn 我认识这个字 nghĩa là nhận ra mặt chữ — cả hai đều dùng được với chữ viết.","ex":[["我认识他，他是我的同学。","Tôi quen anh ấy, anh ấy là bạn cùng lớp.","Wǒ rènshi tā, tā shì wǒ de tóngxué."],["我知道他的名字。","Tôi biết tên anh ấy.","Wǒ zhīdào tā de míngzi."],["我不知道。","Tôi không biết.","Wǒ bù zhīdào."]]},{"t":"说 và 告诉 — nói và nói CHO AI","b":"说 + nội dung · 告诉 + người + nội dung","d":"说 không đi trực tiếp với người: nói 我说他 là sai. Muốn nói với ai thì dùng 告诉他 hoặc 跟他说.","ex":[["他说他很忙。","Anh ấy nói anh ấy bận.","Tā shuō tā hěn máng."],["请告诉我。","Xin nói cho tôi biết.","Qǐng gàosu wǒ."],["我想跟你说一件事。","Tôi muốn nói với bạn một việc.","Wǒ xiǎng gēn nǐ shuō yí jiàn shì."]]},{"t":"再 và 又 — lại lần nữa, nhưng khác thì","b":"再 = việc CHƯA xảy ra · 又 yòu = việc ĐÃ xảy ra","d":"请再说一次 (xin nói lại — sắp làm). 他又来了 (anh ấy lại đến nữa rồi — đã làm). Đây là điểm phân biệt kinh điển của HSK 2.","ex":[["请再说一次。","Xin nói lại lần nữa. (chưa nói)","Qǐng zài shuō yí cì."],["他昨天又来了。","Hôm qua anh ấy lại đến. (đã đến)","Tā zuótiān yòu lái le."],["明天再见！","Mai gặp lại!","Míngtiān zàijiàn!"]]},{"t":"Bộ từ nói về thời tiết","b":"晴天 · 阴天 · 下雨 · 下雪 · 很冷 · 很热","d":"Chú ý mưa và tuyết là ĐỘNG TỪ trong tiếng Trung (下雨, 下雪), còn nắng và âm u là TÍNH TỪ. Hỏi thời tiết: 今天天气怎么样？","ex":[["今天是晴天。","Hôm nay trời nắng.","Jīntiān shì qíngtiān."],["昨天下雪了。","Hôm qua có tuyết.","Zuótiān xià xuě le."],["明天可能下雨。","Mai có thể mưa.","Míngtiān kěnéng xiàyǔ."]]}],"items":[{"zh":"晴","py":"qíng","vi":"trời nắng, quang đãng","hv":"tình","note":"日 (mặt trời) + 青 (xanh) = mặt trời trên nền trời xanh. Chữ tượng hình rất đẹp.","ex":"今天是晴天，很暖和。","exPy":"Jīntiān shì qíngtiān, hěn nuǎnhuo.","exVi":"Hôm nay trời nắng, rất ấm.","w":"今天 是 晴 天， 很 暖和。"},{"zh":"阴","py":"yīn","vi":"trời âm u, nhiều mây","hv":"âm","note":"Tiếng Việt: \"âm u\", \"âm dương\". Cặp 晴 / 阴 giống cặp \"nắng / râm\".","ex":"今天天气很阴。","exPy":"Jīntiān tiānqì hěn yīn.","exVi":"Hôm nay trời âm u.","w":"今天 天气 很 阴。"},{"zh":"雪","py":"xuě","vi":"tuyết","hv":"tuyết","note":"Chính là \"tuyết\" tiếng Việt. Bộ 雨 (mưa) ở trên — mưa đông lại thành tuyết. 下雪 = trời có tuyết.","ex":"去年冬天下了很多雪。","exPy":"Qùnián dōngtiān xià le hěn duō xuě.","exVi":"Mùa đông năm ngoái tuyết rơi nhiều.","w":"去年 冬天 下 了 很 多 雪。"},{"zh":"日","py":"rì","vi":"ngày; mặt trời","hv":"nhật","note":"Dạng VIẾT trang trọng của 号: 九月二日 (viết) = 九月二号 (nói). Cũng có trong 日本 (Nhật Bản).","ex":"九月二日","exPy":"jiǔ yuè èr rì","exVi":"ngày 2 tháng 9","w":"九 月 二 日"},{"zh":"去年","py":"qùnián","vi":"năm ngoái","hv":"khứ niên","note":"去 (đã qua) + 年 (năm). Bộ ba: 去年 (năm ngoái), 今年 (năm nay), 明年 (năm sau).","ex":"我去年去过北京。","exPy":"Wǒ qùnián qù guo Běijīng.","exVi":"Năm ngoái tôi đã đi Bắc Kinh.","w":"我 去年 去 过 北京。"},{"zh":"再","py":"zài","vi":"lại, lần nữa (việc CHƯA xảy ra)","hv":"tái","note":"Tiếng Việt: \"tái diễn\", \"tái bản\", \"tái kiến\" (再见). Dùng cho việc sắp lặp lại.","ex":"对不起，我没听清楚，请再说一次。","exPy":"Duìbuqǐ, wǒ méi tīng qīngchu, qǐng zài shuō yí cì.","exVi":"Xin lỗi, tôi nghe chưa rõ, xin nói lại lần nữa.","w":"对不起， 我 没 听 清楚， 请 再说 一 次。"},{"zh":"错","py":"cuò","vi":"sai, nhầm","hv":"thác","note":"Bộ 钅 (kim loại). Trái nghĩa với 对. 不错 nghĩa là \"không tệ, khá đấy\" — một lời khen!","ex":"这个字我写错了。","exPy":"Zhège zì wǒ xiě cuò le.","exVi":"Chữ này tôi viết sai rồi.","w":"这个 字 我 写 错 了。"},{"zh":"说","py":"shuō","vi":"nói","hv":"thuyết","note":"Tiếng Việt: \"thuyết minh\", \"diễn thuyết\", \"tiểu thuyết\". Bộ 讠 (lời nói).","ex":"他说汉语说得很好。","exPy":"Tā shuō Hànyǔ shuō de hěn hǎo.","exVi":"Anh ấy nói tiếng Trung rất giỏi.","w":"他 说 汉语 说 得 很 好。"},{"zh":"知道","py":"zhīdào","vi":"biết (thông tin)","hv":"tri đạo","note":"Tiếng Việt: \"tri thức\", \"thông tri\". Biết một SỰ VIỆC — khác 认识 (quen một NGƯỜI).","ex":"我不知道他在哪儿。","exPy":"Wǒ bù zhīdào tā zài nǎr.","exVi":"Tôi không biết anh ấy ở đâu.","w":"我 不 知道 他 在 哪儿。"},{"zh":"报纸","py":"bàozhǐ","vi":"báo giấy","hv":"báo chỉ","note":"报 chính là \"báo\" tiếng Việt (\"báo cáo\", \"tờ báo\"). 纸 = \"chỉ\" (giấy), có bộ 纟 (sợi).","ex":"爸爸每天早上看报纸。","exPy":"Bàba měi tiān zǎoshang kàn bàozhǐ.","exVi":"Sáng nào bố cũng đọc báo.","w":"爸爸 每 天 早上 看 报纸。"}],"newChars":["晴","阴","雪","错","知","报","纸"],"outro":"很好！Xong bài 38."};
